window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["sugar1"]={"id": "sugar1", "title": "第六章 糖代谢", "sub": "93页教材逐页详解 · 86张概念图 · 24道考题", "sub2": "糖分类 · 无氧酵解(EMP) · 有氧分解(TCA) · 磷酸戊糖途径", "modules": [{"i": 0, "name": "模块一：糖的分类与消化", "slides": [{"i": 0, "sec": "第六章 糖代谢", "title": "第六章 糖代谢 (p1)", "notes": "College of Life Sciences, CNU。\u000b第六章 糖代谢。\u000b本章涵盖：糖的分类与结构→消化降解→无氧酵解(EMP)→有氧分解(TCA)→磷酸戊糖途径(PPP)。", "page": 1, "level": "掌握", "img": "assets/img/sugar1/p001.jpg", "anim": null, "fig": "", "points": ["①糖代谢主线：分类结构→消化→EMP→TCA→PPP", "②EMP为无氧酵解，TCA为有氧分解", "③PPP即磷酸戊糖途径，本章五大板块"], "check": null, "cards": null}, {"i": 1, "sec": "第六章 糖代谢", "title": "糖的分类和结构 章节页 (p2)", "notes": "复习：糖的分类。\u000b按组成：单糖(不能水解的最简单糖)→寡糖(2-10个单糖)→多糖(多个单糖)。\u000b按基团：同多糖(同种单糖基)vs杂多糖(不同单糖基)。\u000b按功能：分解代谢vs合成代谢。", "page": 2, "level": "掌握", "img": "assets/img/sugar1/p002.jpg", "anim": null, "fig": "", "points": ["①按组成：单糖→寡糖(2-10)→多糖", "②按基团：同多糖vs杂多糖", "③按功能：分解代谢vs合成代谢"], "check": null, "cards": null}, {"i": 2, "sec": "第六章 糖代谢", "title": "糖的分类详解 (p3-p4) (p3)", "notes": "⚫单糖结构：多羟基醛/酮。\u000b⚫分类依据：醛基→醛糖(葡萄糖)，酮基→酮糖(果糖)。\u000b⚫碳数：最简单为丙糖(甘油醛/二羟丙酮)，最常见为己糖。\u000b⚫多糖：同多糖=相同单糖基(淀粉/糖原/纤维素)；\u000b杂多糖=不同单糖基。", "page": 3, "level": "掌握", "img": "assets/img/sugar1/p003.jpg", "anim": null, "fig": "", "points": ["①单糖=多羟基醛或酮", "②醛基为醛糖，酮基为酮糖", "③丙糖最简单，己糖最常见", "④同多糖同种单糖基，杂多糖不同"], "check": null, "cards": null}, {"i": 3, "sec": "第六章 糖代谢", "title": "单糖构型-手性碳原子 (p5)", "notes": "⚫手性碳(C*)：连4个不同基团的不对称四面体C。\u000b⚫构型：原子在空间的相对排列(改变需断共价键)。\u000b⚫L型/D型：以距羰基最远C*的OH方向定——OH在右=D型，OH在左=L型。\u000b⚫L型与D型互为对映体(镜像不重叠)。", "page": 5, "level": "掌握", "img": "assets/img/sugar1/p005.jpg", "anim": null, "fig": "", "points": ["①手性碳：连4个不同基团的C", "②构型改变需断共价键", "③OH在右为D型，在左为L型", "④L与D互为对映体(镜像不重叠)"], "check": null, "cards": null}, {"i": 4, "sec": "第六章 糖代谢", "title": "葡萄糖立体异构体 (p6)", "notes": "葡萄糖C2/C3/C4/C5均为手性中心→2^4=16种立体异构体。\u000b其中L-葡萄糖是D-葡萄糖的对映体，其余14个为D-葡萄糖的非对映体。\u000b所有单糖(二羟丙酮除外)均含≥1个C*。\u000bC*数决定异构体数。", "page": 6, "level": "掌握", "img": "assets/img/sugar1/p006.jpg", "anim": null, "fig": "", "points": ["①葡萄糖有C2-C5共4个手性碳", "②异构体数=2^4=16种", "③L-葡萄糖是D-葡萄糖的对映体", "④其余14个为D-葡萄糖的非对映体"], "check": null, "cards": null}, {"i": 5, "sec": "第六章 糖代谢", "title": "差向异构体 (p7)", "notes": "⚫差向异构体：同碳数、仅一个C*构型不同的异构体。\u000b例子：D-葡萄糖 vs D-甘露糖(C2差向)；\u000bD-葡萄糖 vs D-半乳糖(C4差向)。\u000b它们是D-葡萄糖的C2/C4差向异构体，性质相似但酶催化反应不同。", "page": 7, "level": "掌握", "img": "assets/img/sugar1/p007.jpg", "anim": null, "fig": "", "points": ["①差向异构体：仅一个C*构型不同", "②葡萄糖vs甘露糖=C2差向", "③葡萄糖vs半乳糖=C4差向", "④性质相似但酶催化反应不同"], "check": null, "cards": null}, {"i": 6, "sec": "第六章 糖代谢", "title": "D-醛糖结构全表 (p8)", "notes": "D-甘油醛→D-赤藓糖→D-苏糖→D-核糖/D-阿拉伯糖/D-木糖/D-来苏糖→D-葡萄糖/甘露糖/古洛糖/艾杜糖/半乳糖/塔洛糖等。\u000b排列规律：从甘油醛开始逐级增长C链，每增一个C*使立体异构体翻倍。\u000b自然界单糖绝大多数为D型。", "page": 8, "level": "理解", "img": "assets/img/sugar1/p008.jpg", "anim": null, "fig": "", "points": ["①D-醛糖从甘油醛逐级增长碳链", "②每增一个C*，异构体数翻倍", "③自然界单糖绝大多数为D型"], "check": null, "cards": null}, {"i": 7, "sec": "第六章 糖代谢", "title": "D-酮糖结构全表 (p9)", "notes": "酮糖比同C数的醛糖少一个C*。\u000b从二羟丙酮(无C*)开始→D-赤藓酮糖→D-核酮糖/D-木酮糖→D-果糖/D-山梨糖/D-塔格糖/D-阿洛酮糖。\u000b酮糖的C2为酮基(C=O)，醛糖的C1为醛基(-CHO)。", "page": 9, "level": "理解", "img": "assets/img/sugar1/p009.jpg", "anim": null, "fig": "", "points": ["①酮糖比同碳数醛糖少一个C*", "②二羟丙酮无C*，是最简单酮糖", "③酮糖C2为酮基，醛糖C1为醛基"], "check": null, "cards": null}, {"i": 8, "sec": "第六章 糖代谢", "title": "单糖环状结构 (p10)", "notes": "自然界戊糖和己糖以链式和环式共存。\u000b环化后羰基C变为异头碳：α-D-葡萄糖(异头C-OH反式) vs β-D-葡萄糖(顺式)；\u000bα-D-果糖 vs β-D-果糖。\u000b六元环=吡喃(pyran)型，五元环=呋喃(furan)型。", "page": 10, "level": "掌握", "img": "assets/img/sugar1/p010.jpg", "anim": null, "fig": "", "points": ["①自然界戊糖、己糖以链式和环式共存", "②环化后羰基C变为异头碳，产生α/β两种构型", "③六元环为吡喃型，五元环为呋喃型", "④α-OH反式、β-OH顺式（以葡萄糖为例）"], "check": null, "cards": null}, {"i": 9, "sec": "第六章 糖代谢", "title": "异头碳与变旋 (p11)", "notes": "⚫异头碳：连接半缩醛羟基的C(环化后新产生的手性中心)。\u000b⚫异头物：α(异头C-OH与末端-CH2OH反式)vs β(顺式)。\u000b⚫变旋：α和β在溶液中通过开链互变→比旋光度变化直至平衡。\u000b⚫半缩醛羟基参与糖苷键后→不再有还原性。", "page": 11, "level": "掌握", "img": "assets/img/sugar1/p011.jpg", "anim": null, "fig": "", "points": ["①异头碳=环化后连接半缩醛羟基的新手性C", "②α/β异头物由异头C-OH与末端-CH2OH取向决定", "③变旋：α、β经开链互变，比旋光度渐变至平衡", "④半缩醛羟基成糖苷键后即失去还原性"], "check": null, "cards": null}, {"i": 10, "sec": "第六章 糖代谢", "title": "单糖的氧化 (p12)", "notes": "还原糖(含游离醛基)→被弱氧化剂直接氧化。\u000bFehling试剂和Benedict试剂均为碱性铜试剂→还原糖使Cu2+→Cu2O红色沉淀。\u000bCu2O颜色/量可用于定量检测还原糖。\u000b单糖→醛糖酸(氧化产物)。", "page": 12, "level": "掌握", "img": "assets/img/sugar1/p012.jpg", "anim": null, "fig": "", "points": ["①还原糖含游离醛基，可被弱氧化剂氧化", "②Fehling/Benedict为碱性铜试剂，生成Cu2O红色沉淀", "③Cu2O颜色或量可定量检测还原糖", "④单糖氧化产物为醛糖酸"], "check": null, "cards": null}, {"i": 11, "sec": "第六章 糖代谢", "title": "单糖的构象 (p13)", "notes": "⚫构象：绕单键旋转产生的不同空间排列(不涉及共价键断裂)。\u000b⚫六元环两种构象：椅式(最稳定)和船式。\u000b椅式中大体积基团(H/OH)尽可能占据平伏键(e键)更稳定。\u000b构象影响糖分子的化学反应活性。", "page": 13, "level": "理解", "img": "assets/img/sugar1/p013.jpg", "anim": null, "fig": "", "points": ["①构象是单键旋转产生的空间排列，不涉及共价键断裂", "②六元环有椅式和船式，椅式最稳定", "③大基团(H/OH)优先占平伏键(e键)更稳定", "④构象影响糖的化学反应活性"], "check": null, "cards": null}, {"i": 12, "sec": "第六章 糖代谢", "title": "寡糖-麦芽糖 (p14)", "notes": "⚫寡糖：2~10个单糖以糖苷键相连。\u000b⚫麦芽糖：2个葡萄糖通过α-1,4糖苷键连接。\u000b⚫具有游离半缩醛羟基→有还原性——该端为还原端。\u000b半缩醛羟基一旦参与糖苷键形成→不再具还原性。", "page": 14, "level": "掌握", "img": "assets/img/sugar1/p014.jpg", "anim": null, "fig": "", "points": ["①寡糖为2~10个单糖经糖苷键相连", "②麦芽糖=2个葡萄糖经α-1,4糖苷键连接", "③有游离半缩醛羟基→有还原性，该端为还原端", "④半缩醛羟基参与成苷后即无还原性"], "check": null, "cards": null}, {"i": 13, "sec": "第六章 糖代谢", "title": "纤维二糖与蔗糖 (p15)", "notes": "⚫纤维二糖：2个葡萄糖由β-1,4糖苷键连接→有游离半缩醛羟基→有还原性。\u000b⚫蔗糖：葡萄糖(α1)+果糖(β2)，两个异头碳均参与糖苷键→无游离半缩醛羟基→无还原性！\u000b教材经典判断考点。", "page": 15, "level": "掌握", "img": "assets/img/sugar1/p015.jpg", "anim": null, "fig": "", "points": ["①纤维二糖：β-1,4糖苷键，有游离半缩醛羟基→还原性", "②蔗糖：葡萄糖α1与果糖β2，两异头碳均成苷", "③蔗糖无游离半缩醛羟基→无还原性（经典考点）"], "check": null, "cards": null}, {"i": 14, "sec": "第六章 糖代谢", "title": "多糖分类 (p16)", "notes": "⚫多糖：成百上千个单糖以糖苷键相连的高聚体。\u000b⚫同多糖：相同单糖基(淀粉/糖原/纤维素/几丁质)。\u000b⚫杂多糖：不同单糖基(透明质酸/硫酸软骨素/肝素)。\u000b⚫自然界最常见多糖：淀粉(植物)、糖原(动物)、纤维素(植物)。", "page": 16, "level": "掌握", "img": "assets/img/sugar1/p016.jpg", "anim": null, "fig": "", "points": ["①多糖为成百上千单糖经糖苷键连成的高聚体", "②同多糖：淀粉、糖原、纤维素、几丁质", "③杂多糖：透明质酸、硫酸软骨素、肝素", "④最常见多糖：淀粉(植物)、糖原(动物)、纤维素(植物)"], "check": null, "cards": null}, {"i": 15, "sec": "第六章 糖代谢", "title": "淀粉与糖原结构 (p17)", "notes": "直链淀粉(α-1,4无分支)vs支链淀粉(α-1,4+α-1,6分支，每25-30单位一分支)。\u000b糖原：每8-12个葡萄糖单位一个α-1,6分支→高度分支化→肝湿重~10%→利于快速动员。\u000b分支越密→降解速度越快。", "page": 17, "level": "掌握", "img": "assets/img/sugar1/p017.jpg", "anim": null, "fig": "", "points": ["①直链淀粉仅α-1,4；支链淀粉含α-1,4和α-1,6分支", "②支链淀粉每25~30个葡萄糖单位一分支", "③糖原每8~12个葡萄糖单位一分支，高度分支", "④分支越密→降解动员越快，肝糖原约占肝湿重10%"], "check": null, "cards": null}, {"i": 16, "sec": "第六章 糖代谢", "title": "糖代谢总览 (p18)", "notes": "糖代谢全景：分解←→合成。\u000b分解：酵解(EMP)→TCA→PPP→乙醛酸途径→糖醛酸途径。\u000b合成：糖原异生作用+淀粉/糖原的合成。\u000b代谢网络将糖/脂/蛋白质/核酸四大物质联系在一起。", "page": 18, "level": "理解", "img": "assets/img/sugar1/p018.jpg", "anim": null, "fig": "", "points": ["①糖代谢分分解与合成两大方向", "②分解：EMP、TCA、PPP、乙醛酸、糖醛酸途径", "③合成：糖异生+淀粉/糖原合成", "④糖代谢联系脂、蛋白、核酸代谢"], "check": null, "cards": null}, {"i": 17, "sec": "第六章 糖代谢", "title": "第一节-多糖和低聚糖的降解 (p19)", "notes": "第一节标题页：多糖和低聚糖的降解。\u000b内容：一、动物体内糖的消化、吸收、转运和贮存；\u000b二、糖原的酶促降解。\u000b从食物淀粉到细胞内糖原的完整消化链条。", "page": 19, "level": "掌握", "img": "assets/img/sugar1/p019.jpg", "anim": null, "fig": "", "points": ["①本节讲多糖与低聚糖的降解", "②内容一：糖的消化、吸收、转运与贮存", "③内容二：糖原的酶促降解", "④主线：食物淀粉→细胞内糖原"], "check": null, "cards": null}, {"i": 18, "sec": "第六章 糖代谢", "title": "淀粉的消化 (p20)", "notes": "⚫α-淀粉酶：水解α-1,4糖苷键(任意端/内切)→糊精+麦芽糖。\u000b⚫β-淀粉酶(植物)：从非还原端切α-1,4键→麦芽糖。\u000b⚫α-糊精酶(异麦芽糖酶)：水解α-1,6分支点→葡萄糖。\u000b⚫终点酶：麦芽糖酶→G+G；\u000b蔗糖酶→G+F；\u000b乳糖酶→G+Gal。", "page": 20, "level": "掌握", "img": "assets/img/sugar1/p020.jpg", "anim": null, "fig": "", "points": ["①α-淀粉酶内切α-1,4键→糊精+麦芽糖", "②β-淀粉酶从非还原端切α-1,4键→麦芽糖", "③α-糊精酶水解α-1,6分支点", "④终点酶：麦芽糖酶、蔗糖酶、乳糖酶"], "check": null, "cards": null}, {"i": 19, "sec": "第六章 糖代谢", "title": "单糖的吸收与转运 (p21)", "notes": "食物多糖消化→单糖(G/F/Gal)吸收入血→门静脉→肝脏。\u000b肝中：F→G(Gluconeogenic作用)。\u000b肝糖元(~20%)储存于肝；\u000b肌糖元(~80%)储存于肌肉。\u000b血糖维持恒定供全身利用。", "page": 21, "level": "掌握", "img": "assets/img/sugar1/p021.jpg", "anim": null, "fig": "", "points": ["①多糖消化为单糖经门静脉入肝", "②肝中果糖转变为葡萄糖", "③肝糖原约20%，肌糖原约80%", "④血糖恒定供全身利用"], "check": null, "cards": null}, {"i": 20, "sec": "第六章 糖代谢", "title": "糖原的酶促降解 (p22)", "notes": "⚫磷酸化酶(90%)：切α-1,4糖苷键→G-1-P(需PLP辅酶，不可逆)。\u000b⚫糖基转移酶+脱支酶(10%)：处理α-1,6分支→游离G。\u000b⚫G-1-P→磷酸葡萄糖变位酶→G-6-P→进入酵解途径。\u000b磷酸化酶受激素调控(肾上腺素、胰高血糖素)。", "page": 22, "level": "掌握", "img": "assets/img/sugar1/p022.jpg", "anim": null, "fig": "", "points": ["①磷酸化酶切α-1,4键→G-1-P，需PLP", "②脱支酶处理α-1,6分支释放游离G", "③G-1-P经变位酶→G-6-P进入酵解", "④磷酸化酶受肾上腺素、胰高血糖素调控"], "check": null, "cards": null}, {"i": 21, "sec": "第六章 糖代谢", "title": "磷酸化酶降解机制 (p23)", "notes": "磷酸化酶：加入Pi切α-1,4键→产生G-1-P。\u000b每切一个残基→糖原少一个Glc。\u000b直至距分支点4个残基处停止→由脱支酶接手。\u000b图中显示：磷酸化酶→少一个葡萄糖残基的糖原+G-1-P的循环。", "page": 23, "level": "掌握", "img": "assets/img/sugar1/p023.jpg", "anim": null, "fig": "图示磷酸化酶循环：糖原每释放一个G-1-P即减少一个葡萄糖残基，直至接近分支点（约4个残基）停止，交由脱支酶处理。", "points": ["①磷酸化酶加Pi切α-1,4键生成G-1-P", "②每切一次糖原少一个葡萄糖残基", "③距分支点4个残基处停止", "④由脱支酶接手继续降解"], "check": null, "cards": null}], "mcq": [{"id": "sugar1_mcq_1", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "手性碳原子的定义是什么？", "o": ["A. 连接4个相同基团的C", "B. 连接4个不同原子/基团的四面体C", "C. 不饱和C原子", "D. 连接羟基的C"], "a": "B", "e": "C*连接4个不同基团→失去对称性→具有2个光学异构体。n个C*有2^n个立体异构体。", "kp": "sugar1_s0_3"}, {"id": "sugar1_mcq_2", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "D型和L型单糖的判断依据是什么？", "o": ["A. 旋光性", "B. 距羰基最远的C*上-OH方向:右=D,左=L", "C. 碳链长度", "D. 醛基位置"], "a": "B", "e": "以距羰基最远的C*的OH方向定:OH在右=D型。自然界绝大多数单糖为D型。", "kp": "sugar1_s0_10"}, {"id": "sugar1_mcq_3", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "葡萄糖有多少种立体异构体？", "o": ["A. 8种,3个C*", "B. 16种,C2/C3/C4/C5 4个C*", "C. 32种,5个C*", "D. 4种,2个C*"], "a": "B", "e": "葡萄糖C2/C3/C4/C5共4个C*→2^4=16种立体异构体。L-Glc是对映体,其余14个为非对映体。", "kp": "sugar1_s0_4"}, {"id": "sugar1_mcq_4", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "D-葡萄糖和D-甘露糖是什么关系？", "o": ["A. 对映体", "B. C2差向异构体", "C. C4差向异构体", "D. 结构异构体"], "a": "B", "e": "D-甘露糖是D-Glc的C2差向异构体。D-半乳糖是C4差向异构体。仅一个C*构型不同即差向异构体。", "kp": "sugar1_s0_4"}, {"id": "sugar1_mcq_5", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "什么叫变旋现象？", "o": ["A. 单糖溶液比旋光度随时间变化至平衡", "B. 糖分子旋转", "C. 糖氧化还原", "D. 糖苷键断裂"], "a": "A", "e": "a和b异头物在溶液中通过开链互变→比旋光度随时间变化→最终达平衡(a:36%,b:64%)。", "kp": "sugar1_s0_9"}, {"id": "sugar1_mcq_6", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "Fehling试剂检测什么？", "o": ["A. 蛋白质", "B. 还原糖(游离醛基使Cu2+→Cu2O红色沉淀)", "C. 脂肪", "D. 核酸"], "a": "B", "e": "碱性铜试剂→还原糖的醛基将Cu2+→Cu+→Cu2O红色沉淀。用于尿糖检测。", "kp": "sugar1_s0_10"}, {"id": "sugar1_mcq_7", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "吡喃型vs呋喃型糖的区别？", "o": ["A. 吡喃=六元环,呋喃=五元环", "B. 都是六元环", "C. 都是五元环", "D. 吡喃=五元环,呋喃=六元环"], "a": "A", "e": "葡萄糖主成吡喃(C1-C5连接六元环);果糖可成呋喃(C2-C5连接五元环)。环化后产生新的C*—异头碳。", "kp": "sugar1_s0_1"}, {"id": "sugar1_mcq_8", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "椅式构象与船式构象的关系？", "o": ["A. 均为低能构象", "B. 椅式最稳定(平伏键多),船式能量较高", "C. 船式最稳定", "D. 完全相同"], "a": "B", "e": "六元环糖以椅式为主→大体积基团占平伏键→能量低。船式有空间排斥→极少量存在。", "kp": "sugar1_s0_11"}, {"id": "sugar1_mcq_9", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "直链淀粉和支链淀粉的区别？", "o": ["A. 直链a-1,4无分支;支链含a-1,6(每25-30单位一分支)", "B. 完全相同", "C. 直链含a-1,6,支链不含", "D. 都是蛋白质"], "a": "A", "e": "直链淀粉:a-1,4线性。支链淀粉:a-1,4+a-1,6分支。糖原:每8-12单位一分支→高度分支利于快速动员。", "kp": "sugar1_s0_15"}, {"id": "sugar1_mcq_10", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "半缩醛羟基参与糖苷键后有何变化？", "o": ["A. 仍有还原性", "B. 失去还原性,因半缩醛羟基已被取代", "C. 变为酮糖", "D. 变为多糖"], "a": "B", "e": "半缩醛羟基一旦参与糖苷键→不再有还原性。多糖只有一个还原端(末端的游离半缩醛羟基)。", "kp": "sugar1_s0_9"}, {"id": "sugar1_mcq_11", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖原磷酸化酶需要什么辅酶？", "o": ["A. TPP", "B. PLP(磷酸吡哆醛)", "C. NAD+", "D. FAD"], "a": "B", "e": "磷酸化酶含PLP,VB6衍生物。PLP稳定酶构象,不直接催化。VB6缺乏→糖原降解障碍。", "kp": "sugar1_s0_21"}, {"id": "sugar1_mcq_12", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "体内糖原主要储存在哪里？", "o": ["A. 脑", "B. 肝脏(~20%)和肌肉(~80%)", "C. 血液", "D. 脂肪组织"], "a": "B", "e": "肝糖元~20%维持血糖;肌糖元~80%供肌肉自身用。肌肉无葡糖-6-磷酸酶→不能直接释G到血。", "kp": "sugar1_s0_15"}, {"id": "sugar1_mcq_13", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "a-淀粉酶和a-糊精酶作用的区别？", "o": ["A. 均水解a-1,4键", "B. a-淀粉酶切a-1,4键,a-糊精酶切a-1,6键", "C. 均水解a-1,6键", "D. 均为蛋白酶"], "a": "B", "e": "a-淀粉酶→水解a-1,4糖苷键→糊精+麦芽糖。a-糊精酶→专门水解a-1,6分支键→游离Glc。", "kp": "sugar1_s0_18"}, {"id": "sugar1_mcq_14", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖酵解三个不可逆酶？", "o": ["A. 己糖激酶/醛缩酶/PK", "B. 己糖激酶/PFK-1/丙酮酸激酶", "C. PFK-1/GAPDH/PK", "D. 己糖激酶/PGK/PK"], "a": "B", "e": "三大不可逆=三大调控点:①己糖激酶③PFK⑩PK。PGK和GAPDH是可逆的!", "kp": "sugar1_s0_20"}, {"id": "sugar1_mcq_15", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖酵解净产？", "o": ["A. 4ATP+2NADH", "B. 2ATP+2NADH", "C. 2ATP+4NADH", "D. 4ATP"], "a": "B", "e": "耗2ATP,产4ATP=净+2ATP+2NADH。", "kp": "sugar1_s0_0"}], "judge": [], "fill": [{"id": "sugar1_fill_5", "modI": 0, "q": "糖原磷酸化酶降解糖原切________键,产物是________,需要辅酶________。", "a": "a-1,4糖苷,G-1-P,PLP(磷酸吡哆醛)", "kp": "sugar1_s0_21"}, {"id": "sugar1_fill_8", "modI": 0, "q": "蔗糖由________和________通过________糖苷键连接,因________均参与糖苷键而________还原性。", "a": "葡萄糖,果糖,a1/b2,两个异头碳,无", "kp": "sugar1_s0_13"}], "short": [{"id": "sugar1_short_6", "modI": 0, "q": "简述糖原降解的酶和机制。", "a": "糖原降解需要三种酶:\u000b\u000b①磷酸化酶(处理90%):切a-1,4糖苷键→加Pi→G-1-P(需PLP辅酶)。从非还原端逐个切除葡萄糖残基,直到距a-1,6分支点4个残基处停止。\u000b\u000b②糖基转移酶:将暴露的分支顶端3个葡萄糖残基转移到另一条链的非还原端→只剩1个连接在分支点的Glc(a-1,6)。\u000b\u000b③脱支酶(处理10%):水解a-1,6糖苷键→释放游离葡萄糖(不是G-1-P)。\u000b\u000b产物:G-1-P(90%)和游离G(10%)。\u000b\u000bG-1-P→磷酸葡萄糖变位酶→G-6-P→进入酵解供能。\u000b\u000b调节:磷酸化酶受肾上腺素/胰高血糖素(通过cAMP/PKA)磷酸化激活→糖原分解→维持血糖。", "kp": "sugar1_s0_20"}, {"id": "sugar1_short_11", "modI": 0, "q": "简述淀粉、糖原和纤维素结构的异同。", "a": "共同点:均为葡萄糖单元以糖苷键相连的同多糖。\u000b\u000b淀粉(植物):\u000b• 直链淀粉→a-1,4线性链无分支,螺旋结构\u000b• 支链淀粉→a-1,4+a-1,6分支,每25-30单位一分支\u000b\u000b糖原(动物):\u000b• a-1,4+a-1,6分支,每8-12单位一分支→高度分支化\u000b• 每链平均长度:外链12-14残基,内链5-6残基\u000b• 具无定形结构→易于快速攻击(多酶同时切多个末端)\u000b• 肝湿重~10%存储为糖原\u000b\u000b纤维素(植物):\u000b• b-1,4糖苷键(非a键)→产生刚性平面链\u000b• 无分支,相邻链通过分子间H键形成微纤维→高强度\u000b• 动物无纤维素酶(草食性动物靠共生菌产生)\u000b\u000b关键差异:分支度(糖原>支链淀粉>直链淀粉>纤维素);糖苷键类型(a-1,4 vs b-1,4)。", "kp": "sugar1_s0_15"}, {"id": "sugar1_short_13", "modI": 0, "q": "简述G-6-P在糖代谢中的枢纽地位。", "a": "G-6-P是葡萄糖进入细胞内后的第一个磷酸化产物,是糖代谢的中心分支点:\u000b\u000b三条主要去路:\u000b①→F-6-P→酵解(EMP)→产能(ATP+NADH)→各组织基本供能\u000b②→6-P-葡萄糖酸内酯→PPP→NADPH+5-P-核糖→合成代谢/核酸\u000b③→G-1-P→UDP-葡萄糖→糖原合成(储存)\u000b\u000b来源:\u000b• 葡萄糖被己糖激酶/葡糖激酶→G-6-P\u000b• 糖原降解→G-1-P→G-6-P\u000b• 糖异生→G-6-P→G(仅肝/肾可完成,释入血液)\u000b\u000b三条去路分配取决于:\u000b• 细胞能量需求(ATP/ADP比)→酵解\u000b• 还原力需求(NADPH)→PPP\u000b• 葡萄糖供应过剩→糖原储存\u000b\u000b己糖激酶受G-6-P反馈抑制;葡糖激酶(肝)不受→可持续摄G。\u000bG-6-PDH受NADPH反馈抑制→NADPH过剩时PPP↓。\u000bG-6-P是EMP/PPP的分水岭→代谢灵活调控。", "kp": "sugar1_s0_0"}], "calc": [{"id": "sugar1_calc_6", "modI": 0, "q": "计算糖原中1个葡萄糖残基彻底氧化产生的ATP数(与游离葡萄糖比较)。", "a": "31或29 ATP(比游离G多1ATP)", "steps": "糖原中的葡萄糖残基以G-1-P形式释放(磷酸化酶),不是游离G+ATP→G-6-P\u000b\u000b差异:游离G→G-6-P(己糖激酶):消耗1ATP\u000b     糖原G-1-P→G-6-P(变位酶):不消耗ATP\u000b\u000b所以糖原比游离G少消耗1个ATP\u000b\u000b计算:\u000b游离G有氧氧化:32ATP(苹果酸穿梭)\u000b糖原Glc残基有氧氧化:\u000b• G-1-P→G-6-P:0ATP消耗\u000b• 后续:酵解+PDH+TCA=30-32(取决于穿梭)\u000b• 总计:32+1=33? → 实际上31(用穿梭换算)\u000b\u000b详细:\u000b• 已跳过己糖激酶:省1ATP\u000b• 酵解:G-1-P→...→2丙酮酸:净产=完整酵解2ATP+省1ATP=3ATP\u000b• +2NADH(c)→5ATP(苹果酸穿梭)=8ATP\u000b• +PDH(5ATP)+TCA(20ATP)=33ATP\u000b→比游离G多1ATP(省了己糖激酶那步)\u000b→32+1=33? → 实际是31/32-29/30的精确计算", "kp": "sugar1_s0_4"}], "term": [{"id": "sugar1_term_1", "modI": 0, "term": "异头碳(Anomeric Carbon)", "def": "①在环状单糖结构中,原始羰基碳(C=O)在环化后产生的新手性碳原子（定义）。②α异头物:异头C上的-OH与环末端的-CH2OH呈反式;β异头物:二者呈顺式（分类）。③异头物:因异头C上羟基位置不同形成的立体异构体（命名）。④变旋现象:α和β异头物在溶液中通过开链互变→比旋光度变化至平衡（特点）。⑤半缩醛羟基参与糖苷键后→不再有还原性;若不参与→保留还原性（重要性）。", "kps": "①定义(1分)②a/b分类(1分)③异头物概念(1分)④变旋现象(1分)⑤与还原性的关系(1分)", "kp": "sugar1_s0_9"}, {"id": "sugar1_term_2", "modI": 0, "term": "变旋现象(Mutarotation)", "def": "①单糖溶解后,其比旋光度随时间发生变化,最终达到恒定值的现象（定义）。②原因:α和β异头物在溶液中通过开链形式互变→α→开链→β→达到动态平衡（机制）。③葡萄糖平衡时成分:α-D-葡萄糖(约36%)+β-D-葡萄糖(约64%)+开链形式(<1%)（组成）。④影响因素:温度、pH、缓冲盐等→可改变平衡速率（影响因素）。⑤变旋反映了糖分子结构的动态性和环-链互变的存在（意义）。", "kps": "①定义(1分)②机制:开链互变(1分)③平衡组成(1分)④影响因素(1分)⑤意义(1分)", "kp": "sugar1_s0_9"}, {"id": "sugar1_term_3", "modI": 0, "term": "糖苷键(Glycosidic Bond)", "def": "①单糖分子半缩醛羟基与另一分子的羟基、氨基或巯基缩合形成的O/N/S-糖苷键（定义）。②由异头C通过糖苷键与其他基团连接→单糖残基固定在环式→不再有还原性（特点）。③分类:α-糖苷键(异头C上OH与环末端反式)和β-糖苷键(顺式)（分类）。④常见:α-1,4糖苷键(麦芽糖、淀粉)、β-1,4糖苷键(纤维二糖、纤维素)、α-1,6糖苷键(支链淀粉、糖原分支)（举例）。⑤糖苷酶专一水解特定类型的糖苷键→代谢多样性（意义）。", "kps": "①定义(1分)②半缩醛消失(1分)③a/b分类(1分)④3种常见类型(1分)⑤生理意义(1分)", "kp": "sugar1_s0_19"}, {"id": "sugar1_term_4", "modI": 0, "term": "还原糖(Reducing Sugar)", "def": "①具有游离半缩醛羟基→能将弱氧化剂(Fehling试剂/Benedict试剂)还原产生红色Cu2O沉淀的单糖或寡糖。②化学基础:游离醛基或半缩醛羟基→打开环式→露出醛基→具还原性。③检测原理:碱性铜试剂→还原糖将Cu2+→Cu+(砖红色)→Cu2O红色沉淀。④常见还原糖:所有单糖(Fru虽为酮糖但碱性异构化→醛糖)、麦芽糖、乳糖等含游离半缩醛的二糖。⑤无还原性:蔗糖(两个异头碳均参与糖苷键)、所有多糖(只有一个还原端,浓度极低)。", "kps": "①定义(1分)②化学基础(1分)③检测原理(1分)④举例(1分)⑤非还原糖举例(1分)", "kp": "sugar1_s0_10"}, {"id": "sugar1_term_5", "modI": 0, "term": "差向异构体(Epimer)", "def": "①同碳数、同构型(D/L系列)、仅一个C*的构型不同的两种糖互为差向异构体(特殊类型的非对映体)。②D-甘露糖是D-葡萄糖的C2差向异构体;D-半乳糖是D-葡萄糖的C4差向异构体(举例)。③所有其他C*(C3/C5)构型相同→两者在化学性质上差别小,但生化功能不同(酶识别差异)。④底物/产物:差向异构酶催化差向异构体间互变(如:5-P-核酮糖→5-P-木酮糖)。⑤完全对映体(L-葡萄糖)不是差向异构体(所有C*都不同)。", "kps": "①定义(1分)②Glc→Man(C2)/Gal(C4)(1分)③其他C*相同(1分)④酶催化互变(1分)⑤与对映体的区别(1分)", "kp": "sugar1_s0_5"}, {"id": "sugar1_term_14", "modI": 0, "term": "糖原磷酸化酶(Glycogen Phosphorylase)", "def": "①催化糖原非还原端a-1,4糖苷键磷酸解→产生G-1-P的酶（定义）。②反应:糖原(n残基)+Pi→糖原(n-1残基)+G-1-P,不可逆（反应）。③辅酶:PLP(磷酸吡哆醛)→不与底物直接作用,而是稳定酶构象（辅酶）。④作用范围:处理约90%的糖原残基→从非还原端逐个切除Glc→直到距a-1,6分支点4个残基处停止（作用范围）。⑤调控:磷酸化调控→被肾上腺素/胰高血糖素通过cAMP/PKA级联→磷酸化→激活（调控）。⑥剩余10%由糖基转移酶+脱支酶完成（配合）。", "kps": "①定义(1分)②反应式(1分)③PLP辅酶(1分)④90%+剩余(1分)⑤磷酸化调控(1分)⑥配合脱支酶(1分)", "kp": "sugar1_s0_21"}, {"id": "sugar1_term_16", "modI": 0, "term": "同多糖vs杂多糖(Homopolysaccharide vs Heteropolysaccharide)", "def": "①同多糖:由相同单糖基构成的多糖(例如淀粉仅含葡萄糖a-1,4+a-1,6键,糖原、纤维素、几丁质均为同多糖)（定义+举例）。②杂多糖:由不同单糖基构成的多糖(例如透明质酸含GlcN/AcGlcN/GlcNAc,硫酸软骨素/肝素等)（定义+举例）。③功能差异:同多糖→储能(淀粉/糖原)+结构(纤维素/几丁质);杂多糖→细胞间基质/润滑剂/细胞识别(糖胺聚糖家族)（功能）。④降解:不同糖苷酶水解不同键→同多糖降解简单(单一酶);杂多糖降解复杂(多种酶协同)（降解）。⑤分析:组成分析→酸/酶水解→色谱/质谱→鉴别同/杂多糖（分析）。", "kps": "①同多糖定义+举例(1分)②杂多糖定义+举例(1分)③功能差异(1分)④降解差异(1分)⑤分析方法(1分)", "kp": "sugar1_s0_14"}, {"id": "sugar1_term_17", "modI": 0, "term": "手性碳原子(Chiral Carbon, C*)", "def": "①连接4个不同原子或基团的碳原子→失去对称性,具有两种光学异构体(互为镜像,不能重叠)（定义）。②重要性:单糖的多手性→立体异构体数=2^n个(n=C*数)→葡萄糖的4个C*→16种立体异构体（重要性）。③与D/L构型关系:以距羰基最远的C*的OH方向判定构型→OH在右=D型（判定）。④差向异构体:同碳数、仅一个C*构型不同的糖→互差向→化学反应几乎相同→酶反应因位阻不同而有差异（差向异构体）。⑤酶催化识别:C*构型决定了哪个酶可催化该糖→差向异构体被不同酶识别→生物活性差异很大（酶识别）。", "kps": "①C*定义(1分)②2^n法则(1分)③D/L判定(1分)④差向异构体(1分)⑤酶识别差异(1分)", "kp": "sugar1_s0_3"}, {"id": "sugar1_term_18", "modI": 0, "term": "构型vs构象(Configuration vs Conformation)", "def": "①构型:原子在空间的相对分布和排列,改变必须断裂共价键(如D型↔L型→断键重连)→构型互变需化学键断裂（定义）。②构象:绕单键旋转产生的不同空间排列,不涉及共价键断裂(如椅式↔船式仅绕单键旋转)（定义）。③糖类构象:六元糖以椅式为主(平伏键多→空间位阻小→最稳定)→船式(有立体矛盾→高能量→溶液中极少)（实例）。④代谢活性:仅具有特定构型和构象的糖才能进入酶活性中心→糖类代谢对立体化学严格辨别（说明）。⑤构型/构象固定了糖与其他分子的相互作用方式(如受体、酶等)（意义）。", "kps": "①构型定义(1分)②构象定义(1分)③糖类构象椅式/船式(1分)④代谢对立体化学的要求(1分)⑤意义(1分)", "kp": "sugar1_s0_3"}, {"id": "sugar1_term_24", "modI": 0, "term": "半缩醛羟基(Hemiacetal Hydroxyl)", "def": "①在单糖环化中,原羰基C(C=O)通过与分子内羟基反应,生成的异头碳上的OH（定义）。②产生:醛基与羟基分子内脱水→半缩醛→异头碳形成新C*→OH为该半缩醛羟基（产生）。③性质:半缩醛羟基反应性高→可与另一分子的OH/NH等脱水→形成糖苷键→此羟基消失→单糖失去还原性（性质）。④游离半缩醛→开环→露出醛基→具有还原性→检测还原糖时依赖此反应（与还原性的关系）。⑤重要性:半缩醛羟基的参与与否决定了糖苷键结构和多糖的表征→决定了糖类的物理/化学/生物性质（重要性）。", "kps": "①定义(1分)②产生机制(1分)③与糖苷键关系(1分)④与还原性关系(1分)⑤重要性(1分)", "kp": "sugar1_s0_9"}]}, {"i": 1, "name": "模块二：糖酵解(EMP途径)", "slides": [{"i": 0, "sec": "第六章 糖代谢", "title": "第二节-糖的无氧酵解 (p24)", "notes": "第二节标题页：糖的无氧酵解(Glycolysis)。\u000bEMP途径(Embden-Meyerhof-Parnas)，共10步→2丙酮酸+2ATP+2NADH。\u000b分准备阶段(前5步耗2ATP)和贮能阶段(后5步产4ATP+2NADH)。", "page": 24, "level": "掌握", "img": "assets/img/sugar1/p024.jpg", "anim": null, "fig": "", "points": ["①本节讲糖的无氧酵解（EMP途径）", "②共10步，产物2丙酮酸+2ATP+2NADH", "③准备阶段前5步耗2ATP", "④贮能阶段后5步产4ATP+2NADH"], "check": null, "cards": null}, {"i": 1, "sec": "第六章 糖代谢", "title": "酵解定义 (p25)", "notes": "⚫酵解(Glycolysis)：无氧条件下，酶将葡萄糖→丙酮酸并释放ATP的过程。\u000b⚫分类：糖酵解→乳酸(LDH)，生醇发酵→乙醇(PDC+ADH)。\u000b无氧条件下二者均再生NAD+保证酵解持续。", "page": 25, "level": "掌握", "img": "assets/img/sugar1/p025.jpg", "anim": null, "fig": "", "points": ["①酵解：无氧下葡萄糖→丙酮酸并产ATP", "②糖酵解经LDH生成乳酸", "③生醇发酵经PDC+ADH生成乙醇", "④无氧下均再生NAD+维持酵解进行"], "check": null, "cards": null}, {"i": 2, "sec": "第六章 糖代谢", "title": "EMP途径三位科学家 (p26)", "notes": "Gustav Embden(1874-1933)、Otto Meyerhof(1884-1951)、Jakub Parnas(1884-1949)。\u000b三人共同阐明酵解途径全貌——EMP路径。\u000bMeyerhof因酵解研究获1922年诺贝尔生理学/医学奖。", "page": 26, "level": "了解", "img": "assets/img/sugar1/p026.jpg", "anim": null, "fig": "", "points": ["①Embden、Meyerhof、Parnas共同阐明酵解途径全貌", "②该途径命名为EMP路径（三人姓氏首字母）", "③Meyerhof因酵解研究获1922年诺贝尔生理学/医学奖"], "check": null, "cards": null}, {"i": 3, "sec": "第六章 糖代谢", "title": "酵解10步全景 (p27)", "notes": "⚫部位：细胞质。\u000b⚫前5步(准备阶段)：G→2GAP(三磷酸甘油醛)，消耗2ATP。\u000b⚫后5步(贮能阶段)：2GAP→2丙酮酸，产4ATP(底物水平磷酸化)+2NADH。\u000b⚫净产：2ATP+2NADH。\u000b三大不可逆步：①③⑩。", "page": 27, "level": "掌握", "img": "assets/img/sugar1/p027.jpg", "anim": null, "fig": "", "points": ["①部位在细胞质，前5步准备阶段耗2ATP生成2GAP", "②后5步贮能阶段产4ATP+2NADH（底物水平磷酸化）", "③净产2ATP+2NADH；不可逆步为①③⑩"], "check": null, "cards": null}, {"i": 4, "sec": "第六章 糖代谢", "title": "准备阶段-前5步概述 (p28)", "notes": "准备阶段（前5步）：葡萄糖(G)→(2)3-磷酸甘油醛。\u000b☆消耗2个ATP——为后续能量释放做准备。\u000b将六碳糖→两个三碳糖，每个含一个磷酸基团(磷酸化活化+裂解)。", "page": 28, "level": "掌握", "img": "assets/img/sugar1/p028.jpg", "anim": null, "fig": "", "points": ["①前5步为准备阶段：葡萄糖→2分子3-磷酸甘油醛", "②消耗2个ATP，为后续能量释放做准备", "③六碳糖裂解为两个含磷酸基团的三碳糖（活化+裂解）"], "check": null, "cards": null}, {"i": 5, "sec": "第六章 糖代谢", "title": "第1步：己糖激酶 (p29)", "notes": "G+ATP→G-6-P+ADP —己糖激酶(Mg2+/Mn2+)—不可逆！\u000b🔴。\u000b机理：G的C6-OH对ATP的γ-磷酸亲核攻击→ODD机理(Mg2+中和负电荷)。\u000b这是酵解第一个调控点且第一个消耗ATP的步骤。", "page": 29, "level": "掌握", "img": "assets/img/sugar1/p029.jpg", "anim": null, "fig": "", "points": ["①G+ATP→G-6-P+ADP，己糖激酶催化，不可逆", "②需Mg²⁺/Mn²⁺，C6-OH亲核攻击ATP的γ-磷酸", "③酵解第一个调控点，也是第一个耗ATP步骤"], "check": null, "cards": null}, {"i": 6, "sec": "第六章 糖代谢", "title": "己糖激酶诱导契合 (p30)", "notes": "己糖激酶与底物(D-葡萄糖)结合→构象显著变化→活性位点包围底物→排除水分子→利于磷酸转移。\u000b这一现象是诱导契合学说的经典范例(酶的构象柔性)。\u000b结构变化→催化效率↑↑。", "page": 30, "level": "掌握", "img": "assets/img/sugar1/p030.jpg", "anim": null, "fig": "", "points": ["①己糖激酶与葡萄糖结合后构象显著变化", "②活性位点包围底物、排除水分子，利于磷酸转移", "③诱导契合学说的经典范例，体现酶构象柔性"], "check": null, "cards": null}, {"i": 7, "sec": "第六章 糖代谢", "title": "第2步：磷酸葡萄糖异构酶 (p31)", "notes": "G-6-P→F-6-P —磷酸葡萄糖异构酶— 可逆。\u000b醛糖(G-6-P)→酮糖(F-6-P)的异构化。\u000b准备后续C3-C4裂解反应——醛糖比酮糖更难裂解，必须先异构。\u000b反应平衡偏G-6-P但F-6-P被PFK不断消耗推动前进。", "page": 31, "level": "理解", "img": "assets/img/sugar1/p031.jpg", "anim": null, "fig": "", "points": ["①G-6-P→F-6-P，磷酸葡萄糖异构酶催化，可逆", "②醛糖→酮糖的异构化反应", "③为后续C3-C4裂解做准备；F-6-P被PFK消耗推动反应"], "check": null, "cards": null}, {"i": 8, "sec": "第六章 糖代谢", "title": "第3步：磷酸果糖激酶PFK (p32)", "notes": "F-6-P+ATP→F-1,6-2P+ADP —磷酸果糖激酶— 不可逆！\u000b🔴。\u000b酵解最重要限速酶！\u000b受ATP/柠檬酸(H+)抑制；\u000bAMP/ADP/F-2,6-BP激活。\u000bF-2,6-二磷酸果糖是最强别构激活剂→解除ATP抑制。", "page": 32, "level": "掌握", "img": "assets/img/sugar1/p032.jpg", "anim": null, "fig": "", "points": ["①F-6-P+ATP→F-1,6-2P+ADP，PFK催化，不可逆", "②酵解最重要限速酶，关键调控点", "③ATP/柠檬酸抑制；AMP/ADP/F-2,6-BP激活"], "check": null, "cards": null}, {"i": 9, "sec": "第六章 糖代谢", "title": "第4步：醛缩酶 (p33-p35) (p10)", "notes": "F-1,6-2P→DHAP+GAP —醛缩酶—。\u000b六碳→两个三碳。\u000bDHAP(磷酸二羟丙酮，酮糖)+GAP(3-磷酸甘油醛，醛糖)。\u000b醛缩酶裂解C3-C4键→产生两个互为异构体的三碳糖。\u000b平衡偏逆方向。", "page": 10, "level": "掌握", "img": "assets/img/sugar1/p010.jpg", "anim": null, "fig": "", "points": ["①F-1,6-2P→DHAP+GAP，醛缩酶催化", "②裂解C3-C4键，六碳糖→两个三碳糖", "③产物DHAP（酮糖）与GAP（醛糖）互为异构体，平衡偏逆"], "check": null, "cards": null}, {"i": 10, "sec": "第六章 糖代谢", "title": "第5步：磷酸丙糖异构酶 (p36)", "notes": "DHAP↔GAP —磷酸丙糖异构酶— 快速可逆。\u000bDHAP≠可直接继续酵解，必须异构为GAP。\u000b高效催化→DHAP几乎定量转化为GAP。\u000b至此准备阶段完成：G→2GAP+消耗2ATP。", "page": 36, "level": "理解", "img": "assets/img/sugar1/p036.jpg", "anim": null, "fig": "", "points": ["①DHAP必须异构为GAP才能继续酵解", "②磷酸丙糖异构酶催化，快速可逆", "③高效催化使DHAP几乎定量转为GAP", "④准备阶段完成：G→2GAP，耗2ATP"], "check": null, "cards": null}, {"i": 11, "sec": "第六章 糖代谢", "title": "贮能阶段-后5步概述 (p37)", "notes": "贮能阶段（后5步）：(2)3-磷酸甘油醛→(2)丙酮酸。\u000b☆生成4ATP(底物水平磷酸化)+2NADH(H+)。\u000b从高能中间体(1,3-BPG, PEP)转移磷酸基团→ADP→ATP。\u000b这是酵解能量收成的阶段。", "page": 37, "level": "掌握", "img": "assets/img/sugar1/p037.jpg", "anim": null, "fig": "", "points": ["①后5步：2分子GAP→2分子丙酮酸", "②净生成4ATP+2NADH，为能量收成阶段", "③ATP来自底物水平磷酸化", "④磷酸基团由1,3-BPG、PEP等高能中间物转移给ADP"], "check": null, "cards": null}, {"i": 12, "sec": "第六章 糖代谢", "title": "第6步：GAPDH (p38)", "notes": "GAP+NAD++Pi→1,3-BPG+NADH+H+ —GAPDH—。\u000b🔴唯一氧化步！\u000b活性中心含Cys-SH→氧化GAP醛基成羧基→硫酯高能中间物→磷酸解→1,3-BPG。\u000b砷酸代Pi→1-砷酸-3-PG不稳定自身水解→解偶联(不产ATP)。", "page": 38, "level": "掌握", "img": "assets/img/sugar1/p038.jpg", "anim": null, "fig": "", "points": ["①GAP+NAD⁺+Pi→1,3-BPG+NADH+H⁺", "②酵解唯一氧化步，含Cys-SH活性中心", "③醛基氧化成羧基，经硫酯高能中间物磷酸解", "④砷酸替代Pi致解偶联，不产ATP"], "check": null, "cards": null}, {"i": 13, "sec": "第六章 糖代谢", "title": "第7步：PGK底物磷酸化 (p39)", "notes": "1,3-BPG+ADP→3-PG+ATP —磷酸甘油酸激酶—。\u000b🔴第一次底物水平磷酸化！\u000b1,3-BPG水解△G0'=-49.37kJ/mol 覆盖 ATP生成△G0'=+30.54kJ/mol。\u000b净△G0'=-18.83kJ/mol→反应不可逆。\u000b产生第一个ATP!", "page": 39, "level": "掌握", "img": "assets/img/sugar1/p039.jpg", "anim": null, "fig": "", "points": ["①1,3-BPG+ADP→3-PG+ATP，PGK催化", "②第一次底物水平磷酸化，生成第一个ATP", "③1,3-BPG水解释能覆盖ATP合成耗能", "④净ΔG⁰'=-18.83kJ/mol，反应不可逆"], "check": null, "cards": null}, {"i": 14, "sec": "第六章 糖代谢", "title": "第8步：磷酸甘油酸变位酶 (p40)", "notes": "3-PG→2-PG —磷酸甘油酸变位酶—。\u000b磷酸基团从C3→C2位置迁移。\u000b需要中间物2,3-BPG(二磷酸甘油酸)作为辅因子参与磷酸转移。\u000b变位酶催化分子内重排反应。", "page": 40, "level": "理解", "img": "assets/img/sugar1/p040.jpg", "anim": null, "fig": "", "points": ["①3-PG→2-PG，磷酸甘油酸变位酶催化", "②磷酸基团由C3迁移至C2", "③需2,3-BPG作辅因子参与磷酸转移", "④属分子内重排反应"], "check": null, "cards": null}, {"i": 15, "sec": "第六章 糖代谢", "title": "第9步：烯醇化酶 (p41)", "notes": "2-PG→PEP+H2O —烯醇化酶—。\u000b⚫脱水反应→分子内能量重排：磷酸酯水解能从-17.6→高能烯醇磷酸酯-61.9kJ/mol，大幅升高磷酸基团转移势能。\u000b⚫Fˉ抑制(临床：血糖管灰头利用此原理防止酵解)。", "page": 41, "level": "掌握", "img": "assets/img/sugar1/p041.jpg", "anim": null, "fig": "", "points": ["①2-PG→PEP+H₂O，烯醇化酶催化脱水", "②磷酸酯水解能由-17.6升至-61.9kJ/mol", "③能量重排大幅提高磷酸基团转移势能", "④F⁻抑制该酶，灰头血糖管据此防酵解"], "check": null, "cards": null}, {"i": 16, "sec": "第六章 糖代谢", "title": "第10步：丙酮酸激酶PK (p42)", "notes": "PEP+ADP→丙酮酸+ATP —丙酮酸激酶— 不可逆！\u000b🔴。\u000b🔴第二次底物水平磷酸化！\u000bPEP水解△G0'=-61.92kJ/mol 覆盖 ATP合成+30.54kJ/mol。\u000b净△G0'=-31.38kJ/mol→极度不可逆。\u000b肝PK受磷酸化/去磷酸化调控。", "page": 42, "level": "掌握", "img": "assets/img/sugar1/p042.jpg", "anim": null, "fig": "", "points": ["①PEP+ADP→丙酮酸+ATP，PK催化不可逆", "②第二次底物水平磷酸化，生成第二个ATP", "③PEP水解释能覆盖ATP合成耗能", "④净ΔG⁰'=-31.38kJ/mol，极度不可逆；肝PK受磷酸化调控"], "check": null, "cards": null}, {"i": 17, "sec": "第六章 糖代谢", "title": "酵解自由能变化图 (p43)", "notes": "全10步的△G变化剖面图(红细胞条件)。\u000b三步不可逆反应(①③⑩)△G远负(-29.9、-14.2、-31.4kJ/mol)→驱动整条通路单向进行。\u000b其余7步△G接近0→可逆，由浓度差驱动方向。", "page": 43, "level": "掌握", "img": "assets/img/sugar1/p043.jpg", "anim": null, "fig": "图为酵解10步反应的自由能变化剖面，纵轴为ΔG。读图重点：第1、3、10步出现大幅负值深谷（-29.9、-14.2、-31.4kJ/mol），为不可逆的限速调控点；其余步骤ΔG接近0，方向由底物/产物浓度决定。", "points": ["①全10步ΔG剖面图（红细胞条件）", "②三步不可逆反应：①③⑩步ΔG远负", "③不可逆步驱动整条通路单向进行", "④其余7步ΔG近0，可逆，由浓度差定方向"], "check": null, "cards": null}, {"i": 18, "sec": "第六章 糖代谢", "title": "底物水平磷酸化总结 (p44)", "notes": "底物水平磷酸化：将高能磷酸化合物(1,3-BPG→第7步，PEP→第10步)的~P直接转移至ADP→ATP。\u000b与氧化磷酸化不同：不依赖呼吸链和质子梯度。\u000b酵解共2次底物磷酸化×2=4ATP总产。", "page": 44, "level": "掌握", "img": "assets/img/sugar1/p044.jpg", "anim": null, "fig": "", "points": ["①高能~P直接转移给ADP生成ATP", "②1,3-BPG(第7步)和PEP(第10步)两处", "③不依赖呼吸链和质子梯度", "④酵解共2次×2=4ATP"], "check": null, "cards": null}, {"i": 19, "sec": "第六章 糖代谢", "title": "酵解途径小结 (p45)", "notes": "总反应式：G+2NAD++2ADP+2Pi→2丙酮酸+2NADH+2ATP+2H2O。\u000b三步不可逆(1/3/10)是限速步骤和调控点。\u000b能量计算：消耗2ATP→产生4ATP+2NADH→净产2ATP+2NADH(H+)。", "page": 45, "level": "掌握", "img": "assets/img/sugar1/p045.jpg", "anim": null, "fig": "", "points": ["①总反应式：G→2丙酮酸+2ATP+2NADH", "②三步不可逆(1/3/10)为限速调控点", "③消耗2ATP、产生4ATP，净得2ATP", "④净产2ATP+2NADH(H+)"], "check": null, "cards": null}, {"i": 20, "sec": "第六章 糖代谢", "title": "丙酮酸的去路 (p46)", "notes": "丙酮酸三条去路：①有氧→乙酰CoA→TCA→CO2+H2O+大量ATP；\u000b②无氧(肌肉/红细胞/乳酸菌)→乳酸(LDH, 糖酵解)；\u000b③无氧(酵母)→乙醇(丙酮酸脱羧酶+乙醇脱氢酶, 生醇发酵)。\u000b②③均再生NAD+。", "page": 46, "level": "掌握", "img": "assets/img/sugar1/p046.jpg", "anim": null, "fig": "", "points": ["①有氧→乙酰CoA→TCA→大量ATP", "②无氧(肌肉/红细胞)→乳酸(LDH)", "③无氧(酵母)→乙醇(脱羧酶+ADH)", "④乳酸/乙醇途径均再生NAD+"], "check": null, "cards": null}, {"i": 21, "sec": "第六章 糖代谢", "title": "糖酵解(乳酸发酵) (p47)", "notes": "总反应：G+2ADP+2Pi→2乳酸+2ATP+2H2O。\u000b丙酮酸+NADH+H+→乳酸+NAD+(LDH)。\u000b关键：再生NAD+保证酵解持续。\u000b红细胞的唯一能量来源就是葡萄糖→乳酸途径(LDH丰富，无线粒体)。", "page": 47, "level": "掌握", "img": "assets/img/sugar1/p047.jpg", "anim": null, "fig": "", "points": ["①总反应：G→2乳酸+2ATP+2H2O", "②丙酮酸+NADH→乳酸+NAD+(LDH)", "③再生NAD+保证酵解持续进行", "④红细胞唯一供能途径(无线粒体)"], "check": null, "cards": null}, {"i": 22, "sec": "第六章 糖代谢", "title": "生醇发酵 (p48)", "notes": "总反应：G+2ADP+2Pi→2乙醇+2CO2+2ATP+2H2O。\u000b两步：①丙酮酸脱羧酶(TPP)→乙醛+CO2；\u000b②乙醇脱氢酶(ADH)→乙醇+NAD+。\u000b酵母A-S酵母在无氧下的能量代谢。\u000b酿酒/做面包的原理。", "page": 48, "level": "掌握", "img": "assets/img/sugar1/p048.jpg", "anim": null, "fig": "", "points": ["①总反应：G→2乙醇+2CO2+2ATP", "②丙酮酸脱羧酶(TPP)→乙醛+CO2", "③乙醇脱氢酶(ADH)→乙醇+NAD+", "④酵母无氧代谢，酿酒/面包原理"], "check": null, "cards": null}, {"i": 23, "sec": "第六章 糖代谢", "title": "酵解生理意义 (p49)", "notes": "三大意义：①生命体普遍存在的供能途径→缺氧/无氧下维持生命活动；\u000b②少数组织(表皮、视网膜)常态下靠酵解供能(糖酵解依赖)；\u000b③特殊生理状况下意义重大：激烈运动/登山/贫血→酵解关键。", "page": 49, "level": "掌握", "img": "assets/img/sugar1/p049.jpg", "anim": null, "fig": "", "points": ["①普遍存在的供能途径，缺氧下维持生命", "②表皮、视网膜等常态靠酵解供能", "③剧烈运动/贫血等特殊状况意义重大"], "check": null, "cards": null}, {"i": 24, "sec": "第六章 糖代谢", "title": "Cori循环(乳酸循环) (p50)", "notes": "肌肉酵解→乳酸→血液→肝脏→糖异生→葡萄糖→血液→肌肉。\u000b废物回收+解毒+再供能。\u000b乳酸过量→酸中毒。\u000b心肌利用乳酸作为能源→Cori循环的加速方向。\u000b激烈运动后肌肉酸痛=乳酸堆积。", "page": 50, "level": "掌握", "img": "assets/img/sugar1/p050.jpg", "anim": null, "fig": "", "points": ["①肌肉乳酸→血→肝糖异生→葡萄糖→肌肉", "②废物回收、解毒并再供能", "③乳酸过量致酸中毒、肌肉酸痛", "④心肌利用乳酸，加速Cori循环"], "check": null, "cards": null}, {"i": 25, "sec": "第六章 糖代谢", "title": "第三节-糖的有氧分解 (p51)", "notes": "第三节标题页：糖的有氧分解。\u000b三阶段：①丙酮酸氧化脱羧→乙酰CoA(PDH系,线粒体基质)；\u000b②TCA三羧酸循环(线粒体基质)；\u000b③NADH/FADH2→呼吸链→ATP(线粒体内膜)。\u000b1分子葡萄糖→32ATP(最高效)。", "page": 51, "level": "掌握", "img": "assets/img/sugar1/p051.jpg", "anim": null, "fig": "", "points": ["①三阶段：氧化脱羧、TCA、呼吸链", "②丙酮酸→乙酰CoA(PDH系,线粒体基质)", "③TCA在线粒体基质，呼吸链在内膜", "④1分子葡萄糖彻底氧化→32ATP"], "check": null, "cards": null}, {"i": 26, "sec": "第六章 糖代谢", "title": "有氧分解定义 (p52)", "notes": "有氧分解：有氧条件下，丙酮酸被彻底氧化→CO2+H2O并合成大量ATP。\u000b一分子葡萄糖经有氧分解最多可产生32个ATP。\u000b整个过程在线粒体内完成，是多细胞生物主要供能方式。", "page": 52, "level": "掌握", "img": "assets/img/sugar1/p052.jpg", "anim": null, "fig": "", "points": ["①有氧条件下丙酮酸彻底氧化为CO2和H2O", "②1分子葡萄糖有氧分解最多产32个ATP", "③全过程在线粒体完成", "④是多细胞生物主要供能方式"], "check": null, "cards": null}], "mcq": [{"id": "sugar1_mcq_16", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "PFK-1最强激活剂？", "o": ["A. ATP", "B. 柠檬酸", "C. 2,6-二磷酸果糖", "D. NADH"], "a": "C", "e": "F-2,6-BP是PFK-1最强别构激活剂。ATP/柠檬酸抑制PFK-1。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_17", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "GAPDH产物？", "o": ["A. GAP→3-PG", "B. GAP+Pi+NAD+→1,3-BPG+NADH", "C. 1,3-BPG→GAP", "D. GAP+FAD→产物"], "a": "B", "e": "GAPDH催化唯一氧化步。活性Cys形成硫酯。砷酸替代Pi→解偶联不产ATP。", "kp": "sugar1_s1_12"}, {"id": "sugar1_mcq_18", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "氟化物抑制哪个酶？", "o": ["A. 己糖激酶", "B. 烯醇化酶", "C. PFK-1", "D. PK"], "a": "B", "e": "F-+Mg2++Pi→复合物→取代烯醇化酶Mg2+→2-PG积累。血糖管(灰头管)利用此原理。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_19", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "底物磷酸化哪两步？", "o": ["A. 1和3", "B. 7(PGK)和10(PK)", "C. 6和7", "D. 4和10"], "a": "B", "e": "PGK:1,3-BPG→3-PG+ATP;PK:PEP→丙酮酸+ATP。各x2=总4ATP。", "kp": "sugar1_s1_13"}, {"id": "sugar1_mcq_20", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "己糖激酶与底物结合后构象变化说明什么？", "o": ["A. 锁钥模型", "B. 诱导契合(酶的构象柔性)", "C. 抑制剂作用", "D. 共价催化"], "a": "B", "e": "己糖激酶与D-Glc结合→构象显著变化→活性位点包围底物→排开水分子→利于磷酸转移。诱导契合经典范例!", "kp": "sugar1_s1_6"}, {"id": "sugar1_mcq_21", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "砷酸(AsO43-)如何影响酵解？", "o": ["A. 促进ATP生成", "B. 替代Pi,形成1-砷酸-3-PG→快速自发水解→不产ATP(解偶联)", "C. 抑制PFK", "D. 无影响"], "a": "B", "e": "砷酸与Pi类似→GAPDH用砷酸→1-砷酸-3-PG高度不稳定→不经过PGK→不产ATP→净产0ATP。砷毒性分子基础!", "kp": "sugar1_s1_17"}, {"id": "sugar1_mcq_22", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "2,3-BPG的生理功能是什么？", "o": ["A. 仅作为酵解中间物", "B. 降低Hb对O2亲和力,有利于组织供氧", "C. 抑制糖酵解", "D. 激活PFK"], "a": "B", "e": "2,3-BPG与Hb b亚基结合→稳定T态→O2解离曲线右移→组织水平O2释放↑。高山适应/贫血→RBC中2,3-BPG↑。", "kp": "sugar1_s1_13"}, {"id": "sugar1_mcq_23", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "丙酮酸在无氧条件下的去路？", "o": ["A. ①TCA②乳酸发酵③丙氨酸", "B. ①乳酸(LDH)②乙醇(PDC+ADH)③TCA", "C. ①TCA②PPP③生醇发酵", "D. ①糖异生②PPP③TCA"], "a": "B", "e": "有氧→乙酰CoA→TCA;无氧-肌肉→乳酸(LDH,NAD+再生);无氧-酵母→乙醇NAD+再生。后两种保证NAD+再生维持酵解。", "kp": "sugar1_s1_20"}, {"id": "sugar1_mcq_24", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "生醇发酵中TPP的作用？", "o": ["A. 丙酮酸脱羧酶辅酶,脱羧生成乙醛+CO2", "B. 激活ADH", "C. 乙醇的辅酶", "D. 无作用"], "a": "A", "e": "PDC依赖TPP→丙酮酸→乙醛+CO2。然后ADH→乙醇+NAD+。两步均在细胞质,再生的NAD+保障酵解持续。", "kp": "sugar1_s1_22"}, {"id": "sugar1_mcq_25", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "酵解中三步不可逆反应的ΔG？", "o": ["A. 1,3,10", "B. 1,7,10", "C. 3,7,10", "D. 1,3,7"], "a": "A", "e": "第1步:-33.5kJ/mol;第3步:-22.2;第10步:-16.7。ΔG远负→不可逆→调控点。其余7步≈0→可逆。", "kp": "sugar1_s1_17"}, {"id": "sugar1_mcq_26", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "激烈运动时酵解为什么重要？", "o": ["A. 有氧供能足够", "B. 肌肉缺氧,酵解可在无氧下快速供能(2ATP/G)", "C. 酵解产ATP比有氧多", "D. 酵解不需酶"], "a": "B", "e": "剧烈运动→局部缺氧→TCA受阻→依赖酵解速供ATP。乳酸堆积→酸中毒→肌肉酸痛。生理意义三大点之一。", "kp": "sugar1_s1_23"}, {"id": "sugar1_mcq_27", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "F-2,6-BP如何调控PFK-1？", "o": ["A. 竞争性抑制", "B. 在别构位点结合,解除ATP/柠檬酸抑制", "C. 促进PFK-1降解", "D. 作为底物参与反应"], "a": "B", "e": "F-2,6-BP是PFK-1最强别构激活剂→结合别构位点→增强F-6-P亲和力→克服ATP/柠檬酸抑制。受胰岛素/胰高血糖素调控。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_28", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "Cori循环(乳酸循环)的完整流程？", "o": ["A. 肝乳酸→G→肌肉", "B. 肌肉酵解→乳酸→血液→肝糖异生→G→血液→肌肉", "C. G→乳酸不可逆", "D. 肝→乳酸→肌肉→G"], "a": "B", "e": "Cori循环=废物回收+解毒+供能。肌肉酵解→乳酸→肝糖异生→G→肌肉。净亏4ATP,但为紧急供能!", "kp": "sugar1_s1_24"}, {"id": "sugar1_mcq_29", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "TCA不可逆酶？", "o": ["A. 柠檬酸合酶/异柠檬酸脱氢酶/a-KG脱氢酶", "B. 苹果酸脱氢酶", "C. 琥珀酸脱氢酶", "D. 延胡索酸酶"], "a": "A", "e": "TCA三个调控点:①柠檬酸合酶③异柠檬酸脱氢酶④a-KG脱氢酶。SDH=呼吸链复合物II。", "kp": "sugar1_s1_3"}, {"id": "sugar1_mcq_30", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "一轮TCA产ATP？", "o": ["A. 12", "B. 10(3NADH+1FADH2+1GTP)", "C. 15", "D. 8"], "a": "B", "e": "3NADH(x2.5=7.5)+1FADH2(x1.5=1.5)+1GTP=10ATP。", "kp": "sugar1_s1_20"}], "judge": [], "fill": [{"id": "sugar1_fill_1", "modI": 1, "q": "糖酵解中三步不可逆反应分别由________、________和________催化。", "a": "己糖激酶,磷酸果糖激酶(PFK-1),丙酮酸激酶(PK)", "kp": "sugar1_s1_17"}, {"id": "sugar1_fill_9", "modI": 1, "q": "Cori循环(乳酸循环)中,肌肉酵解产生________经血液运至________,通过________途径生成葡萄糖再回到肌肉。", "a": "乳酸,肝脏,糖异生", "kp": "sugar1_s1_24"}, {"id": "sugar1_fill_11", "modI": 1, "q": "糖酵解的底物水平磷酸化发生在第________步(________催化)和第________步(________催化)。", "a": "7,磷酸甘油酸激酶(PGK),10,丙酮酸激酶(PK)", "kp": "sugar1_s1_18"}], "short": [{"id": "sugar1_short_1", "modI": 1, "q": "简述糖酵解(EMP途径)的10步反应,标明三步不可逆反应及其催化酶。", "a": "糖酵解在细胞质进行,分两阶段:准备阶段(前5步)和贮能阶段(后5步)。\u000b\u000b【准备阶段】(耗2ATP):\u000b①G+ATP→G-6-P+ADP(己糖激酶,不可逆!)\u000b②G-6-P→F-6-P(异构酶)\u000b③F-6-P+ATP→F-1,6-2P+ADP(PFK-1,不可逆!最重要调控点)\u000b④F-1,6-2P→DHAP+GAP(醛缩酶)\u000b⑤DHAP↔GAP(异构酶)\u000b\u000b【贮能阶段】(产4ATP+2NADH):\u000b⑥GAP+NAD++Pi→1,3-BPG+NADH(GAPDH,唯一氧化步)\u000b⑦1,3-BPG+ADP→3-PG+ATP(PGK,底物磷酸化)\u000b⑧3-PG→2-PG(变位酶)\u000b⑨2-PG→PEP+H2O(烯醇化酶,F-抑制)\u000b⑩PEP+ADP→丙酮酸+ATP(PK,不可逆!底物磷酸化)\u000b\u000b总反应:G+2NAD++2ADP+2Pi→2丙酮酸+2NADH+2ATP+2H2O\u000b净产:2ATP+2NADH。三步不可逆①②⑩=三个调控点。", "kp": "sugar1_s1_2"}, {"id": "sugar1_short_7", "modI": 1, "q": "简述NADH穿梭的两种方式及ATP产量的差异。", "a": "胞质中产生的NADH不能直接进入线粒体,需穿梭系统:\u000b\u000b①苹果酸-天冬氨酸穿梭(肝/肾/心肌):\u000b胞质NADH→苹果酸→进入线粒体→MDH→OAA+NADH(m)→NADH→复合物I→P/O≈2.5\u000b→2胞质NADH→2线粒体NADH→5ATP\u000b\u000b②甘油-3-磷酸穿梭(肌肉/神经):\u000b胞质NADH→DHAP→甘油-3-磷酸(G3PDH)→进入膜间隙→线粒体G3PDH(膜结合)→FADH2→CoQ→绕过复合物I→P/O≈1.5\u000b→2胞质NADH→2FADH2→3ATP\u000b\u000b差异原因:苹果酸穿梭将NADH直接交给复合物I(高P/O);甘油-3-P穿梭转换为FADH2直接进入CoQ(低P/O)。\u000b\u000b1分子G总ATP:肝/心肌32ATP(苹果酸穿梭);骨骼肌/神经30ATP(甘油-3-P穿梭)。", "kp": "sugar1_s1_12"}, {"id": "sugar1_short_10", "modI": 1, "q": "简述糖异生(gluconeogenesis)绕过酵解三步不可逆反应的机制。", "a": "糖异生基本是酵解的逆过程,但有三步不可逆必须绕过:\u000b\u000b酵解步1: G→G-6-P(己糖激酶)\u000b绕过: G-6-P+H2O→G+Pi(葡萄糖-6-磷酸酶,肝/肾内质网)\u000b\u000b酵解步3: F-6-P→F-1,6-2P(PFK-1)\u000b绕过: F-1,6-2P+H2O→F-6-P+Pi(果糖-1,6-二磷酸酶,FBPase-1)\u000b\u000b酵解步10: PEP→丙酮酸(PK)\u000b绕过分两步:\u000b①丙酮酸+CO2+ATP→草酰乙酸+ADP+Pi(丙酮酸羧化酶,线粒体,生物素)\u000b②草酰乙酸→苹果酸(出线粒体)→OAA→PEP+CO2+GTP(PEPCK,胞质)\u000b\u000b能量消耗:\u000b酵解: 1G→2丙酮酸=净产2ATP\u000b糖异生: 2丙酮酸→1G=消耗6ATP(或GTP)\u000b净亏4ATP,保障代谢单向性。G-6-Pase仅在肝/肾有,肌肉无→肌肉糖原不能直接释G到血。", "kp": "sugar1_s1_17"}], "calc": [{"id": "sugar1_calc_2", "modI": 1, "q": "计算糖酵解(EMP)中ATP的消耗和产生,说明净ATP数。", "a": "净产2ATP+2NADH", "steps": "消耗ATP(准备阶段):\u000b①G→G-6-P(己糖激酶): -1ATP\u000b③F-6-P→F-1,6-2P(PFK-1): -1ATP\u000b消耗合计:-2ATP\u000b\u000b产生ATP(贮能阶段):\u000b⑦1,3-BPG→3-PG(PGK): +1ATP×2个三碳=+2ATP\u000b⑩PEP→丙酮酸(PK): +1ATP×2个三碳=+2ATP\u000b\u000b产生合计:+4ATP\u000b\u000b净ATP=+4-2=+2ATP\u000b\u000b还需产生:2NADH(H+)→进入呼吸链\u000b• 苹果酸穿梭:2×2.5=5ATP\u000b• 甘油-3-P穿梭:2×1.5=3ATP\u000b\u000b酵解能量效率为有氧氧化的几分之一:\u000b有氧32ATP vs 酵解(乳酸发酵)2ATP→酵解效率极低但速度快。", "kp": "sugar1_s1_2"}, {"id": "sugar1_calc_8", "modI": 1, "q": "论述糖酵解在不同生理条件下的调节机制。", "a": "酵解根据组织氧条件、能量需求和激素状态受精密调节", "steps": "糖酵解的核心调节点是三步不可逆反应:\u000b\u000b①己糖激酶:\u000b• 受G-6-P反馈抑制(产物)\u000b• 葡糖激酶(肝):Km高(10mM)→高G时摄糖;不受G-6-P抑制→可持续运转\u000b\u000b②PFK-1(最重要调控点!):\u000b• 别构抑制剂:ATP(高能荷信号)、柠檬酸(无氧排出的TCA产物)\u000b• 别构激活剂:AMP/ADP(低能荷信号)\u000b• F-2,6-BP(最强激活剂)→克服ATP/柠檬酸抑制\u000b  - 受胰岛素→激活PFK-2→F-2,6-BP↑→酵解↑\u000b  - 受胰高血糖素→抑制PFK-2→F-2,6-BP↓→酵解↓\u000b\u000b③丙酮酸激酶(PK):\u000b• 受F-1,6-BP前馈激活(酵解中间物↑→通路加速)\u000b• 受ATP/Ala抑制\u000b• 肝PK受磷酸化调控:胰高血糖素→PKA通路→PK磷酸化→活性↓→酵解↓\u000b\u000b不同条件:\u000b• 进食后(高G):F-2,6-BP↑→PFK-1激活→酵解↑\u000b• 饥饿:胰高血糖素→F-2,6-BP↓+PK↓→酵解↓→节约G供脑组织\u000b• 运动肌肉:AMP↑→PFK-1激活;Ca2+↑→丙酮酸脱氢酶激活\u000b• 缺氧/无氧:PFK-1+Pasteur效应→促进酵解代替TCA", "kp": "sugar1_s1_23"}], "term": [{"id": "sugar1_term_6", "modI": 1, "term": "糖酵解/EMP途径(Glycolysis/EMP Pathway)", "def": "①无氧条件下,酶将葡萄糖分解为丙酮酸并释放ATP的过程（定义）。②3位德国科学家阐明:Embden-Meyerhof-Parnas→就此命名EMP途径（发现者）。③部位:细胞质。步骤:10步→准备阶段(前5步)+贮能阶段(后5步)（过程）。④产能:耗2ATP+产4ATP=净2ATP+2NADH(H+)（产能）。⑤三步不可逆反应(己糖激酶③/⑧/⑩)为关键调控点（调控）。⑥所有生物体普遍存在的核心代谢途径（普遍性）。", "kps": "①定义(1分)②EMP命名(1分)③10步两阶段(1分)④产能(1分)⑤三步不可逆调控(1分)⑥普遍性(1分)", "kp": "sugar1_s1_0"}, {"id": "sugar1_term_7", "modI": 1, "term": "底物水平磷酸化(Substrate-level Phosphorylation)", "def": "①高能底物(含高能磷酸/酰基键)将高能基团直接转移给ADP/GDP生成ATP/GTP的过程（定义）。②与氧化磷酸化不同→不依赖呼吸链、O2或质子梯度（与氧化磷酸化的区别）。③糖代谢中两处:酵解-1,3-BPG→3-PG(PGK,每G产2ATP);TCA-琥珀酰CoA→琥珀酸(琥珀酰CoA合成酶,每轮TCA产1ATP/GTP)（糖代谢中位置）。④关键特征:△G0'高能底物→可逆反应→总反应中占较小比例(酵解+S+TCA底物磷酸化仅4+2=6ATP vs 呼吸链26个 ATP)（特征）。⑤在无氧条件下是唯一生成ATP的方式（意义）。", "kps": "①定义(2分)②与氧化磷酸化区别(1分)③糖代谢两处(1分)④产能占比小(1分)⑤无氧下唯一产能方式(1分)", "kp": "sugar1_s1_18"}, {"id": "sugar1_term_8", "modI": 1, "term": "诱导契合(Induced Fit)", "def": "①酶与底物结合时,酶构象发生改变以精确匹配底物形状的学说（定义）。②提出者Koshland(1958):酶活性中心不是预先形成的刚性孔穴,与底物结合才产生构象变化（理论）。③经典范例:己糖激酶与D-葡萄糖结合→活性位点包围底物→排开水分→促进磷酸转移反应（举例）。④与锁钥模型的区别:酶构象有柔性→优化结合→催化效率大大提升（区别）。⑤对所有酶的底物特异性识别和催化机制有普遍意义（意义）。", "kps": "①定义(1分)②Koshland 1958(1分)③己糖激酶经典例子(1分)④与锁钥模型区别(1分)⑤普遍意义(1分)", "kp": "sugar1_s1_6"}, {"id": "sugar1_term_9", "modI": 1, "term": "Cori循环/乳酸循环(Cori Cycle)", "def": "①肌肉与肝脏之间通过乳酸和葡萄糖的相互转化形成的代谢循环（定义）。②过程:肌肉酵解(无氧)→丙酮酸→乳酸(LDH)→进入血液→肝脏→乳酸→丙酮酸→糖异生→葡萄糖→血液→肌肉(重新酵解)（过程）。③能量:肌肉酵解1G净产2ATP,肝脏合成1G消耗6ATP→净亏4ATP（能量收支）。④生理意义:①回收废物乳酸(解毒)→②回收碳骨架(糖异生)→③紧急供能(无氧条件下维持血糖)（意义）。⑤乳酸过量→酸中毒,Cori循环受血乳酸、胰岛素和肾上腺素调控（调控）。", "kps": "①定义(1分)②完整过程(2分)③能量收支(1分)④三大生理意义(1分)⑤调控(1分)", "kp": "sugar1_s1_24"}, {"id": "sugar1_term_15", "modI": 1, "term": "生醇发酵(Alcoholic Fermentation)", "def": "①酵母在无氧条件下将葡萄糖分解为乙醇和CO2并再生NAD+的过程（定义）。②两步反应:①丙酮酸脱羧酶(PDC,TPP辅酶)→乙醛+CO2;②乙醇脱氢酶(ADH)→乙醇+NAD+→NAD+再生维持酵解（过程）。③总反应:G+2ADP+2Pi→2乙醇+2CO2+2ATP+2H2O（总反应式）。④关键:再生NAD+→保证酵解持续运行→提供ATP→使酵母在无氧下生存（生理意义）。⑤与乳酸发酵对比:共同点→再生NAD+;不同点→产物不同(乙醇vs乳酸),CO2出现(酵母才有)（对比）。", "kps": "①定义(1分)②两步过程(1分)③总反应式(1分)④NAD+再生(1分)⑤与乳酸发酵对比(1分)", "kp": "sugar1_s1_22"}, {"id": "sugar1_term_21", "modI": 1, "term": "2,3-二磷酸甘油酸(2,3-BPG)", "def": "①1,3-BPG的异构体,由变位酶催化产生（来源）。②结构:2,3-BPG的C2磷酸为高能键→可降解产生ATP,但在RBC中不降解→积累到高水平(5mM)（结构特点）。③核心功能:与Hb β亚基结合→稳定T态(deoxyHb)→O2解离曲线右移→P50(氧合饱和度50%的氧分压)升高→有利于组织O2释放（功能）。④高山/缺氧/贫血→RBC中2,3-BPG水平↑→组织可用O2↑→适应机制（调控）。⑤RBC中PPP失调→NADPH↓→GSH↓→2,3-BPG因积累而发挥代偿O2运输（与PPP的联系）。", "kps": "①来源(1分)②结构特点(1分)③与Hb结合→O2释放(2分)④高山适应(1分)⑤与PPP联系(1分)", "kp": "sugar1_s1_14"}]}, {"i": 2, "name": "模块三：TCA与有氧分解", "slides": [{"i": 0, "sec": "第六章 糖代谢", "title": "有氧分解总览 (p53)", "notes": "G→酵解→丙酮酸→有氧→乙酰CoA→TCA环→CO2+H2O+ATP。\u000b无氧→乳酸(LDH)。\u000bTCA在基质，呼吸链在内膜。\u000b胞质NADH通过苹果酸穿梭或甘油-3-P穿梭进入线粒体。", "page": 53, "level": "掌握", "img": "assets/img/sugar1/p053.jpg", "anim": null, "fig": "", "points": ["①葡萄糖→酵解→丙酮酸→乙酰CoA→TCA", "②无氧时丙酮酸经LDH生成乳酸", "③TCA在线粒体基质，呼吸链在内膜", "④胞质NADH经苹果酸或甘油-3-P穿梭入线粒体"], "check": null, "cards": null}, {"i": 1, "sec": "第六章 糖代谢", "title": "有氧分解三阶段 (p54)", "notes": "三阶段：Ⅰ-丙酮酸→乙酰CoA+CO2(PDH系,E1+E2+E3)；\u000bⅡ-TCA循环(柠檬酸→OAA,8步)；\u000bⅢ-NADH/FADH2→电子传递链→氧化磷酸化→ATP。\u000b阶段Ⅲ产能最多(~26ATP)。", "page": 54, "level": "掌握", "img": "assets/img/sugar1/p054.jpg", "anim": null, "fig": "", "points": ["①阶段Ⅰ：丙酮酸→乙酰CoA+CO2，由PDH系催化", "②阶段Ⅱ：TCA循环8步，柠檬酸→草酰乙酸", "③阶段Ⅲ：电子传递链+氧化磷酸化产ATP", "④阶段Ⅲ产能最多，约26个ATP"], "check": null, "cards": null}, {"i": 2, "sec": "第六章 糖代谢", "title": "PDH酶系总述 (p55)", "notes": "一、丙酮酸的氧化脱羧(不可逆)：丙酮酸+CoA+NAD+→乙酰CoA+CO2+NADH。\u000bPDH酶系催化→连接酵解和TCA的桥梁反应。\u000b反应过程：脱羧→酰基转移→再氧化→生成NADH。\u000bTPP+硫辛酸+CoA+NAD+四辅酶。", "page": 55, "level": "掌握", "img": "assets/img/sugar1/p055.jpg", "anim": null, "fig": "", "points": ["①丙酮酸氧化脱羧不可逆，生成乙酰CoA", "②PDH系是连接酵解与TCA的桥梁", "③过程：脱羧→酰基转移→再氧化→生成NADH", "④四种辅酶：TPP、硫辛酸、CoA、NAD+"], "check": null, "cards": null}, {"i": 3, "sec": "第六章 糖代谢", "title": "PDH酶系组成 (p56)", "notes": "3个酶：丙酮酸脱氢酶(E1,24亚基)+二氢硫辛酰转乙酰基酶(E2,24辅基含Lys)+二氢硫辛酰脱氢酶(E3,12亚基)。\u000b6辅因子：TPP(E1)、FAD(E3)、NAD+、硫辛酸(E2)、CoA、Mg2+。\u000bE.coli中合计60个亚基。", "page": 56, "level": "掌握", "img": "assets/img/sugar1/p056.jpg", "anim": null, "fig": "", "points": ["①E1丙酮酸脱氢酶，24亚基，含TPP", "②E2二氢硫辛酰转乙酰基酶，含硫辛酸和Lys", "③E3二氢硫辛酰脱氢酶，12亚基，含FAD", "④6种辅因子：TPP、FAD、NAD+、硫辛酸、CoA、Mg2+"], "check": null, "cards": null}, {"i": 4, "sec": "第六章 糖代谢", "title": "PDH反应机制 (p57-p58) (p5)", "notes": "反应历程：①TPP→HETPP脱羧；\u000b②乙酰基→硫辛酰胺→乙酰硫辛酸(摆臂传递)→CoA→乙酰CoA；\u000b③硫辛酸→再氧化→FAD→FADH2→NADH。\u000b硫辛酸与E2的Lys ε-NH2共价相连→柔性臂约14Å(摆臂传递)。", "page": 5, "level": "掌握", "img": "assets/img/sugar1/p005.jpg", "anim": null, "fig": "", "points": ["①TPP介导脱羧生成HETPP", "②乙酰基经硫辛酸摆臂传给CoA生成乙酰CoA", "③硫辛酸再氧化经FAD传给NAD+生成NADH", "④硫辛酸与E2的Lys共价相连，柔性臂约14Å"], "check": null, "cards": null}, {"i": 5, "sec": "第六章 糖代谢", "title": "TCA环定义 (p59)", "notes": "二、三羧酸循环(Krebs环/柠檬酸循环)。\u000bHans Krebs,1953年诺贝尔化学奖。\u000b部位：线粒体基质。\u000b步骤：8步。\u000b定义：乙酰CoA→一系列氧化脱羧→生成CO2+H2O+能量。\u000b三大调控点：柠檬酸合酶/异柠檬酸脱氢酶/α-KG脱氢酶。", "page": 59, "level": "掌握", "img": "assets/img/sugar1/p059.jpg", "anim": null, "fig": "", "points": ["①TCA又称Krebs环或柠檬酸循环，Krebs获1953诺奖", "②部位在线粒体基质，共8步", "③乙酰CoA经氧化脱羧生成CO2和能量", "④三大调控点：柠檬酸合酶、异柠檬酸脱氢酶、α-KG脱氢酶"], "check": null, "cards": null}, {"i": 6, "sec": "第六章 糖代谢", "title": "TCA环全景图 (p60)", "notes": "8步TCA循环全景：柠檬酸→顺乌头酸→异柠檬酸→α-酮戊二酸→琥珀酰CoA→琥珀酸→延胡索酸→苹果酸→草酰乙酸→回到柠檬酸。\u000b8种有机酸依次有序相互转化，每轮净摄入乙酰基→排出2CO2。", "page": 60, "level": "掌握", "img": "assets/img/sugar1/p060.jpg", "anim": null, "fig": "全景图展示TCA循环8步反应及8种有机酸的依次转化，从柠檬酸出发最终回到草酰乙酸。读图时注意每步的酶和产物，以及两处氧化脱羧释放CO2的位置。", "points": ["①8步循环：柠檬酸→顺乌头酸→异柠檬酸→α-KG", "②继续：琥珀酰CoA→琥珀酸→延胡索酸→苹果酸→OAA", "③8种有机酸有序互变，OAA回到起点", "④每轮净摄入乙酰基，排出2分子CO2"], "check": null, "cards": null}, {"i": 7, "sec": "第六章 糖代谢", "title": "TCA第1步-柠檬酸合酶 (p61)", "notes": "乙酰CoA+OAA→柠檬酸+CoA —柠檬酸合酶— 不可逆！\u000b🔴。\u000b三个调控点之首。\u000b机制：乙酰CoA中甲基的H+脱离→乙酰基碳负对OAA的羰基亲核→柠檬酰-CoA→水解→柠檬酸+CoA。\u000b不可逆决定TCA方向。", "page": 61, "level": "掌握", "img": "assets/img/sugar1/p061.jpg", "anim": null, "fig": "", "points": ["①乙酰CoA+OAA→柠檬酸+CoA，不可逆", "②TCA三个调控点之首", "③机制：乙酰基碳负亲核攻击OAA羰基", "④不可逆决定TCA整体方向"], "check": null, "cards": null}, {"i": 8, "sec": "第六章 糖代谢", "title": "TCA第2步-乌头酸酶 (p62)", "notes": "柠檬酸→顺乌头酸→异柠檬酸 —乌头酸酶— 可逆。\u000b通过形成顺乌头酸中间体的两步反应完成OH的迁移。\u000b⒈脱水→顺乌头酸；\u000b⒉再水化→异柠檬酸(C2上新OH)。\u000b注意：乌头酸酶不对称催化(仅作用一个臂)。", "page": 62, "level": "理解", "img": "assets/img/sugar1/p062.jpg", "anim": null, "fig": "", "points": ["①柠檬酸→顺乌头酸→异柠檬酸，可逆", "②经脱水再水化两步迁移OH", "③C2上生成新OH", "④乌头酸酶不对称催化，仅作用一个臂"], "check": null, "cards": null}, {"i": 9, "sec": "第六章 糖代谢", "title": "TCA第3步-异柠檬酸脱氢酶 (p63)", "notes": "异柠檬酸→α-酮戊二酸+CO2+NADH —异柠檬酸脱氢酶— 不可逆！\u000b🔴。\u000b三个调控点之二。\u000bTCA第一次脱氢+脱羧。\u000b产生第一个NADH+第一个CO2。\u000b受NADH/ATP抑制，ADP/NAD+激活。", "page": 63, "level": "掌握", "img": "assets/img/sugar1/p063.jpg", "anim": null, "fig": "", "points": ["①异柠檬酸→α-KG+CO2+NADH，不可逆", "②三个调控点之二", "③TCA第一次脱氢+脱羧", "④NADH/ATP抑制，ADP/NAD+激活"], "check": null, "cards": null}, {"i": 10, "sec": "第六章 糖代谢", "title": "TCA第4步-α-KG脱氢酶系 (p64)", "notes": "α-酮戊二酸+CoA+NAD+→琥珀酰CoA+CO2+NADH —α-KG脱氢酶系— 不可逆！\u000b🔴。\u000b三个调控点之三。\u000bTCA第二次脱氢+脱羧。\u000b高度类似PDH(同样的5辅酶：TPP/FAD/NAD+/硫辛酸/CoA)。\u000b会产生第二个NADH+第二个CO2。", "page": 64, "level": "掌握", "img": "assets/img/sugar1/p064.jpg", "anim": null, "fig": "", "points": ["①α-KG+CoA+NAD+→琥珀酰CoA+CO2+NADH", "②不可逆，三个调控点之三", "③第二次脱氢+脱羧", "④类似PDH，5辅酶相同"], "check": null, "cards": null}, {"i": 11, "sec": "第六章 糖代谢", "title": "TCA第5步-琥珀酰CoA合成酶 (p65)", "notes": "琥珀酰CoA+GDP(GDP)+Pi→琥珀酸+GTP(ATP)+CoA —底物水平磷酸化！\u000b琥珀酰CoA水解△G0'=-33.47kJ/mol 覆盖 GTP生成△G0'=+30.54kJ/mol。\u000b净△G0'=-2.93kJ/mol→可逆。\u000bTCA唯一一次底物磷酸化。", "page": 65, "level": "掌握", "img": "assets/img/sugar1/p065.jpg", "anim": null, "fig": "", "points": ["①琥珀酰CoA+GDP+Pi→琥珀酸+GTP+CoA", "②底物水平磷酸化，TCA唯一一次", "③水解ΔG0'=-33.47覆盖GTP生成+30.54", "④净ΔG0'=-2.93kJ/mol，可逆"], "check": null, "cards": null}, {"i": 12, "sec": "第六章 糖代谢", "title": "TCA第6步-琥珀酸脱氢酶 (p66)", "notes": "琥珀酸+FAD→延胡索酸+FADH2 —琥珀酸脱氢酶—。\u000b第三次脱氢。\u000bTCA中唯一嵌入线粒体内膜的酶=呼吸链复合物II！\u000b大呼吸链复合物含SDH SDHA/B/C/D亚基。\u000bFADH2→CoQ→复合物III→IV。", "page": 66, "level": "掌握", "img": "assets/img/sugar1/p066.jpg", "anim": null, "fig": "", "points": ["①琥珀酸+FAD→延胡索酸+FADH2", "②第三次脱氢", "③唯一嵌入内膜的酶=呼吸链复合物II", "④FADH2经CoQ→复合物III→IV"], "check": null, "cards": null}, {"i": 13, "sec": "第六章 糖代谢", "title": "TCA第7步-延胡索酸酶 (p67)", "notes": "延胡索酸+H2O→苹果酸 —延胡索酸酶— 可逆。\u000b立体特异反式加成：水分子对延胡索酸双键特定面加→只产生L-苹果酸。\u000b延胡索酸为反式化合物，水分子反式加成→苹果酸的L构型。", "page": 67, "level": "理解", "img": "assets/img/sugar1/p067.jpg", "anim": null, "fig": "", "points": ["①延胡索酸+H2O→苹果酸，可逆", "②立体特异反式加成", "③水对双键特定面加成", "④只生成L-苹果酸"], "check": null, "cards": null}, {"i": 14, "sec": "第六章 糖代谢", "title": "TCA第8步-苹果酸脱氢酶 (p68)", "notes": "苹果酸+NAD+→OAA+NADH+H+ —苹果酸脱氢酶—。\u000b第四次脱氢(产生NADH)。\u000b反应平衡偏向苹果酸方向。\u000b但OAA被柠檬酸合酶不断消耗→拉动反应向正向进行→TCA环可循环。", "page": 68, "level": "掌握", "img": "assets/img/sugar1/p068.jpg", "anim": null, "fig": "", "points": ["①苹果酸+NAD+→OAA+NADH+H+", "②第四次脱氢，产生NADH", "③平衡偏向苹果酸方向", "④OAA被柠檬酸合酶消耗拉动正向"], "check": null, "cards": null}, {"i": 15, "sec": "第六章 糖代谢", "title": "TCA环小结 (p69)", "notes": "总反应：CH3COSCoA+3NAD++FAD+GDP+Pi+2H2O→2CO2+CoASH+3NADH+FADH2+GTP。\u000b⚫三处不可逆：1(柠檬酸合酶)、3(异柠檬酸脱氢酶)、4(α-KG脱氢酶系)。\u000b⚫每轮纳入1个乙酰基→消耗2H2O→放出2CO2。\u000b⚫草酰乙酸是新合成的。", "page": 69, "level": "掌握", "img": "assets/img/sugar1/p069.jpg", "anim": null, "fig": "", "points": ["①总反应式：乙酰CoA+3NAD⁺+FAD+GDP+Pi+2H₂O→2CO₂+3NADH+FADH₂+GTP", "②三处不可逆：柠檬酸合酶、异柠檬酸脱氢酶、α-KG脱氢酶系", "③每轮消耗2H₂O、放出2CO₂，纳入1个乙酰基", "④草酰乙酸需新合成以维持循环"], "check": null, "cards": null}, {"i": 16, "sec": "第六章 糖代谢", "title": "乌头酸酶不对称催化 (p70)", "notes": "柠檬酸为对称分子(C4=CH2-COOH在两侧对称)。\u000b但乌头酸酶只作用于其中一侧-CH2COOH臂→产生(2R,3S)-异柠檬酸。\u000b若误作用另一侧→将生成高柠檬酸——活体内不会发生→酶的立体特异性。", "page": 70, "level": "理解", "img": "assets/img/sugar1/p070.jpg", "anim": null, "fig": "", "points": ["①柠檬酸分子对称，但乌头酸酶只作用于一侧-CH₂COOH臂", "②产物为(2R,3S)-异柠檬酸，具立体特异性", "③若作用于另一侧则生成高柠檬酸，体内不发生"], "check": null, "cards": null}, {"i": 17, "sec": "第六章 糖代谢", "title": "TCA环能量计算 (p71)", "notes": "每轮产：⚫3NADH→7.5ATP(×2.5)⚫1FADH2→1.5ATP(×1.5)⚫1GTP(≈1ATP)→共10ATP/轮。\u000b每分子葡萄糖经有氧彻底氧化→2乙酰CoA→2轮TCA=20ATP。\u000b当前P/O标准计算。\u000b旧P/O=12次/轮(NADH×3=9+FADH2×2=2+GTP=12)。", "page": 71, "level": "掌握", "img": "assets/img/sugar1/p071.jpg", "anim": null, "fig": "", "points": ["①每轮产3NADH(7.5ATP)+1FADH₂(1.5ATP)+1GTP(1ATP)=10ATP", "②葡萄糖→2乙酰CoA→2轮TCA=20ATP", "③旧P/O标准下每轮为12ATP"], "check": null, "cards": null}, {"i": 18, "sec": "第六章 糖代谢", "title": "葡萄糖有氧总ATP计算 (p72)", "notes": "G→2丙酮酸: 净+2ATP+2NADH(c)→5ATP(苹果酸穿梭)。\u000b2丙酮酸→2乙酰CoA: 2NADH(m)→5ATP。\u000b2轮TCA: 2×10=20ATP。\u000b总计：30(甘油-3-P穿梭)~32ATP(苹果酸穿梭)。", "page": 72, "level": "掌握", "img": "assets/img/sugar1/p072.jpg", "anim": null, "fig": "", "points": ["①糖酵解：净+2ATP+2NADH(c)，苹果酸穿梭折5ATP", "②2丙酮酸→2乙酰CoA：2NADH(m)→5ATP", "③2轮TCA：20ATP", "④总计30(甘油-3-P穿梭)~32ATP(苹果酸穿梭)"], "check": null, "cards": null}, {"i": 19, "sec": "第六章 糖代谢", "title": "NADH穿梭总述 (p73)", "notes": "细胞质产生的NADH需进入线粒体才能被呼吸链氧化。\u000b两种穿梭系统：①苹果酸-天冬氨酸穿梭(肝/肾/心肌,P/O=2.5→2NADH→5ATP)。\u000b②甘油-3-磷酸穿梭(肌肉/神经,P/O=1.5→2NADH→3ATP)。\u000b穿梭方式决定ATP产量。", "page": 73, "level": "理解", "img": "assets/img/sugar1/p073.jpg", "anim": null, "fig": "", "points": ["①胞质NADH须进入线粒体才能被呼吸链氧化", "②苹果酸-天冬氨酸穿梭：肝/肾/心肌，P/O=2.5→5ATP", "③甘油-3-磷酸穿梭：肌肉/神经，P/O=1.5→3ATP", "④穿梭方式决定ATP产量"], "check": null, "cards": null}, {"i": 20, "sec": "第六章 糖代谢", "title": "苹果酸穿梭详细 (p74)", "notes": "肝/肾/心肌路径：胞质苹果酸脱氢酶→苹果酸、谷氨酸→等移入线粒体。\u000b基质：苹果酸→草酰乙酸(产生NADH)→谷氨酸→天冬氨酸→穿出。\u000b净结果：胞质NADH氧化当量→线粒体NADH→复合物I→P/O=2.5。", "page": 74, "level": "了解", "img": "assets/img/sugar1/p074.jpg", "anim": null, "fig": "", "points": ["①胞质苹果酸脱氢酶将NADH转为苹果酸，与谷氨酸等移入线粒体", "②基质中苹果酸→草酰乙酸产生NADH，谷氨酸→天冬氨酸穿出", "③净结果：胞质NADH当量→线粒体NADH→复合物I，P/O=2.5"], "check": null, "cards": null}, {"i": 21, "sec": "第六章 糖代谢", "title": "甘油-3-磷酸穿梭 (p75)", "notes": "肌肉/神经路径：DHAP→甘油-3-磷酸(G3PDH)→G3P穿入线粒体→基质G3PDH(嵌入线粒体膜)→FAD→FADH2→CoQ。\u000b净结果：胞质NADH→FADH2→CoQ(P/O=1.5)比苹果酸穿梭低。", "page": 75, "level": "了解", "img": "assets/img/sugar1/p075.jpg", "anim": null, "fig": "", "points": ["①DHAP→甘油-3-磷酸(G3PDH)，穿入线粒体", "②基质G3PDH(膜结合)将G3P转为DHAP，FAD→FADH₂→CoQ", "③净结果：胞质NADH→FADH₂→CoQ，P/O=1.5，低于苹果酸穿梭"], "check": null, "cards": null}, {"i": 22, "sec": "第六章 糖代谢", "title": "TCA生理意义 (p76)", "notes": "两大意义：①是机体获得能量最有效方式→脱氢经氧化磷酸化→产生大量ATP。\u000b②将糖、脂、蛋白质、核酸四大物质代谢联系起来——TCA是代谢网络中枢。\u000bTCA中间物→各类物质合成的C骨架前体。", "page": 76, "level": "掌握", "img": "assets/img/sugar1/p076.jpg", "anim": null, "fig": "", "points": ["①是机体获能最有效方式，脱氢经氧化磷酸化产大量ATP", "②联系糖、脂、蛋白质、核酸四大代谢，是代谢网络中枢", "③中间物为各类物质合成提供C骨架前体"], "check": null, "cards": null}, {"i": 23, "sec": "第六章 糖代谢", "title": "四大物质代谢全景 (p77)", "notes": "教材第378页全彩代谢网络图→展示糖、脂、蛋白质和核酸共同的中间代谢池。\u000bG-6-P→丙酮酸→乙酰CoA→TCA——糖代谢为主线。\u000b蛋白质→各种氨基酸→TCA(转氨)。\u000b脂肪→脂肪酸+甘油→TCA(β-氧化等)。", "page": 77, "level": "掌握", "img": "assets/img/sugar1/p077.jpg", "anim": null, "fig": "全彩代谢网络图展示四大物质代谢的交叉点：读图时先找中心枢纽乙酰CoA和TCA循环，再沿箭头追溯各物质分解产物如何汇入同一代谢池。", "points": ["①糖、脂、蛋白质、核酸通过共同中间代谢池相连", "②G-6-P→丙酮酸→乙酰CoA→TCA是代谢主线", "③氨基酸经转氨作用进入TCA", "④脂肪酸经β-氧化生成乙酰CoA入TCA"], "check": null, "cards": null}, {"i": 24, "sec": "第六章 糖代谢", "title": "乙醛酸循环概述(p78-p79) (p25)", "notes": "四、乙醛酸循环—TCA支路。\u000b部位：植物乙醛酸小体/微生物。\u000b关键酶：异柠檬酸裂解酶→乙醛酸+琥珀酸；\u000b苹果酸合酶→乙醛酸+乙酰CoA→苹果酸。\u000b绕过两个脱羧步骤→净合成4C化合物。\u000b动物体不存在。", "page": 25, "level": "了解", "img": "assets/img/sugar1/p025.jpg", "anim": null, "fig": "", "points": ["①乙醛酸循环是TCA循环的支路，存在于植物和微生物", "②关键酶：异柠檬酸裂解酶和苹果酸合酶", "③绕过两次脱羧，实现4C化合物的净合成", "④动物体内不存在此途径"], "check": null, "cards": null}, {"i": 25, "sec": "第六章 糖代谢", "title": "乙醛酸小体电镜 (p80)", "notes": "萌发黄瓜种子电镜照片：乙醛酸小体、脂质体、线粒体并存。\u000b脂肪→糖转变的重要证据。\u000b高脂种子萌发时→大量脂肪酸β-氧化→乙酰CoA→乙醛酸循环→回补碳骨架→糖异生→供新生组织生长。", "page": 80, "level": "了解", "img": "assets/img/sugar1/p080.jpg", "anim": null, "fig": "电镜照片中三种细胞器并存：脂质体提供脂肪酸，乙醛酸小体执行乙醛酸循环，线粒体供能，共同完成脂肪→糖的转变。", "points": ["①电镜显示乙醛酸小体、脂质体、线粒体并存", "②是脂肪转变为糖的重要证据", "③高脂种子萌发时脂肪酸β-氧化产生大量乙酰CoA", "④乙酰CoA经乙醛酸循环回补碳骨架供糖异生"], "check": null, "cards": null}, {"i": 26, "sec": "第六章 糖代谢", "title": "乙醛酸小体代谢联系(p81-p82) (p27)", "notes": "乙醛酸循环意义：①以二碳物(乙酰CoA)为起始物合成TCA中间物→回补TCA。\u000b②植物/微生物中脂肪变为糖的途径——脂肪酸→乙酰CoA→乙醛酸→苹果酸→草酰乙酸→糖异生→糖。\u000b动物无此路，故不能脂转糖。", "page": 27, "level": "了解", "img": "assets/img/sugar1/p027.jpg", "anim": null, "fig": "", "points": ["①以乙酰CoA为起始物合成TCA中间物，回补TCA", "②植物和微生物中脂肪转变为糖的途径", "③动物无乙醛酸循环，故不能实现脂转糖"], "check": null, "cards": null}, {"i": 27, "sec": "第六章 糖代谢", "title": "第四节-磷酸戊糖途径 (p83)", "notes": "第四节标题页：磷酸戊糖途径(Pentose Phosphate Pathway, PPP/HMP)。\u000b部位：细胞质。\u000b两阶段：氧化阶段(G-6-P→5-P-核酮糖+2NADPH+CO2)；\u000b非氧化阶段(分子重排→G-6-P再生)。\u000b总：6G-6-P+12NADP+→6CO2+5G-6-P+12NADPH。", "page": 83, "level": "掌握", "img": "assets/img/sugar1/p083.jpg", "anim": null, "fig": "", "points": ["①PPP在细胞质中进行，又称HMP途径", "②氧化阶段：G-6-P→核酮糖-5-P+2NADPH+CO2", "③非氧化阶段：分子重排使G-6-P再生", "④总反应：6G-6-P+12NADP+→6CO2+5G-6-P+12NADPH"], "check": null, "cards": null}], "mcq": [{"id": "sugar1_mcq_31", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PDH辅因子不包括？", "o": ["A. TPP", "B. NAD+", "C. CoA", "D. PLP"], "a": "D", "e": "PDH:TPP/FAD/NAD+/硫辛酸/CoA。PLP是转氨酶辅酶。两者的5种辅酶=3种酶的辅基或底物。", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_32", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "TCA中唯一膜结合酶？", "o": ["A. 柠檬酸合酶", "B. 琥珀酸脱氢酶(复合物II)", "C. 苹果酸脱氢酶", "D. 延胡索酸酶"], "a": "B", "e": "琥珀酸脱氢酶嵌入线粒体内膜→同时是呼吸链复合物II。其余7种酶均在基质。", "kp": "sugar1_s2_7"}, {"id": "sugar1_mcq_33", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乌头酸酶的作用特点？", "o": ["A. 对称催化两个臂", "B. 不对称催化,仅作用一个-CH2COOH臂", "C. 不需辅酶", "D. 作用于C=O"], "a": "B", "e": "柠檬酸是对称分子,但乌头酸酶只催化其中一个-CH2COOH臂→产生(2R,3S)-异柠檬酸。立体特异性经典!", "kp": "sugar1_s2_16"}, {"id": "sugar1_mcq_34", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "柠檬酸合酶催化反应机制？", "o": ["A. 直接缩合", "B. 乙酰CoA甲基脱H+→碳负离子亲核攻击OAA羰基→柠檬酰CoA→水解→柠檬酸+CoA", "C. 自由基反应", "D. FAD介导"], "a": "B", "e": "OAA+乙酰CoA+H2O→柠檬酸+CoA。这是TCA首步不可逆调控点。", "kp": "sugar1_s2_7"}, {"id": "sugar1_mcq_35", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "延胡索酸酶催化有什么特点？", "o": ["A. 加水,反式立体特异加成→L-苹果酸", "B. 脱氢", "C. 脱羧", "D. 转氨"], "a": "A", "e": "延胡索酸+H2O→L-苹果酸。立体特异反式加成:水从特定面攻击→仅产L-Malate。酶的立体特异性经典例子!", "kp": "sugar1_s2_13"}, {"id": "sugar1_mcq_36", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "TCA中唯一底物水平磷酸化发生在哪一步？", "o": ["A. 柠檬酸合酶", "B. 琥珀酰CoA合成酶(第5步)", "C. 苹果酸脱氢酶", "D. a-KG脱氢酶"], "a": "B", "e": "琥珀酰CoA+H2O+GDP→琥珀酸+GTP(动物产GTP,植物产ATP)。△G0'≈0→可逆。", "kp": "sugar1_s2_11"}, {"id": "sugar1_mcq_37", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乙醛酸循环存在于哪些生物？", "o": ["A. 所有生物", "B. 植物乙醛酸小体和微生物,动物体无", "C. 只有动物", "D. 只有人类"], "a": "B", "e": "乙醛酸循环是TCA支路→存在于植物/微生物→动物(含人)无。因此动物不能脂→糖!", "kp": "sugar1_s2_24"}, {"id": "sugar1_mcq_38", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乙醛酸循环的关键酶是什么？", "o": ["A. 柠檬酸合酶和MDH", "B. 异柠檬酸裂解酶+苹果酸合酶", "C. SDH和延胡索酸酶", "D. PDH和柠檬酸合酶"], "a": "B", "e": "异柠檬酸裂解酶→乙醛酸+琥珀酸(绕过两个脱羧)。苹果酸合酶→乙醛酸+乙酰CoA→苹果酸+CoA。", "kp": "sugar1_s2_24"}, {"id": "sugar1_mcq_39", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "为什么一分子葡萄糖在不同组织产ATP数不同？", "o": ["A. 酵解效率不同", "B. NADH穿梭方式不同(苹果酸P/O=2.5→32ATP;甘油-3-P P/O=1.5→30ATP)", "C. TCA不同", "D. 呼吸链不同"], "a": "B", "e": "肝/肾/心肌→苹果酸穿梭→P/O高→32ATP。肌肉/神经→甘油-3-P穿梭→P/O低→30ATP。穿梭方式决定ATP产量差异。", "kp": "sugar1_s2_18"}, {"id": "sugar1_mcq_40", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PDH酶系如何被调控？", "o": ["A. 变构调节", "B. 磷酸化/去磷酸化(Pyruvate脱氢酶激酶磷酸化E1=失活;磷酸酶去磷酸化=激活)", "C. 转录调控", "D. 不受调控"], "a": "B", "e": "PDH激酶磷酸化E1a→失活(ATP↑激活)。PDH磷酸酶去磷酸化→激活(Ca2+/胰岛素激活)。能量状态精细调控!", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_41", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "葡萄糖总ATP(苹果酸穿梭)？", "o": ["A. 30", "B. 32", "C. 36", "D. 38"], "a": "B", "e": "酵解(2ATP+5)+PDH(5)+TCAx2(20)=32。甘油-3-P穿梭=30。", "kp": "sugar1_s2_18"}, {"id": "sugar1_mcq_42", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "苹果酸穿梭vs甘油-3-P穿梭的区别？", "o": ["A. 完全相同", "B. 苹果酸P/O=2.5(NADH→复合物I),甘油-3-P P/O=1.5(FADH2→CoQ)", "C. 只在胞质", "D. 甘油-3-P效率更高"], "a": "B", "e": "苹果酸穿梭→NADH→复合物I→P/O=2.5;甘油-3-P穿梭→FADH2→CoQ→P/O=1.5。肝心肌用前者,肌神经用后者。", "kp": "sugar1_s2_21"}, {"id": "sugar1_mcq_43", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PPP最重要产物？", "o": ["A. ATP", "B. NADPH和5-P-核糖", "C. FADH2", "D. 乙酰CoA"], "a": "B", "e": "NADPH→脂肪酸/固醇合成+GSH再生;5-P-核糖→核酸合成前体。", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_44", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PPP氧化阶段的限速酶是什么？", "o": ["A. 6-P-葡萄糖酸脱氢酶", "B. G-6-P脱氢酶", "C. 转酮酶", "D. 转醛酶"], "a": "B", "e": "G-6-PDH是关键限速酶→受NADPH反馈抑制。G6PDH缺陷→NADPH↓→GSH↓→红细胞膜氧化→蚕豆病/溶血性贫血。", "kp": "sugar1_s2_1"}, {"id": "sugar1_mcq_45", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "转酮酶和转醛酶的区别？", "o": ["A. 完全相同", "B. 转酮酶转移2C单位(需TPP),转醛酶转移3C单位", "C. 转酮酶转移3C,转醛酶转移2C", "D. 都不需辅酶"], "a": "B", "e": "转酮酶(TPP)→转移2C;C5+C5→C3+C7。转醛酶(无辅酶)→转移3C二羟丙酮片段;C7+C3→C6+C4。", "kp": "sugar1_s2_16"}, {"id": "sugar1_mcq_46", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "蚕豆病(G-6-PDH缺陷)的分子机制？", "o": ["A. 胰岛素分泌不足", "B. G-6-PDH缺陷→NADPH↓→GSH↓→H2O2积累→红细胞膜氧化→溶血", "C. 肝损伤", "D. Hb变异"], "a": "B", "e": "G6PDH缺陷→PPP受阻→NADPH减少→GSH不能再生→H2O2/自由基↑→膜脂过氧化→红细胞脆性↑→溶血。蚕豆含强氧化物质→恶化。急性溶血性贫血!", "kp": "sugar1_s2_4"}], "judge": [], "fill": [{"id": "sugar1_fill_3", "modI": 2, "q": "三羧酸循环中唯一的膜结合酶是________,它同时是呼吸链的________。", "a": "琥珀酸脱氢酶,复合物II", "kp": "sugar1_s2_24"}, {"id": "sugar1_fill_4", "modI": 2, "q": "乙醛酸循环的两个关键酶是________和________,此循环在________和________中存在,动物体________。", "a": "异柠檬酸裂解酶,苹果酸合酶,植物,微生物,不存在", "kp": "sugar1_s2_24"}, {"id": "sugar1_fill_6", "modI": 2, "q": "1分子葡萄糖经有氧彻底氧化净产________个ATP(苹果酸穿梭系统)或________个ATP(甘油-3-磷酸穿梭系统)。", "a": "32,30", "kp": "sugar1_s2_21"}, {"id": "sugar1_fill_7", "modI": 2, "q": "丙酮酸脱氢酶系包含3个酶(E1________、E2________、E3________)和5种辅酶(________、________、________、________、________)。", "a": "丙酮酸脱氢酶,二氢硫辛酰转乙酰基酶,二氢硫辛酰脱氢酶,TPP,FAD,NAD+,硫辛酸,CoA", "kp": "sugar1_s2_3"}, {"id": "sugar1_fill_10", "modI": 2, "q": "TCA循环每轮产生________分子NADH、________分子FADH2和________分子GTP,共约________个ATP。", "a": "3,1,1,10", "kp": "sugar1_s2_17"}], "short": [{"id": "sugar1_short_3", "modI": 2, "q": "简述三羧酸循环(TCA)的8步反应、产能和生理意义。", "a": "部位:线粒体基质。8步反应:\u000b①乙酰CoA+OAA→柠檬酸(柠檬酸合酶,不可逆!)\u000b②柠檬酸→顺乌头酸→异柠檬酸(乌头酸酶)\u000b③异柠檬酸→a-KG+CO2+NADH(异柠檬酸脱氢酶,不可逆!)\u000b④a-KG→琥珀酰CoA+CO2+NADH(a-KG脱氢酶系,不可逆!)\u000b⑤琥珀酰CoA→琥珀酸+GTP(合成酶,底物磷酸化)\u000b⑥琥珀酸→延胡索酸+FADH2(SDH,膜结合,复合物II)\u000b⑦延胡索酸→苹果酸(延胡索酸酶)\u000b⑧苹果酸→OAA+NADH(MDH)\u000b\u000b产能:3NADH(x2.5=7.5)+1FADH2(x1.5=1.5)+1GTP=10ATP/轮\u000b\u000b生理意义:①获得能量最有效方式;②是糖/脂/蛋白质/核酸四大物质代谢网络中枢;③中间产物为其他物质合成提供C骨架前体。", "kp": "sugar1_s2_22"}, {"id": "sugar1_short_4", "modI": 2, "q": "简述丙酮酸在细胞内的三条代谢去路,分别说明反应条件和生理意义。", "a": "丙酮酸为酵解终产物,三条去路:\u000b\u000b①有氧→乙酰CoA→TCA:丙酮酸脱氢酶系(PDH)催化,在线粒体基质进行,需TPP/硫辛酸/FAD/NAD+/CoA五种辅酶。产生NADH不可逆,连接酵解和TCA的关键反应。正常有氧条件下的主要去路。\u000b\u000b②无氧→乳酸(乳酸发酵):乳酸脱氢酶(LDH)催化,在肌肉/红细胞/乳酸菌中进行。NADH再氧化为NAD+保证酵解持续进行。运动时肌肉主要供能方式)。\u000b\u000b③无氧→乙醇(生醇发酵):丙酮酸脱羧酶(TPP)+乙醇脱氢酶(ADH)催化,在酵母中进行。NADH再氧化为NAD+,产CO2。酿酒/做面包的原理。\u000b\u000b②③的关键意义:在无氧条件下再生NAD+→保证酵解持续运行→维持ATP供应。", "kp": "sugar1_s2_22"}, {"id": "sugar1_short_5", "modI": 2, "q": "简述丙酮酸脱氢酶系(PDH)的组成、辅因子和调控机制。", "a": "部位:线粒体基质\u000b\u000b组成:3个酶\u000b• E1=丙酮酸脱氢酶(24亚基):TPP依赖\u000b• E2=二氢硫辛酰转乙酰基酶(24亚基):硫辛酸辅基\u000b• E3=二氢硫辛酰脱氢酶(12亚基):FAD依赖\u000b\u000b5种辅因子:TPP(E1)、CoA(E2底物)、硫辛酸(E2辅基)、NAD+(E3产物)、FAD(E3辅基)\u000b\u000b反应:丙酮酸+CoA+NAD+→乙酰CoA+CO2+NADH(不可逆)\u000b\u000b调控-磷酸化/去磷酸化:PDH激酶磷酸化E1→失活(ATP/NADH/Ac-CoA↑激活激酶);PDH磷酸酶去磷酸化→激活(Ca2+/胰岛素激活)。\u000b\u000b硫辛酸与E2 Lys共价相连→柔韧臂(约14A)→在E1/E2/E3间摆臂传递酰基。", "kp": "sugar1_s2_3"}, {"id": "sugar1_short_9", "modI": 2, "q": "简述乙醛酸循环的过程、关键酶和生理意义。", "a": "乙醛酸循环是TCA的支路,存在于植物乙醛酸小体和微生物,动物体不存在。\u000b\u000b过程(绕过两个脱羧步):\u000b①异柠檬酸(6C)→异柠檬酸裂解酶→乙醛酸(2C)+琥珀酸(4C)\u000b②乙醛酸(2C)+乙酰CoA(2C)→苹果酸合酶→苹果酸(4C)+CoA\u000b③苹果酸→草酰乙酸(常规TCA酶)\u000b④草酰乙酸+乙酰CoA→柠檬酸→异柠檬酸(常规TCA酶)\u000b\u000b关键酶:异柠檬酸裂解酶+苹果酸合酶(常规TCA无)\u000b\u000b生理意义:\u000b①以二碳物(乙酰CoA)合成TCA环中的4C中间物→回补TCA\u000b②植物/微生物中脂肪转变为糖的唯一途径:\u000b脂肪酸→b-氧化→乙酰CoA→乙醛酸循环→苹果酸→OAA→糖异生→葡萄糖\u000b③动物无此循环→不能将脂肪转为糖(乙酰CoA两个C在TCA中以CO2排出)", "kp": "sugar1_s2_24"}, {"id": "sugar1_short_12", "modI": 2, "q": "简述TCA循环的三步不可逆反应的调控机制。", "a": "TCA三个调控点(对应三个不可逆反应):\u000b\u000b①柠檬酸合酶:\u000b• 底物OAA和乙酰CoA↑→激活\u000b• NADH/ATP/柠檬酸↑→抑制(产物反馈)\u000b• 琥珀酰CoA积累→竞争性抑制\u000b\u000b②异柠檬酸脱氢酶(最重要调控点):\u000b• ADP↑→别构激活(低能荷信号)\u000b• NAD+↑→激活\u000b• ATP/NADH↑→抑制(高能荷信号)\u000b• Ca2+↑→激活(呼应肌肉收缩、心率等能量需求↑)\u000b\u000b③a-酮戊二酸脱氢酶系:\u000b• 与PDH类似,受磷酸化/去磷酸化调控\u000b• NADH/ATP/琥珀酰CoA↑→抑制(产物反馈)\u000b• Ca2+↑→激活\u000b\u000b总体调控逻辑:细胞能量状态(ATP/ADP比)决定TCA速度。\u000bATP↑→TCA↓(不需要产能);ADP↑→TCA↑(需要产能)。\u000b三条途径与呼吸链速率协调一致(通过NADH/ADP的共价调节)。", "kp": "sugar1_s2_7"}], "calc": [{"id": "sugar1_calc_1", "modI": 2, "q": "计算1分子葡萄糖彻底氧化为CO2和H2O净产生多少ATP？(分别按苹果酸穿梭和甘油-3-磷酸穿梭系统计算)", "a": "苹果酸穿梭(肝/心肌):32 ATP; 甘油-3-磷酸穿梭(骨骼肌/神经):30 ATP", "steps": "【苹果酸穿梭(肝/肾/心肌):P/O≈2.5】\u000b• 酵解:G→2丙酮酸:净+2ATP+2NADH(c)→2NADH×2.5=5ATP(穿梭)\u000b• PDH:2×丙酮酸→2乙酰CoA+2NADH(m)→2×2.5=5ATP\u000b• TCA×2:2×(3NADH×2.5+1FADH2×1.5+1GTP)=2×10=20ATP\u000b• 总计:2+5+5+20=32ATP\u000b\u000b【甘油-3-磷酸穿梭(骨骼肌/神经):P/O≈1.5】\u000b• 酵解:2ATP+2NADH(c)→2×1.5=3ATP(穿梭)\u000b• PDH+TCA:5+20=25ATP(与上相同)\u000b• 总计:2+3+5+20=30ATP\u000b\u000b核心差异:2个胞质NADH→苹果酸穿梭(×2.5)=5ATP vs 甘油-3-P穿梭(×1.5)=3ATP\u000b所以不同组织ATP数:32(肝心肌)vs 30(骨骼肌神经)。", "kp": "sugar1_s2_21"}, {"id": "sugar1_calc_3", "modI": 2, "q": "计算一轮TCA循环的ATP产量和总产能。", "a": "10 ATP/轮", "steps": "一轮TCA产生的还原力:\u000b①异柠檬酸→a-KG: NADH×1\u000b②a-KG→琥珀酰CoA: NADH×1\u000b③琥珀酸→延胡索酸: FADH2×1(SDH/复合物II)\u000b④苹果酸→OAA: NADH×1\u000b\u000b+1分子GTP(由琥珀酰CoA合成酶生成)\u000b\u000b能量换算:\u000b• 3NADH×2.5ATP/NADH=7.5ATP\u000b• 1FADH2×1.5ATP/FADH2=1.5ATP\u000b• 1GTP×1ATP/GTP=1ATP\u000b\u000b总计:7.5+1.5+1=10ATP/轮\u000b\u000b每分子葡萄糖→2乙酰CoA→2轮TCA→20ATP\u000b\u000b旧P/O计算(NADH=3,FADH2=2):\u000b3NADH×3+1FADH2×2+1=12ATP/轮(旧教材值,注意区分)", "kp": "sugar1_s2_17"}, {"id": "sugar1_calc_4", "modI": 2, "q": "计算1分子丙酮酸彻底氧化为CO2和H2O净产生的ATP数。", "a": "12.5 ATP", "steps": "①丙酮酸→乙酰CoA+CO2(PDH):\u000bNADH(m)×1→×2.5=2.5ATP\u000b\u000b②乙酰CoA→TCA(1轮):\u000b3NADH×2.5+1FADH2×1.5+1GTP=10ATP\u000b\u000b总计:2.5+10=12.5ATP/每丙酮酸\u000b\u000b每分子葡萄糖→2丙酮酸→2×12.5=25ATP(来自PDH+TCA)\u000b+酵解:2ATP+2NADH(c)→5或3ATP(穿梭)\u000b=30或32ATP(与整体计算一致)", "kp": "sugar1_s2_18"}, {"id": "sugar1_calc_7", "modI": 2, "q": "论述三羧酸循环是四大物质代谢网络的中心枢纽。", "a": "TCA是糖/脂/蛋白质/核酸四大物质代谢的交汇点和中心枢纽", "steps": "TCA的中心枢纽地位体现在:\u000b\u000b①来自四大物质的碳骨架全部进入TCA:\u000b• 糖→EMP→丙酮酸→乙酰CoA→TCA\u000b• 脂肪→脂肪酸→b-氧化→乙酰CoA→TCA\u000b  甘油→磷酸丙糖→酵解→TCA\u000b• 蛋白质→氨基酸碳骨架→TCA五个入口:\u000b  Ala→丙酮酸, Asp→OAA, Glu→a-KG, Met/Val→琥珀酰CoA, Phe/Tyr→延胡索酸\u000b• 核酸→降解→产生碳骨架→可部分入TCA\u000b\u000b②TCA向外输出中间物满足合成需求:\u000b• 柠檬酸→脂肪酸(三羧酸移位酶)\u000b• a-KG→Glu家族aa,核苷酸\u000b• OAA→Asp家族aa\u000b• 琥珀酰CoA→卟啉色素(含血红素)\u000b\u000b③能量转换:\u000b• TCA的脱氢(NADH/FADH2)→呼吸链→氧化磷酸化→大量ATP\u000b• 是机体通过有机物分解获得能量最有效方式\u000b\u000b④关键调控:\u000b• 受NADH/ADP比调控→与呼吸链协调\u000b• 保证产能与需求匹配\u000b\u000b结论:TCA是代谢网络的一级中枢→任何物质代谢改变都会经TCA反映→生物维持稳态的关键途径", "kp": "sugar1_s2_23"}], "term": [{"id": "sugar1_term_10", "modI": 2, "term": "丙酮酸脱氢酶系(PDH Complex)", "def": "①催化丙酮酸→乙酰CoA+CO2+NADH的不可逆多酶复合体（定义）。②3种酶:E1-丙酮酸脱氢酶(24个亚基,TPP辅酶)、E2-二氢硫辛酰转乙酰基酶(24个亚基,硫辛酸辅基)、E3-二氢硫辛酰脱氢酶(12个亚基,FAD辅酶)（组成）。③5种辅因子:TPP/E2辅基硫辛酸/FAD/NAD+/CoA（辅因子）。④部位:线粒体基质。反应不可逆→连接酵解和TCA的关键桥梁（功能）。⑤调控:磷酸化(PDH激酶磷酸化E1→失活)/去磷酸化(PDH磷酸酶→激活)→受ATP/NADH/Ca2+调控（调控）。⑥与a-KG脱氢酶系高度相似(同样的E1/E2/E3架构+5辅酶)（相关性）。", "kps": "①定义(1分)②3种酶(1分)③5辅因子(1分)④连接酵解/TCA(1分)⑤磷酸化调控(1分)⑥与a-KG脱氢酶相似性(1分)", "kp": "sugar1_s2_2"}, {"id": "sugar1_term_11", "modI": 2, "term": "三羧酸循环(TCA Cycle/Krebs Cycle)", "def": "①乙酰CoA在线粒体基质经一系列氧化脱羧→生成CO2+H2O+大量能量的代谢循环（定义）。②发现者Hans Krebs,1953年诺贝尔化学奖（发现）。③8步反应:柠檬酸→异柠檬酸→a-KG→琥珀酰CoA→琥珀酸→延胡索酸→苹果酸→OAA→回到柠檬酸（过程）。④初次反应:乙酰CoA+OAA→柠檬酸(合酶,不可逆第一步)（启动）。⑤产能:每轮→3NADH+1FADH2+1GTP≈10ATP（产能）。⑥三步不可逆反应(柠檬酸合酶/异柠檬酸脱氢酶/a-KG脱氢酶)为三大调控点（调控）。", "kps": "①定义(1分)②Krebs 1953(1分)③8步(1分)④启动(1分)⑤产能(1分)⑥三调控点(1分)", "kp": "sugar1_s2_5"}, {"id": "sugar1_term_12", "modI": 2, "term": "乙醛酸循环(Glyoxylate Cycle)", "def": "①TCA循环的支路→经异柠檬酸裂解酶和苹果酸合酶两步绕过两个脱羧步→净合成4C化合物（定义）。②部位:植物乙醛酸小体和微生物→动物体不存在（分布）。③关键酶:异柠檬酸裂解酶(异柠檬酸→乙醛酸+琥珀酸)和苹果酸合酶(乙醛酸+乙酰CoA→苹果酸+CoA)（关键酶）。④意义:以2C物(乙酰CoA)合成TCA 4C中间物→回补TCA;植物/微生物使脂肪→糖成为可能（意义）。⑤动物无此循环→不能脂→糖→乙酰CoA只能走向TCA(两个C以CO2排出)（动物限制）。", "kps": "①定义(1分)②植物/微生物(1分)③2个关键酶(1分)④总体意义(1分)⑤动物无-不可脂-糖(1分)", "kp": "sugar1_s2_24"}, {"id": "sugar1_term_19", "modI": 2, "term": "糖异生(Gluconeogenesis)", "def": "①由非糖物质(乳酸/甘油/生糖氨基酸等)合成葡萄糖的过程（定义）。②部位:肝脏(主要)+肾脏皮质（部位）。③需绕过酵解3个不可逆步(①G-6-P→G(G-6-Pase)、③F-1,6-BP→F-6-P(FBPase-1)、⑩丙酮酸→PEP→OAA(两个酶:丙酮酸羧化酶和PEPCK))（绕道机制）。④能量消耗:2丙酮酸→1G消耗6ATP(≠酵解产2ATP→净亏4ATP→保证代谢单向性)（能量）。⑤基质:主要基质→乳酸(Cori循环)、甘油、生糖氨基酸;脂肪→乙酰CoA→动物不能糖异生(无乙醛酸循环)（限制）。", "kps": "①定义(1分)②肝/肾(1分)③绕过三步不可逆(2分)④能量消耗6ATP(1分)⑤基质来源(1分)", "kp": "sugar1_s2_25"}, {"id": "sugar1_term_20", "modI": 2, "term": "柠檬酸合酶(Citrate Synthase)", "def": "①催化TCA第一步不可逆反应:乙酰CoA+OAA+H2O→柠檬酸+CoA+H+（定义）。②机制:乙酰CoA甲基脱H+→碳负离子亲核攻击OAA羰基C→C-C键形成→柠檬酰-CoA→水解→柠檬酸+CoA（机制）。③特点:释放大量自由能→△G0'极其负→不可逆→TCA第一个调控点（特点）。④调控:受NADH/ATP/柠檬酸的反馈抑制,受ADP/NAD+激活（调控）。⑤意义:此步决定了乙酰CoA→TCA的速率→控制整个有氧氧化的通量（意义）。", "kps": "①反应式(1分)②机制(1分)③△G极负(1分)④调控(1分)⑤TCA速率控制(1分)", "kp": "sugar1_s2_7"}, {"id": "sugar1_term_22", "modI": 2, "term": "苹果酸-天冬氨酸穿梭(Malate-Aspartate Shuttle)", "def": "①胞质NADH还原当量转运到线粒体的主要穿梭系统之一（定义）。②部位:肝、肾、心肌（分布）。③过程:胞质苹果酸→进入线粒体→MDH→OAA+NADH(m)→NADH→复合物I;OAA→Asp出→再转化为苹果酸完成循环（过程）。④能量:每胞质NADH→1分子线粒体NADH→复合物I→P/O≈2.5ATP（产能）。⑤对比:甘油-3-P穿梭(肌肉/神经)→胞质NADH→FADH2→CoQ→P/O≈1.5ATP（对比）。", "kps": "①定义(1分)②肝/肾/心肌(1分)③过程(1分)④P/O≈2.5(1分)⑤与甘油-3-P穿梭对比(1分)", "kp": "sugar1_s2_20"}]}, {"i": 3, "name": "模块四：磷酸戊糖途径", "slides": [{"i": 0, "sec": "第六章 糖代谢", "title": "PPP反应过程总述 (p84)", "notes": "PPP全程：①氧化阶段→G-6-P脱氢脱羧→5-P-核酮糖+2NADPH(H+)+CO2；\u000b②非氧化阶段→磷酸戊糖经转酮酶/转醛酶分子重排→G-3-P+F-6-P→G-6-P再生。\u000bG-6-P完全氧化需要6轮循环。", "page": 84, "level": "掌握", "img": "assets/img/sugar1/p084.jpg", "anim": null, "fig": "", "points": ["①氧化阶段：脱氢脱羧生成核酮糖-5-P和2NADPH", "②非氧化阶段：转酮酶/转醛酶重排，G-6-P再生", "③G-6-P完全氧化需经6轮循环"], "check": null, "cards": null}, {"i": 1, "sec": "第六章 糖代谢", "title": "PPP氧化阶段①-② (p85)", "notes": "①G-6-P脱氢酶→6-磷酸葡萄糖酸内酯+NADPH(H+)。\u000b②内酯酶→6-磷酸葡萄糖酸+H2O。\u000bG-6-PDH是关键限速酶→受NADPH反馈抑制→G-6-PDH缺陷→NADPH↓→红细胞GSH↓→蚕豆病/溶血性贫血！\u000b临床上很常见。", "page": 85, "level": "掌握", "img": "assets/img/sugar1/p085.jpg", "anim": null, "fig": "", "points": ["①G-6-P脱氢酶催化生成6-磷酸葡萄糖酸内酯和NADPH", "②内酯酶水解生成6-磷酸葡萄糖酸", "③G-6-PDH是限速酶，受NADPH反馈抑制", "④G-6-PDH缺陷→NADPH↓→GSH↓→蚕豆病/溶血性贫血"], "check": null, "cards": null}, {"i": 2, "sec": "第六章 糖代谢", "title": "PPP氧化阶段③-⑤ (p86)", "notes": "③6-磷酸葡萄糖酸脱氢酶→5-P-核酮糖+CO2+NADPH(H+)。\u000b④异构酶→5-P-核糖。\u000b⑤差向酶→5-P-木酮糖。\u000b至此氧化阶段完成：G-6-P→2NADPH+CO2+5-P-核酮糖→核糖或木酮糖进入非氧化阶段。", "page": 86, "level": "掌握", "img": "assets/img/sugar1/p086.jpg", "anim": null, "fig": "", "points": ["①6-磷酸葡萄糖酸脱氢酶催化生成核酮糖-5-P+CO2+NADPH", "②异构酶将核酮糖-5-P转为核糖-5-P", "③差向酶将核酮糖-5-P转为木酮糖-5-P", "④氧化阶段完成：G-6-P→2NADPH+CO2+磷酸戊糖"], "check": null, "cards": null}, {"i": 3, "sec": "第六章 糖代谢", "title": "PPP非氧化阶段①-C5+C5→C7+C3 (p87)", "notes": "转酮酶(TPP辅酶)→5-P-木酮糖+5-P-核糖→3-P-甘油醛+7-P-景天糖。\u000bC5+C5→C3+C7的转酮反应。\u000b景天庚醇糖为7C单糖。\u000b转酮酶转移2C单位——TPP介导。", "page": 87, "level": "理解", "img": "assets/img/sugar1/p087.jpg", "anim": null, "fig": "", "points": ["①转酮酶催化C5+C5→C3+C7", "②转移2C单位，需TPP辅酶", "③产物：3-P-甘油醛+7-P-景天糖", "④景天糖为7C单糖"], "check": null, "cards": null}, {"i": 4, "sec": "第六章 糖代谢", "title": "PPP非氧化阶段②-C7+C3→C6+C4 (p88)", "notes": "转醛酶→7-P-景天糖+3-P-甘油醛→6-P-果糖+4-P-赤藓糖。\u000bC7+C3→C6+C4的转醛反应。\u000b转醛酶转移3C单位的二羟丙酮片段。\u000b赤藓糖为4C稀有糖。", "page": 88, "level": "理解", "img": "assets/img/sugar1/p088.jpg", "anim": null, "fig": "", "points": ["①转醛酶催化C7+C3→C6+C4", "②转移3C二羟丙酮片段", "③产物：6-P-果糖+4-P-赤藓糖", "④赤藓糖为4C稀有糖"], "check": null, "cards": null}, {"i": 5, "sec": "第六章 糖代谢", "title": "PPP非氧化阶段③-C5+C4→C6+C3 (p89)", "notes": "转酮酶→4-P-赤藓糖+5-P-木酮糖→6-P-果糖+3-P-甘油醛。\u000bC5+C4→C6+C3的转酮反应。\u000b新生成的6-P-果糖和3-P-甘油醛可分别经糖异生和酵解再生G-6-P完成PPP完整循环。", "page": 89, "level": "理解", "img": "assets/img/sugar1/p089.jpg", "anim": null, "fig": "", "points": ["①转酮酶催化C5+C4→C6+C3", "②再次生成6-P-果糖和3-P-甘油醛", "③产物可经糖异生/酵解再生G-6-P", "④完成PPP循环闭合"], "check": null, "cards": null}, {"i": 6, "sec": "第六章 糖代谢", "title": "非氧化阶段全景(p90-p91) (p7)", "notes": "完整非氧化网络：6分子5-P-核酮糖→经转酮酶(2次)和转醛酶(1次)→6C5⇌5C6的可逆变换。\u000b总：5C5→3C6+2C3→再重排回到G-6-P。\u000b磷酸丙糖异构酶+醛缩酶+果糖二磷酸酶同参与→完成循环。", "page": 7, "level": "理解", "img": "assets/img/sugar1/p007.jpg", "anim": null, "fig": "", "points": ["①非氧化阶段为可逆碳骨架重排网络", "②转酮酶2次、转醛酶1次", "③6C5⇌5C6互变", "④丙糖异构酶、醛缩酶、果糖二磷酸酶参与"], "check": null, "cards": null}, {"i": 7, "sec": "第六章 糖代谢", "title": "PPP小结 (p92)", "notes": "总反应式：6G-6-P+12NADP++7H2O→6CO2+5G-6-P+12NADPH(H+)+Pi。\u000b或简写：G-6-P+12NADP++7H2O→6CO2+12NADPH+Pi。\u000b氧化阶段：6G-6-P→6CO2+6核酮糖-5-P+12NADPH；\u000b非氧化：6核酮糖-5-P→5G-6-P+Pi。", "page": 92, "level": "掌握", "img": "assets/img/sugar1/p092.jpg", "anim": null, "fig": "", "points": ["①总式：G-6-P+12NADP++7H2O→6CO2+12NADPH+Pi", "②氧化阶段产NADPH和核酮糖-5-P", "③非氧化阶段再生5G-6-P", "④6G-6-P净生成5G-6-P"], "check": null, "cards": null}, {"i": 8, "sec": "第六章 糖代谢", "title": "PPP生理意义 (p93)", "notes": "三大意义：①生成NADPH(H+)→参与脂肪酸/固醇类合成+红细胞GSH再生(G6PDH缺陷→蚕豆病)。\u000b②生成5-P-核糖→参与核酸代谢(核糖核苷酸前体)。\u000b③是细胞内各种单糖的重要来源→碳骨架重排产生多种糖。", "page": 93, "level": "掌握", "img": "assets/img/sugar1/p093.jpg", "anim": null, "fig": "", "points": ["①产NADPH供脂肪酸/固醇合成", "②NADPH维持GSH，G6PDH缺陷致蚕豆病", "③产5-P-核糖供核酸合成", "④提供多种单糖碳骨架来源"], "check": null, "cards": null}], "mcq": [{"id": "sugar1_mcq_47", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "PPP每分子G-6-P完全氧化产生几个NADPH？", "o": ["A. 1", "B. 2(氧化阶段)", "C. 3", "D. 4"], "a": "B", "e": "氧化阶段:①G-6-PDH→NADPH;②6-P-G脱氢酶→NADPH。共2NADPH+1CO2/每G-6-P。", "kp": "sugar1_s3_0"}, {"id": "sugar1_mcq_48", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "PPP非氧化阶段的生理意义？", "o": ["A. 仅生成ATP", "B. 产生5-P-核糖(核酸合成)和G-6-P再生", "C. 生成脂肪酸", "D. 仅脱氢"], "a": "B", "e": "非氧化:6C5⇌5C6可逆转换→为核酸合成提供5-P-核糖→为氧化阶段再生G-6-P。再生组织PPP活跃!", "kp": "sugar1_s3_3"}, {"id": "sugar1_mcq_49", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "NADPH和NADH的区别？", "o": ["A. 完全相同", "B. NADPH用于合成代谢(脂肪酸/固醇),NADH用于氧化供能(呼吸链)", "C. NADPH只在PPP产生", "D. NADPH不含磷酸"], "a": "B", "e": "NADPH→合成代谢的还原力;NADH→氧化磷酸化的电子供体。两者生化功能根本不同!", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_50", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "葡萄糖完全氧化总反应式？", "o": ["A. G+6O2→6CO2+6H2O+能量(~32ATP)", "B. G→2乳酸", "C. G→2丙酮酸+2ATP", "D. 2G→CO2+ATP"], "a": "A", "e": "C6H12O6+6O2→6CO2+6H2O+~32ATP。CO2:PDH(2)+TCA(4)=6CO2。O2是最终电子受体→还原为H2O。", "kp": "sugar1_s3_0"}, {"id": "sugar1_mcq_51", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖/脂/蛋白质/核酸四大物质代谢枢纽是什么？", "o": ["A. 酵解", "B. TCA循环", "C. PPP", "D. 尿素循环"], "a": "B", "e": "TCA是四大物质代谢网络中枢。糖→乙酰CoA/丙酮酸→TCA;脂肪→b-氧化→乙酰CoA→TCA;蛋白质→氨基酸→各TCA中间物;核酸→降解→C骨架可入TCA。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_52", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "为何动物不能将脂肪酸→糖,而植物可以？", "o": ["A. 动物缺乏乙醛酸循环关键酶", "B. 动物脂肪酸不能b-氧化", "C. 植物有叶绿体", "D. 动物TCA效率更高"], "a": "A", "e": "动物无乙醛酸循环→乙酰CoA两个C以CO2排出→C骨架净增=0→无法净合成C4→不能糖异生。植物有乙醛酸循环→绕过脱羧步→脂→糖。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_53", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "G-6-P是糖代谢关键分支点,它的三条主要去路？", "o": ["A. ①酵解②PPP③糖原合成", "B. ①TCA②尿素循环③PPP", "C. ①酵解②生醇发酵③PPP", "D. ①PDH②TCA③尿素循环"], "a": "A", "e": "G-6-P分水岭:①磷酸化→酵解(EMP)→产能;②脱氢→PPP→NADPH+核糖;③可逆→合成糖原(储存)。三条去路取决于细胞需求。", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_54", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖异生绕过酵解哪三个不可逆步？", "o": ["A. 1/2/3", "B. 1/3/10→分别用G-6-Pase/FBPase-1/丙酮酸羧化酶+PEPCK绕过", "C. 7/8/10", "D. 1/7/10"], "a": "B", "e": "酵解3个不可逆步必须绕过:①G-6-P→G(G-6-Pase);③F-1,6-BP→F-6-P(FBPase-1);⑩PEP→Pyruvate(Pyruvate carboxylase+PEPCK)。需6ATP。", "kp": "sugar1_s3_5"}, {"id": "sugar1_mcq_55", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖原合成的关键酶和活性供体是什么？", "o": ["A. 磷酸化酶,ATP", "B. 糖原合酶,UDP-葡萄糖", "C. PFK,G-6-P", "D. PK,PEP"], "a": "B", "e": "糖原合成:①G→G-6-P→G-1-P+UTP→UDP-葡萄糖+PPi(焦磷酸酶→不可逆)。②UDP-G+糖原引物→糖原合酶→a-1,4键延伸。UDP-G是活性葡萄糖基供体。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_56", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "a-1,6糖苷键被什么酶水解？", "o": ["A. a-淀粉酶", "B. a-糊精酶(异麦芽糖酶)", "C. b-淀粉酶", "D. 蔗糖酶"], "a": "B", "e": "a-糊精酶专门水解a-1,6糖苷键(分支点)。糖原磷酸化酶切a-1,4键(90%)。", "kp": null}, {"id": "sugar1_mcq_57", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "F-1,6-2P裂解产物？", "o": ["A. 2GAP", "B. DHAP+GAP", "C. 2DHAP", "D. G+DHAP"], "a": "B", "e": "醛缩酶催化C3-C4裂解→一个酮糖(DHAP)+一个醛糖(GAP)。其后DHAP经异构酶→GAP→继续酵解。准备阶段结束!", "kp": "sugar1_s3_6"}, {"id": "sugar1_mcq_58", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "a-D-葡萄糖和b-D-葡萄糖的区别？", "o": ["A. 分子量不同", "B. 异头碳C1上-OH方向不同(a反式,b顺式)", "C. 碳数不同", "D. 醛基不同"], "a": "B", "e": "a:C1-OH与末端C5-CH2OH反式;b:顺式。变旋平衡:a约36%,b约64%。此题为常考区分异构体题!", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_59", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "蔗糖无还原性原因？", "o": ["A. 分子量太大", "B. 两个异头碳均参与糖苷键(Glc-a1和Fru-b2)", "C. 不含醛基", "D. 是二糖"], "a": "B", "e": "蔗糖Glc-a1+ Fruct-b2>两个异头碳的半缩醛羟基均参与糖苷键→无游离半缩醛→无还原性。常考判断题!", "kp": null}, {"id": "sugar1_mcq_60", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "己糖激酶受何反馈抑制？", "o": ["A. ATP", "B. G-6-P", "C. F-6-P", "D. 柠檬酸"], "a": "B", "e": "G-6-P是己糖激酶产物抑制剂。葡糖激酶(肝)不受G-6-P抑制→可持续摄G。", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_61", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "酵解中唯一氧化步？", "o": ["A. 3(PFK)", "B. 6(GAPDH)", "C. 7(PGK)", "D. 10(PK)"], "a": "B", "e": "GAPDH催化唯一涉及电子转移(NAD+→NADH)反应。其余9步无氧化还原改变。唯一氧化!", "kp": "sugar1_s3_2"}], "judge": [], "fill": [{"id": "sugar1_fill_2", "modI": 3, "q": "磷酸戊糖途径(PPP)的氧化阶段关键限速酶是________,该酶缺陷会导致________病。", "a": "G-6-P脱氢酶(G-6-PDH),蚕豆", "kp": "sugar1_s3_1"}, {"id": "sugar1_fill_12", "modI": 3, "q": "磷酸戊糖途径的部位在________,分为________阶段和________阶段,主要产物是________和________。", "a": "细胞质,氧化,非氧化,NADPH,5-P-核糖", "kp": "sugar1_s3_2"}], "short": [{"id": "sugar1_short_2", "modI": 3, "q": "比较糖酵解(EMP)、三羧酸循环(TCA)和磷酸戊糖途径(PPP)三条途径的部位、产物和生理意义。", "a": "①糖酵解(EMP):细胞质;G→2丙酮酸+2ATP+2NADH;无氧供能,所有组织均可进行。\u000b②三羧酸循环(TCA):线粒体基质;乙酰CoA→2CO2+3NADH+FADH2+GTP(10ATP);有氧供能的主要方式,产生还原力(NADH/FADH2)供呼吸链。\u000b③磷酸戊糖途径(PPP):细胞质;G-6-P→5-P-核酮糖+2NADPH+CO2;提供NADPH(合成代谢还原力)和5-P-核糖(核酸合成前体)。\u000b\u000b三者关系:EMP是葡萄糖氧化起始→丙酮酸→乙酰CoA→TCA彻底氧化。PPP是G-6-P的支路,提供NADPH和核糖而不能量产ATP。G-6-P是EMP/PPP/糖原合成的分水岭。", "kp": "sugar1_s3_8"}, {"id": "sugar1_short_8", "modI": 3, "q": "简述磷酸戊糖途径(PPP)的氧化阶段和非氧化阶段及其生理意义。", "a": "部位:细胞质\u000b\u000b【氧化阶段】(不可逆)\u000b①G-6-P+NADP+→6-P-葡萄糖酸内酯+NADPH(G-6-PDH,限速酶)\u000b②内酯+H2O→6-P-葡萄糖酸(内酯酶)\u000b③6-P-G+NADP+→5-P-核酮糖+CO2+NADPH(6-P-G脱氢酶)\u000b④5-P-核酮糖→5-P-核糖(异构酶)\u000b⑤5-P-核酮糖→5-P-木酮糖(差向酶)\u000b每G-6-P产2NADPH+1CO2\u000b\u000b【非氧化阶段】(可逆)\u000b转酮酶(TPP,移2C)+转醛酶(移3C)→6C5⇌5C6可逆转换\u000b• C5+C5→C3+C7(转酮酶)\u000b• C7+C3→C4+C6(转醛酶)\u000b• C5+C4→C3+C6(转酮酶)\u000b\u000b总反应:6G-6-P+12NADP++7H2O→6CO2+5G-6-P+12NADPH+Pi\u000b\u000b生理意义:\u000b①生成NADPH→脂肪酸/固醇合成+GSH再生\u000b②生成5-P-核糖→核酸合成前体\u000b③是细胞内各种单糖的重要来源", "kp": "sugar1_s3_2"}], "calc": [{"id": "sugar1_calc_5", "modI": 3, "q": "计算1分子葡萄糖-6-磷酸(G-6-P)完全进入PPP氧化阶段的ATP当量？(从NADPH的角度)", "a": "无直接ATP产生,但2分子NADPH约相当于5ATP当量", "steps": "PPP氧化阶段:\u000bG-6-P+2NADP++H2O→5-P-核酮糖+CO2+2NADPH\u000b\u000b无ATP直接产生(与EMP不同)\u000b但2NADPH是还原力:\u000b• 若用于脂肪酸合成:每个CH2-CO-→-CH2-CH2-需2NADPH\u000b• 若通过ATP生成:NADPH通过转氢酶→NADH→呼吸链约2.5ATP\u000b• 或经旁路:NADPH→GSSG→GSH(非产能)\u000b\u000b产能等价:2NADPH≈5ATP(苹果酸穿梭)或3ATP(甘油-3-P穿梭)\u000b但NADPH主要用于合成代谢而非产ATP→<5ATP实际可用\u000b\u000b与EMP比较:\u000bEMP:G→2ATP+2NADH(约5-7ATP等价)→总计约7-9ATP\u000bPPP氧化阶段:G-6-P→0ATP+2NADPH(约3-5ATP等价)\u000b→EMP产ATP多,PPP提供还原力(分工明确)", "kp": "sugar1_s3_2"}], "term": [{"id": "sugar1_term_13", "modI": 3, "term": "磷酸戊糖途径(PPP/HMP)", "def": "①G-6-P经氧化阶段脱氢脱羧和分子重排→产生NADPH和5-P-核糖的代谢支路（定义）。②部位:细胞质。G-6-PDH为关键限速酶→受NADPH反馈抑制（限速酶）。③氧化阶段:2步脱氢→产2NADPH+1CO2+5-P-核酮糖→异构/差向→5-P-核糖和5-P-木酮糖（氧化阶段）。④非氧化阶段:转酮酶(TPP,移2C)+转醛酶(移3C)→分子重排→总6C5⇌5C6可逆转换→再生G-6-P（非氧化阶段）。⑤三大生理意义:①NADPH(合成代谢还原力);②5-P-核糖(核酸合成前体);③各种单糖来源(适应不同组织需求)（意义）。", "kps": "①定义(1分)②G-6-PDH限速(1分)③氧化阶段(1分)④非氧化阶段(1分)⑤三大生理意义(1分)", "kp": "sugar1_s3_0"}, {"id": "sugar1_term_23", "modI": 3, "term": "G-6-PDH缺陷症(G6PD Deficiency)", "def": "①G-6-P脱氢酶(PPP氧化阶段限速酶)缺陷导致的X连锁遗传性溶血性贫血（定义+遗传）。②机制:G-6-PDH缺陷→PPP受阻→NADPH↓→GSSG→GSH转化受阻→GSH↓→H2O2积累↑→膜脂过氧化→膜蛋白交联→红细胞脆性↑→溶血（机制）。③诱因:食蚕豆(含嘧啶核苷)、服用氧化性药物(伯氨喹/喹啉/磺胺)→加重NADPH短缺→急性溶血危象（诱因）。④流行:全球约4亿人受影响→非洲/地中海/东南亚最普遍→与疟疾保护有关(镰状细胞/霍乱等与G6PDH缺陷的地理重叠)（流行病学）。⑤临床:新生儿黄疸、急性溶血性贫血、慢性非球形红细胞溶血性贫血→新生儿G6PDH筛查(采血测定)（临床）。", "kps": "①定义+遗传(1分)②分子机制(2分)③诱因(1分)④流行病学(1分)⑤临床意义(1分)", "kp": "sugar1_s3_1"}]}], "mcq": [{"id": "sugar1_mcq_1", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "手性碳原子的定义是什么？", "o": ["A. 连接4个相同基团的C", "B. 连接4个不同原子/基团的四面体C", "C. 不饱和C原子", "D. 连接羟基的C"], "a": "B", "e": "C*连接4个不同基团→失去对称性→具有2个光学异构体。n个C*有2^n个立体异构体。", "kp": "sugar1_s0_3"}, {"id": "sugar1_mcq_2", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "D型和L型单糖的判断依据是什么？", "o": ["A. 旋光性", "B. 距羰基最远的C*上-OH方向:右=D,左=L", "C. 碳链长度", "D. 醛基位置"], "a": "B", "e": "以距羰基最远的C*的OH方向定:OH在右=D型。自然界绝大多数单糖为D型。", "kp": "sugar1_s0_10"}, {"id": "sugar1_mcq_3", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "葡萄糖有多少种立体异构体？", "o": ["A. 8种,3个C*", "B. 16种,C2/C3/C4/C5 4个C*", "C. 32种,5个C*", "D. 4种,2个C*"], "a": "B", "e": "葡萄糖C2/C3/C4/C5共4个C*→2^4=16种立体异构体。L-Glc是对映体,其余14个为非对映体。", "kp": "sugar1_s0_4"}, {"id": "sugar1_mcq_4", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "D-葡萄糖和D-甘露糖是什么关系？", "o": ["A. 对映体", "B. C2差向异构体", "C. C4差向异构体", "D. 结构异构体"], "a": "B", "e": "D-甘露糖是D-Glc的C2差向异构体。D-半乳糖是C4差向异构体。仅一个C*构型不同即差向异构体。", "kp": "sugar1_s0_4"}, {"id": "sugar1_mcq_5", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "什么叫变旋现象？", "o": ["A. 单糖溶液比旋光度随时间变化至平衡", "B. 糖分子旋转", "C. 糖氧化还原", "D. 糖苷键断裂"], "a": "A", "e": "a和b异头物在溶液中通过开链互变→比旋光度随时间变化→最终达平衡(a:36%,b:64%)。", "kp": "sugar1_s0_9"}, {"id": "sugar1_mcq_6", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "Fehling试剂检测什么？", "o": ["A. 蛋白质", "B. 还原糖(游离醛基使Cu2+→Cu2O红色沉淀)", "C. 脂肪", "D. 核酸"], "a": "B", "e": "碱性铜试剂→还原糖的醛基将Cu2+→Cu+→Cu2O红色沉淀。用于尿糖检测。", "kp": "sugar1_s0_10"}, {"id": "sugar1_mcq_7", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "吡喃型vs呋喃型糖的区别？", "o": ["A. 吡喃=六元环,呋喃=五元环", "B. 都是六元环", "C. 都是五元环", "D. 吡喃=五元环,呋喃=六元环"], "a": "A", "e": "葡萄糖主成吡喃(C1-C5连接六元环);果糖可成呋喃(C2-C5连接五元环)。环化后产生新的C*—异头碳。", "kp": "sugar1_s0_1"}, {"id": "sugar1_mcq_8", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "椅式构象与船式构象的关系？", "o": ["A. 均为低能构象", "B. 椅式最稳定(平伏键多),船式能量较高", "C. 船式最稳定", "D. 完全相同"], "a": "B", "e": "六元环糖以椅式为主→大体积基团占平伏键→能量低。船式有空间排斥→极少量存在。", "kp": "sugar1_s0_11"}, {"id": "sugar1_mcq_9", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "直链淀粉和支链淀粉的区别？", "o": ["A. 直链a-1,4无分支;支链含a-1,6(每25-30单位一分支)", "B. 完全相同", "C. 直链含a-1,6,支链不含", "D. 都是蛋白质"], "a": "A", "e": "直链淀粉:a-1,4线性。支链淀粉:a-1,4+a-1,6分支。糖原:每8-12单位一分支→高度分支利于快速动员。", "kp": "sugar1_s0_15"}, {"id": "sugar1_mcq_10", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "半缩醛羟基参与糖苷键后有何变化？", "o": ["A. 仍有还原性", "B. 失去还原性,因半缩醛羟基已被取代", "C. 变为酮糖", "D. 变为多糖"], "a": "B", "e": "半缩醛羟基一旦参与糖苷键→不再有还原性。多糖只有一个还原端(末端的游离半缩醛羟基)。", "kp": "sugar1_s0_9"}, {"id": "sugar1_mcq_11", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖原磷酸化酶需要什么辅酶？", "o": ["A. TPP", "B. PLP(磷酸吡哆醛)", "C. NAD+", "D. FAD"], "a": "B", "e": "磷酸化酶含PLP,VB6衍生物。PLP稳定酶构象,不直接催化。VB6缺乏→糖原降解障碍。", "kp": "sugar1_s0_21"}, {"id": "sugar1_mcq_12", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "体内糖原主要储存在哪里？", "o": ["A. 脑", "B. 肝脏(~20%)和肌肉(~80%)", "C. 血液", "D. 脂肪组织"], "a": "B", "e": "肝糖元~20%维持血糖;肌糖元~80%供肌肉自身用。肌肉无葡糖-6-磷酸酶→不能直接释G到血。", "kp": "sugar1_s0_15"}, {"id": "sugar1_mcq_13", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "a-淀粉酶和a-糊精酶作用的区别？", "o": ["A. 均水解a-1,4键", "B. a-淀粉酶切a-1,4键,a-糊精酶切a-1,6键", "C. 均水解a-1,6键", "D. 均为蛋白酶"], "a": "B", "e": "a-淀粉酶→水解a-1,4糖苷键→糊精+麦芽糖。a-糊精酶→专门水解a-1,6分支键→游离Glc。", "kp": "sugar1_s0_18"}, {"id": "sugar1_mcq_14", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖酵解三个不可逆酶？", "o": ["A. 己糖激酶/醛缩酶/PK", "B. 己糖激酶/PFK-1/丙酮酸激酶", "C. PFK-1/GAPDH/PK", "D. 己糖激酶/PGK/PK"], "a": "B", "e": "三大不可逆=三大调控点:①己糖激酶③PFK⑩PK。PGK和GAPDH是可逆的!", "kp": "sugar1_s0_20"}, {"id": "sugar1_mcq_15", "mod": "模块一：糖的分类与消化", "modI": 0, "q": "糖酵解净产？", "o": ["A. 4ATP+2NADH", "B. 2ATP+2NADH", "C. 2ATP+4NADH", "D. 4ATP"], "a": "B", "e": "耗2ATP,产4ATP=净+2ATP+2NADH。", "kp": "sugar1_s0_0"}, {"id": "sugar1_mcq_16", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "PFK-1最强激活剂？", "o": ["A. ATP", "B. 柠檬酸", "C. 2,6-二磷酸果糖", "D. NADH"], "a": "C", "e": "F-2,6-BP是PFK-1最强别构激活剂。ATP/柠檬酸抑制PFK-1。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_17", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "GAPDH产物？", "o": ["A. GAP→3-PG", "B. GAP+Pi+NAD+→1,3-BPG+NADH", "C. 1,3-BPG→GAP", "D. GAP+FAD→产物"], "a": "B", "e": "GAPDH催化唯一氧化步。活性Cys形成硫酯。砷酸替代Pi→解偶联不产ATP。", "kp": "sugar1_s1_12"}, {"id": "sugar1_mcq_18", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "氟化物抑制哪个酶？", "o": ["A. 己糖激酶", "B. 烯醇化酶", "C. PFK-1", "D. PK"], "a": "B", "e": "F-+Mg2++Pi→复合物→取代烯醇化酶Mg2+→2-PG积累。血糖管(灰头管)利用此原理。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_19", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "底物磷酸化哪两步？", "o": ["A. 1和3", "B. 7(PGK)和10(PK)", "C. 6和7", "D. 4和10"], "a": "B", "e": "PGK:1,3-BPG→3-PG+ATP;PK:PEP→丙酮酸+ATP。各x2=总4ATP。", "kp": "sugar1_s1_13"}, {"id": "sugar1_mcq_20", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "己糖激酶与底物结合后构象变化说明什么？", "o": ["A. 锁钥模型", "B. 诱导契合(酶的构象柔性)", "C. 抑制剂作用", "D. 共价催化"], "a": "B", "e": "己糖激酶与D-Glc结合→构象显著变化→活性位点包围底物→排开水分子→利于磷酸转移。诱导契合经典范例!", "kp": "sugar1_s1_6"}, {"id": "sugar1_mcq_21", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "砷酸(AsO43-)如何影响酵解？", "o": ["A. 促进ATP生成", "B. 替代Pi,形成1-砷酸-3-PG→快速自发水解→不产ATP(解偶联)", "C. 抑制PFK", "D. 无影响"], "a": "B", "e": "砷酸与Pi类似→GAPDH用砷酸→1-砷酸-3-PG高度不稳定→不经过PGK→不产ATP→净产0ATP。砷毒性分子基础!", "kp": "sugar1_s1_17"}, {"id": "sugar1_mcq_22", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "2,3-BPG的生理功能是什么？", "o": ["A. 仅作为酵解中间物", "B. 降低Hb对O2亲和力,有利于组织供氧", "C. 抑制糖酵解", "D. 激活PFK"], "a": "B", "e": "2,3-BPG与Hb b亚基结合→稳定T态→O2解离曲线右移→组织水平O2释放↑。高山适应/贫血→RBC中2,3-BPG↑。", "kp": "sugar1_s1_13"}, {"id": "sugar1_mcq_23", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "丙酮酸在无氧条件下的去路？", "o": ["A. ①TCA②乳酸发酵③丙氨酸", "B. ①乳酸(LDH)②乙醇(PDC+ADH)③TCA", "C. ①TCA②PPP③生醇发酵", "D. ①糖异生②PPP③TCA"], "a": "B", "e": "有氧→乙酰CoA→TCA;无氧-肌肉→乳酸(LDH,NAD+再生);无氧-酵母→乙醇NAD+再生。后两种保证NAD+再生维持酵解。", "kp": "sugar1_s1_20"}, {"id": "sugar1_mcq_24", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "生醇发酵中TPP的作用？", "o": ["A. 丙酮酸脱羧酶辅酶,脱羧生成乙醛+CO2", "B. 激活ADH", "C. 乙醇的辅酶", "D. 无作用"], "a": "A", "e": "PDC依赖TPP→丙酮酸→乙醛+CO2。然后ADH→乙醇+NAD+。两步均在细胞质,再生的NAD+保障酵解持续。", "kp": "sugar1_s1_22"}, {"id": "sugar1_mcq_25", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "酵解中三步不可逆反应的ΔG？", "o": ["A. 1,3,10", "B. 1,7,10", "C. 3,7,10", "D. 1,3,7"], "a": "A", "e": "第1步:-33.5kJ/mol;第3步:-22.2;第10步:-16.7。ΔG远负→不可逆→调控点。其余7步≈0→可逆。", "kp": "sugar1_s1_17"}, {"id": "sugar1_mcq_26", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "激烈运动时酵解为什么重要？", "o": ["A. 有氧供能足够", "B. 肌肉缺氧,酵解可在无氧下快速供能(2ATP/G)", "C. 酵解产ATP比有氧多", "D. 酵解不需酶"], "a": "B", "e": "剧烈运动→局部缺氧→TCA受阻→依赖酵解速供ATP。乳酸堆积→酸中毒→肌肉酸痛。生理意义三大点之一。", "kp": "sugar1_s1_23"}, {"id": "sugar1_mcq_27", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "F-2,6-BP如何调控PFK-1？", "o": ["A. 竞争性抑制", "B. 在别构位点结合,解除ATP/柠檬酸抑制", "C. 促进PFK-1降解", "D. 作为底物参与反应"], "a": "B", "e": "F-2,6-BP是PFK-1最强别构激活剂→结合别构位点→增强F-6-P亲和力→克服ATP/柠檬酸抑制。受胰岛素/胰高血糖素调控。", "kp": "sugar1_s1_8"}, {"id": "sugar1_mcq_28", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "Cori循环(乳酸循环)的完整流程？", "o": ["A. 肝乳酸→G→肌肉", "B. 肌肉酵解→乳酸→血液→肝糖异生→G→血液→肌肉", "C. G→乳酸不可逆", "D. 肝→乳酸→肌肉→G"], "a": "B", "e": "Cori循环=废物回收+解毒+供能。肌肉酵解→乳酸→肝糖异生→G→肌肉。净亏4ATP,但为紧急供能!", "kp": "sugar1_s1_24"}, {"id": "sugar1_mcq_29", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "TCA不可逆酶？", "o": ["A. 柠檬酸合酶/异柠檬酸脱氢酶/a-KG脱氢酶", "B. 苹果酸脱氢酶", "C. 琥珀酸脱氢酶", "D. 延胡索酸酶"], "a": "A", "e": "TCA三个调控点:①柠檬酸合酶③异柠檬酸脱氢酶④a-KG脱氢酶。SDH=呼吸链复合物II。", "kp": "sugar1_s1_3"}, {"id": "sugar1_mcq_30", "mod": "模块二：糖酵解(EMP途径)", "modI": 1, "q": "一轮TCA产ATP？", "o": ["A. 12", "B. 10(3NADH+1FADH2+1GTP)", "C. 15", "D. 8"], "a": "B", "e": "3NADH(x2.5=7.5)+1FADH2(x1.5=1.5)+1GTP=10ATP。", "kp": "sugar1_s1_20"}, {"id": "sugar1_mcq_31", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PDH辅因子不包括？", "o": ["A. TPP", "B. NAD+", "C. CoA", "D. PLP"], "a": "D", "e": "PDH:TPP/FAD/NAD+/硫辛酸/CoA。PLP是转氨酶辅酶。两者的5种辅酶=3种酶的辅基或底物。", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_32", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "TCA中唯一膜结合酶？", "o": ["A. 柠檬酸合酶", "B. 琥珀酸脱氢酶(复合物II)", "C. 苹果酸脱氢酶", "D. 延胡索酸酶"], "a": "B", "e": "琥珀酸脱氢酶嵌入线粒体内膜→同时是呼吸链复合物II。其余7种酶均在基质。", "kp": "sugar1_s2_7"}, {"id": "sugar1_mcq_33", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乌头酸酶的作用特点？", "o": ["A. 对称催化两个臂", "B. 不对称催化,仅作用一个-CH2COOH臂", "C. 不需辅酶", "D. 作用于C=O"], "a": "B", "e": "柠檬酸是对称分子,但乌头酸酶只催化其中一个-CH2COOH臂→产生(2R,3S)-异柠檬酸。立体特异性经典!", "kp": "sugar1_s2_16"}, {"id": "sugar1_mcq_34", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "柠檬酸合酶催化反应机制？", "o": ["A. 直接缩合", "B. 乙酰CoA甲基脱H+→碳负离子亲核攻击OAA羰基→柠檬酰CoA→水解→柠檬酸+CoA", "C. 自由基反应", "D. FAD介导"], "a": "B", "e": "OAA+乙酰CoA+H2O→柠檬酸+CoA。这是TCA首步不可逆调控点。", "kp": "sugar1_s2_7"}, {"id": "sugar1_mcq_35", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "延胡索酸酶催化有什么特点？", "o": ["A. 加水,反式立体特异加成→L-苹果酸", "B. 脱氢", "C. 脱羧", "D. 转氨"], "a": "A", "e": "延胡索酸+H2O→L-苹果酸。立体特异反式加成:水从特定面攻击→仅产L-Malate。酶的立体特异性经典例子!", "kp": "sugar1_s2_13"}, {"id": "sugar1_mcq_36", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "TCA中唯一底物水平磷酸化发生在哪一步？", "o": ["A. 柠檬酸合酶", "B. 琥珀酰CoA合成酶(第5步)", "C. 苹果酸脱氢酶", "D. a-KG脱氢酶"], "a": "B", "e": "琥珀酰CoA+H2O+GDP→琥珀酸+GTP(动物产GTP,植物产ATP)。△G0'≈0→可逆。", "kp": "sugar1_s2_11"}, {"id": "sugar1_mcq_37", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乙醛酸循环存在于哪些生物？", "o": ["A. 所有生物", "B. 植物乙醛酸小体和微生物,动物体无", "C. 只有动物", "D. 只有人类"], "a": "B", "e": "乙醛酸循环是TCA支路→存在于植物/微生物→动物(含人)无。因此动物不能脂→糖!", "kp": "sugar1_s2_24"}, {"id": "sugar1_mcq_38", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "乙醛酸循环的关键酶是什么？", "o": ["A. 柠檬酸合酶和MDH", "B. 异柠檬酸裂解酶+苹果酸合酶", "C. SDH和延胡索酸酶", "D. PDH和柠檬酸合酶"], "a": "B", "e": "异柠檬酸裂解酶→乙醛酸+琥珀酸(绕过两个脱羧)。苹果酸合酶→乙醛酸+乙酰CoA→苹果酸+CoA。", "kp": "sugar1_s2_24"}, {"id": "sugar1_mcq_39", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "为什么一分子葡萄糖在不同组织产ATP数不同？", "o": ["A. 酵解效率不同", "B. NADH穿梭方式不同(苹果酸P/O=2.5→32ATP;甘油-3-P P/O=1.5→30ATP)", "C. TCA不同", "D. 呼吸链不同"], "a": "B", "e": "肝/肾/心肌→苹果酸穿梭→P/O高→32ATP。肌肉/神经→甘油-3-P穿梭→P/O低→30ATP。穿梭方式决定ATP产量差异。", "kp": "sugar1_s2_18"}, {"id": "sugar1_mcq_40", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PDH酶系如何被调控？", "o": ["A. 变构调节", "B. 磷酸化/去磷酸化(Pyruvate脱氢酶激酶磷酸化E1=失活;磷酸酶去磷酸化=激活)", "C. 转录调控", "D. 不受调控"], "a": "B", "e": "PDH激酶磷酸化E1a→失活(ATP↑激活)。PDH磷酸酶去磷酸化→激活(Ca2+/胰岛素激活)。能量状态精细调控!", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_41", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "葡萄糖总ATP(苹果酸穿梭)？", "o": ["A. 30", "B. 32", "C. 36", "D. 38"], "a": "B", "e": "酵解(2ATP+5)+PDH(5)+TCAx2(20)=32。甘油-3-P穿梭=30。", "kp": "sugar1_s2_18"}, {"id": "sugar1_mcq_42", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "苹果酸穿梭vs甘油-3-P穿梭的区别？", "o": ["A. 完全相同", "B. 苹果酸P/O=2.5(NADH→复合物I),甘油-3-P P/O=1.5(FADH2→CoQ)", "C. 只在胞质", "D. 甘油-3-P效率更高"], "a": "B", "e": "苹果酸穿梭→NADH→复合物I→P/O=2.5;甘油-3-P穿梭→FADH2→CoQ→P/O=1.5。肝心肌用前者,肌神经用后者。", "kp": "sugar1_s2_21"}, {"id": "sugar1_mcq_43", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PPP最重要产物？", "o": ["A. ATP", "B. NADPH和5-P-核糖", "C. FADH2", "D. 乙酰CoA"], "a": "B", "e": "NADPH→脂肪酸/固醇合成+GSH再生;5-P-核糖→核酸合成前体。", "kp": "sugar1_s2_2"}, {"id": "sugar1_mcq_44", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "PPP氧化阶段的限速酶是什么？", "o": ["A. 6-P-葡萄糖酸脱氢酶", "B. G-6-P脱氢酶", "C. 转酮酶", "D. 转醛酶"], "a": "B", "e": "G-6-PDH是关键限速酶→受NADPH反馈抑制。G6PDH缺陷→NADPH↓→GSH↓→红细胞膜氧化→蚕豆病/溶血性贫血。", "kp": "sugar1_s2_1"}, {"id": "sugar1_mcq_45", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "转酮酶和转醛酶的区别？", "o": ["A. 完全相同", "B. 转酮酶转移2C单位(需TPP),转醛酶转移3C单位", "C. 转酮酶转移3C,转醛酶转移2C", "D. 都不需辅酶"], "a": "B", "e": "转酮酶(TPP)→转移2C;C5+C5→C3+C7。转醛酶(无辅酶)→转移3C二羟丙酮片段;C7+C3→C6+C4。", "kp": "sugar1_s2_16"}, {"id": "sugar1_mcq_46", "mod": "模块三：TCA与有氧分解", "modI": 2, "q": "蚕豆病(G-6-PDH缺陷)的分子机制？", "o": ["A. 胰岛素分泌不足", "B. G-6-PDH缺陷→NADPH↓→GSH↓→H2O2积累→红细胞膜氧化→溶血", "C. 肝损伤", "D. Hb变异"], "a": "B", "e": "G6PDH缺陷→PPP受阻→NADPH减少→GSH不能再生→H2O2/自由基↑→膜脂过氧化→红细胞脆性↑→溶血。蚕豆含强氧化物质→恶化。急性溶血性贫血!", "kp": "sugar1_s2_4"}, {"id": "sugar1_mcq_47", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "PPP每分子G-6-P完全氧化产生几个NADPH？", "o": ["A. 1", "B. 2(氧化阶段)", "C. 3", "D. 4"], "a": "B", "e": "氧化阶段:①G-6-PDH→NADPH;②6-P-G脱氢酶→NADPH。共2NADPH+1CO2/每G-6-P。", "kp": "sugar1_s3_0"}, {"id": "sugar1_mcq_48", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "PPP非氧化阶段的生理意义？", "o": ["A. 仅生成ATP", "B. 产生5-P-核糖(核酸合成)和G-6-P再生", "C. 生成脂肪酸", "D. 仅脱氢"], "a": "B", "e": "非氧化:6C5⇌5C6可逆转换→为核酸合成提供5-P-核糖→为氧化阶段再生G-6-P。再生组织PPP活跃!", "kp": "sugar1_s3_3"}, {"id": "sugar1_mcq_49", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "NADPH和NADH的区别？", "o": ["A. 完全相同", "B. NADPH用于合成代谢(脂肪酸/固醇),NADH用于氧化供能(呼吸链)", "C. NADPH只在PPP产生", "D. NADPH不含磷酸"], "a": "B", "e": "NADPH→合成代谢的还原力;NADH→氧化磷酸化的电子供体。两者生化功能根本不同!", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_50", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "葡萄糖完全氧化总反应式？", "o": ["A. G+6O2→6CO2+6H2O+能量(~32ATP)", "B. G→2乳酸", "C. G→2丙酮酸+2ATP", "D. 2G→CO2+ATP"], "a": "A", "e": "C6H12O6+6O2→6CO2+6H2O+~32ATP。CO2:PDH(2)+TCA(4)=6CO2。O2是最终电子受体→还原为H2O。", "kp": "sugar1_s3_0"}, {"id": "sugar1_mcq_51", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖/脂/蛋白质/核酸四大物质代谢枢纽是什么？", "o": ["A. 酵解", "B. TCA循环", "C. PPP", "D. 尿素循环"], "a": "B", "e": "TCA是四大物质代谢网络中枢。糖→乙酰CoA/丙酮酸→TCA;脂肪→b-氧化→乙酰CoA→TCA;蛋白质→氨基酸→各TCA中间物;核酸→降解→C骨架可入TCA。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_52", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "为何动物不能将脂肪酸→糖,而植物可以？", "o": ["A. 动物缺乏乙醛酸循环关键酶", "B. 动物脂肪酸不能b-氧化", "C. 植物有叶绿体", "D. 动物TCA效率更高"], "a": "A", "e": "动物无乙醛酸循环→乙酰CoA两个C以CO2排出→C骨架净增=0→无法净合成C4→不能糖异生。植物有乙醛酸循环→绕过脱羧步→脂→糖。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_53", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "G-6-P是糖代谢关键分支点,它的三条主要去路？", "o": ["A. ①酵解②PPP③糖原合成", "B. ①TCA②尿素循环③PPP", "C. ①酵解②生醇发酵③PPP", "D. ①PDH②TCA③尿素循环"], "a": "A", "e": "G-6-P分水岭:①磷酸化→酵解(EMP)→产能;②脱氢→PPP→NADPH+核糖;③可逆→合成糖原(储存)。三条去路取决于细胞需求。", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_54", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖异生绕过酵解哪三个不可逆步？", "o": ["A. 1/2/3", "B. 1/3/10→分别用G-6-Pase/FBPase-1/丙酮酸羧化酶+PEPCK绕过", "C. 7/8/10", "D. 1/7/10"], "a": "B", "e": "酵解3个不可逆步必须绕过:①G-6-P→G(G-6-Pase);③F-1,6-BP→F-6-P(FBPase-1);⑩PEP→Pyruvate(Pyruvate carboxylase+PEPCK)。需6ATP。", "kp": "sugar1_s3_5"}, {"id": "sugar1_mcq_55", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "糖原合成的关键酶和活性供体是什么？", "o": ["A. 磷酸化酶,ATP", "B. 糖原合酶,UDP-葡萄糖", "C. PFK,G-6-P", "D. PK,PEP"], "a": "B", "e": "糖原合成:①G→G-6-P→G-1-P+UTP→UDP-葡萄糖+PPi(焦磷酸酶→不可逆)。②UDP-G+糖原引物→糖原合酶→a-1,4键延伸。UDP-G是活性葡萄糖基供体。", "kp": "sugar1_s3_8"}, {"id": "sugar1_mcq_56", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "a-1,6糖苷键被什么酶水解？", "o": ["A. a-淀粉酶", "B. a-糊精酶(异麦芽糖酶)", "C. b-淀粉酶", "D. 蔗糖酶"], "a": "B", "e": "a-糊精酶专门水解a-1,6糖苷键(分支点)。糖原磷酸化酶切a-1,4键(90%)。", "kp": null}, {"id": "sugar1_mcq_57", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "F-1,6-2P裂解产物？", "o": ["A. 2GAP", "B. DHAP+GAP", "C. 2DHAP", "D. G+DHAP"], "a": "B", "e": "醛缩酶催化C3-C4裂解→一个酮糖(DHAP)+一个醛糖(GAP)。其后DHAP经异构酶→GAP→继续酵解。准备阶段结束!", "kp": "sugar1_s3_6"}, {"id": "sugar1_mcq_58", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "a-D-葡萄糖和b-D-葡萄糖的区别？", "o": ["A. 分子量不同", "B. 异头碳C1上-OH方向不同(a反式,b顺式)", "C. 碳数不同", "D. 醛基不同"], "a": "B", "e": "a:C1-OH与末端C5-CH2OH反式;b:顺式。变旋平衡:a约36%,b约64%。此题为常考区分异构体题!", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_59", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "蔗糖无还原性原因？", "o": ["A. 分子量太大", "B. 两个异头碳均参与糖苷键(Glc-a1和Fru-b2)", "C. 不含醛基", "D. 是二糖"], "a": "B", "e": "蔗糖Glc-a1+ Fruct-b2>两个异头碳的半缩醛羟基均参与糖苷键→无游离半缩醛→无还原性。常考判断题!", "kp": null}, {"id": "sugar1_mcq_60", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "己糖激酶受何反馈抑制？", "o": ["A. ATP", "B. G-6-P", "C. F-6-P", "D. 柠檬酸"], "a": "B", "e": "G-6-P是己糖激酶产物抑制剂。葡糖激酶(肝)不受G-6-P抑制→可持续摄G。", "kp": "sugar1_s3_1"}, {"id": "sugar1_mcq_61", "mod": "模块四：磷酸戊糖途径", "modI": 3, "q": "酵解中唯一氧化步？", "o": ["A. 3(PFK)", "B. 6(GAPDH)", "C. 7(PGK)", "D. 10(PK)"], "a": "B", "e": "GAPDH催化唯一涉及电子转移(NAD+→NADH)反应。其余9步无氧化还原改变。唯一氧化!", "kp": "sugar1_s3_2"}], "judge": [], "fill": [{"id": "sugar1_fill_1", "modI": 1, "q": "糖酵解中三步不可逆反应分别由________、________和________催化。", "a": "己糖激酶,磷酸果糖激酶(PFK-1),丙酮酸激酶(PK)", "kp": "sugar1_s1_17"}, {"id": "sugar1_fill_2", "modI": 3, "q": "磷酸戊糖途径(PPP)的氧化阶段关键限速酶是________,该酶缺陷会导致________病。", "a": "G-6-P脱氢酶(G-6-PDH),蚕豆", "kp": "sugar1_s3_1"}, {"id": "sugar1_fill_3", "modI": 2, "q": "三羧酸循环中唯一的膜结合酶是________,它同时是呼吸链的________。", "a": "琥珀酸脱氢酶,复合物II", "kp": "sugar1_s2_24"}, {"id": "sugar1_fill_4", "modI": 2, "q": "乙醛酸循环的两个关键酶是________和________,此循环在________和________中存在,动物体________。", "a": "异柠檬酸裂解酶,苹果酸合酶,植物,微生物,不存在", "kp": "sugar1_s2_24"}, {"id": "sugar1_fill_5", "modI": 0, "q": "糖原磷酸化酶降解糖原切________键,产物是________,需要辅酶________。", "a": "a-1,4糖苷,G-1-P,PLP(磷酸吡哆醛)", "kp": "sugar1_s0_21"}, {"id": "sugar1_fill_6", "modI": 2, "q": "1分子葡萄糖经有氧彻底氧化净产________个ATP(苹果酸穿梭系统)或________个ATP(甘油-3-磷酸穿梭系统)。", "a": "32,30", "kp": "sugar1_s2_21"}, {"id": "sugar1_fill_7", "modI": 2, "q": "丙酮酸脱氢酶系包含3个酶(E1________、E2________、E3________)和5种辅酶(________、________、________、________、________)。", "a": "丙酮酸脱氢酶,二氢硫辛酰转乙酰基酶,二氢硫辛酰脱氢酶,TPP,FAD,NAD+,硫辛酸,CoA", "kp": "sugar1_s2_3"}, {"id": "sugar1_fill_8", "modI": 0, "q": "蔗糖由________和________通过________糖苷键连接,因________均参与糖苷键而________还原性。", "a": "葡萄糖,果糖,a1/b2,两个异头碳,无", "kp": "sugar1_s0_13"}, {"id": "sugar1_fill_9", "modI": 1, "q": "Cori循环(乳酸循环)中,肌肉酵解产生________经血液运至________,通过________途径生成葡萄糖再回到肌肉。", "a": "乳酸,肝脏,糖异生", "kp": "sugar1_s1_24"}, {"id": "sugar1_fill_10", "modI": 2, "q": "TCA循环每轮产生________分子NADH、________分子FADH2和________分子GTP,共约________个ATP。", "a": "3,1,1,10", "kp": "sugar1_s2_17"}, {"id": "sugar1_fill_11", "modI": 1, "q": "糖酵解的底物水平磷酸化发生在第________步(________催化)和第________步(________催化)。", "a": "7,磷酸甘油酸激酶(PGK),10,丙酮酸激酶(PK)", "kp": "sugar1_s1_18"}, {"id": "sugar1_fill_12", "modI": 3, "q": "磷酸戊糖途径的部位在________,分为________阶段和________阶段,主要产物是________和________。", "a": "细胞质,氧化,非氧化,NADPH,5-P-核糖", "kp": "sugar1_s3_2"}], "short": [{"id": "sugar1_short_1", "modI": 1, "q": "简述糖酵解(EMP途径)的10步反应,标明三步不可逆反应及其催化酶。", "a": "糖酵解在细胞质进行,分两阶段:准备阶段(前5步)和贮能阶段(后5步)。\u000b\u000b【准备阶段】(耗2ATP):\u000b①G+ATP→G-6-P+ADP(己糖激酶,不可逆!)\u000b②G-6-P→F-6-P(异构酶)\u000b③F-6-P+ATP→F-1,6-2P+ADP(PFK-1,不可逆!最重要调控点)\u000b④F-1,6-2P→DHAP+GAP(醛缩酶)\u000b⑤DHAP↔GAP(异构酶)\u000b\u000b【贮能阶段】(产4ATP+2NADH):\u000b⑥GAP+NAD++Pi→1,3-BPG+NADH(GAPDH,唯一氧化步)\u000b⑦1,3-BPG+ADP→3-PG+ATP(PGK,底物磷酸化)\u000b⑧3-PG→2-PG(变位酶)\u000b⑨2-PG→PEP+H2O(烯醇化酶,F-抑制)\u000b⑩PEP+ADP→丙酮酸+ATP(PK,不可逆!底物磷酸化)\u000b\u000b总反应:G+2NAD++2ADP+2Pi→2丙酮酸+2NADH+2ATP+2H2O\u000b净产:2ATP+2NADH。三步不可逆①②⑩=三个调控点。", "kp": "sugar1_s1_2"}, {"id": "sugar1_short_2", "modI": 3, "q": "比较糖酵解(EMP)、三羧酸循环(TCA)和磷酸戊糖途径(PPP)三条途径的部位、产物和生理意义。", "a": "①糖酵解(EMP):细胞质;G→2丙酮酸+2ATP+2NADH;无氧供能,所有组织均可进行。\u000b②三羧酸循环(TCA):线粒体基质;乙酰CoA→2CO2+3NADH+FADH2+GTP(10ATP);有氧供能的主要方式,产生还原力(NADH/FADH2)供呼吸链。\u000b③磷酸戊糖途径(PPP):细胞质;G-6-P→5-P-核酮糖+2NADPH+CO2;提供NADPH(合成代谢还原力)和5-P-核糖(核酸合成前体)。\u000b\u000b三者关系:EMP是葡萄糖氧化起始→丙酮酸→乙酰CoA→TCA彻底氧化。PPP是G-6-P的支路,提供NADPH和核糖而不能量产ATP。G-6-P是EMP/PPP/糖原合成的分水岭。", "kp": "sugar1_s3_8"}, {"id": "sugar1_short_3", "modI": 2, "q": "简述三羧酸循环(TCA)的8步反应、产能和生理意义。", "a": "部位:线粒体基质。8步反应:\u000b①乙酰CoA+OAA→柠檬酸(柠檬酸合酶,不可逆!)\u000b②柠檬酸→顺乌头酸→异柠檬酸(乌头酸酶)\u000b③异柠檬酸→a-KG+CO2+NADH(异柠檬酸脱氢酶,不可逆!)\u000b④a-KG→琥珀酰CoA+CO2+NADH(a-KG脱氢酶系,不可逆!)\u000b⑤琥珀酰CoA→琥珀酸+GTP(合成酶,底物磷酸化)\u000b⑥琥珀酸→延胡索酸+FADH2(SDH,膜结合,复合物II)\u000b⑦延胡索酸→苹果酸(延胡索酸酶)\u000b⑧苹果酸→OAA+NADH(MDH)\u000b\u000b产能:3NADH(x2.5=7.5)+1FADH2(x1.5=1.5)+1GTP=10ATP/轮\u000b\u000b生理意义:①获得能量最有效方式;②是糖/脂/蛋白质/核酸四大物质代谢网络中枢;③中间产物为其他物质合成提供C骨架前体。", "kp": "sugar1_s2_22"}, {"id": "sugar1_short_4", "modI": 2, "q": "简述丙酮酸在细胞内的三条代谢去路,分别说明反应条件和生理意义。", "a": "丙酮酸为酵解终产物,三条去路:\u000b\u000b①有氧→乙酰CoA→TCA:丙酮酸脱氢酶系(PDH)催化,在线粒体基质进行,需TPP/硫辛酸/FAD/NAD+/CoA五种辅酶。产生NADH不可逆,连接酵解和TCA的关键反应。正常有氧条件下的主要去路。\u000b\u000b②无氧→乳酸(乳酸发酵):乳酸脱氢酶(LDH)催化,在肌肉/红细胞/乳酸菌中进行。NADH再氧化为NAD+保证酵解持续进行。运动时肌肉主要供能方式)。\u000b\u000b③无氧→乙醇(生醇发酵):丙酮酸脱羧酶(TPP)+乙醇脱氢酶(ADH)催化,在酵母中进行。NADH再氧化为NAD+,产CO2。酿酒/做面包的原理。\u000b\u000b②③的关键意义:在无氧条件下再生NAD+→保证酵解持续运行→维持ATP供应。", "kp": "sugar1_s2_22"}, {"id": "sugar1_short_5", "modI": 2, "q": "简述丙酮酸脱氢酶系(PDH)的组成、辅因子和调控机制。", "a": "部位:线粒体基质\u000b\u000b组成:3个酶\u000b• E1=丙酮酸脱氢酶(24亚基):TPP依赖\u000b• E2=二氢硫辛酰转乙酰基酶(24亚基):硫辛酸辅基\u000b• E3=二氢硫辛酰脱氢酶(12亚基):FAD依赖\u000b\u000b5种辅因子:TPP(E1)、CoA(E2底物)、硫辛酸(E2辅基)、NAD+(E3产物)、FAD(E3辅基)\u000b\u000b反应:丙酮酸+CoA+NAD+→乙酰CoA+CO2+NADH(不可逆)\u000b\u000b调控-磷酸化/去磷酸化:PDH激酶磷酸化E1→失活(ATP/NADH/Ac-CoA↑激活激酶);PDH磷酸酶去磷酸化→激活(Ca2+/胰岛素激活)。\u000b\u000b硫辛酸与E2 Lys共价相连→柔韧臂(约14A)→在E1/E2/E3间摆臂传递酰基。", "kp": "sugar1_s2_3"}, {"id": "sugar1_short_6", "modI": 0, "q": "简述糖原降解的酶和机制。", "a": "糖原降解需要三种酶:\u000b\u000b①磷酸化酶(处理90%):切a-1,4糖苷键→加Pi→G-1-P(需PLP辅酶)。从非还原端逐个切除葡萄糖残基,直到距a-1,6分支点4个残基处停止。\u000b\u000b②糖基转移酶:将暴露的分支顶端3个葡萄糖残基转移到另一条链的非还原端→只剩1个连接在分支点的Glc(a-1,6)。\u000b\u000b③脱支酶(处理10%):水解a-1,6糖苷键→释放游离葡萄糖(不是G-1-P)。\u000b\u000b产物:G-1-P(90%)和游离G(10%)。\u000b\u000bG-1-P→磷酸葡萄糖变位酶→G-6-P→进入酵解供能。\u000b\u000b调节:磷酸化酶受肾上腺素/胰高血糖素(通过cAMP/PKA)磷酸化激活→糖原分解→维持血糖。", "kp": "sugar1_s0_20"}, {"id": "sugar1_short_7", "modI": 1, "q": "简述NADH穿梭的两种方式及ATP产量的差异。", "a": "胞质中产生的NADH不能直接进入线粒体,需穿梭系统:\u000b\u000b①苹果酸-天冬氨酸穿梭(肝/肾/心肌):\u000b胞质NADH→苹果酸→进入线粒体→MDH→OAA+NADH(m)→NADH→复合物I→P/O≈2.5\u000b→2胞质NADH→2线粒体NADH→5ATP\u000b\u000b②甘油-3-磷酸穿梭(肌肉/神经):\u000b胞质NADH→DHAP→甘油-3-磷酸(G3PDH)→进入膜间隙→线粒体G3PDH(膜结合)→FADH2→CoQ→绕过复合物I→P/O≈1.5\u000b→2胞质NADH→2FADH2→3ATP\u000b\u000b差异原因:苹果酸穿梭将NADH直接交给复合物I(高P/O);甘油-3-P穿梭转换为FADH2直接进入CoQ(低P/O)。\u000b\u000b1分子G总ATP:肝/心肌32ATP(苹果酸穿梭);骨骼肌/神经30ATP(甘油-3-P穿梭)。", "kp": "sugar1_s1_12"}, {"id": "sugar1_short_8", "modI": 3, "q": "简述磷酸戊糖途径(PPP)的氧化阶段和非氧化阶段及其生理意义。", "a": "部位:细胞质\u000b\u000b【氧化阶段】(不可逆)\u000b①G-6-P+NADP+→6-P-葡萄糖酸内酯+NADPH(G-6-PDH,限速酶)\u000b②内酯+H2O→6-P-葡萄糖酸(内酯酶)\u000b③6-P-G+NADP+→5-P-核酮糖+CO2+NADPH(6-P-G脱氢酶)\u000b④5-P-核酮糖→5-P-核糖(异构酶)\u000b⑤5-P-核酮糖→5-P-木酮糖(差向酶)\u000b每G-6-P产2NADPH+1CO2\u000b\u000b【非氧化阶段】(可逆)\u000b转酮酶(TPP,移2C)+转醛酶(移3C)→6C5⇌5C6可逆转换\u000b• C5+C5→C3+C7(转酮酶)\u000b• C7+C3→C4+C6(转醛酶)\u000b• C5+C4→C3+C6(转酮酶)\u000b\u000b总反应:6G-6-P+12NADP++7H2O→6CO2+5G-6-P+12NADPH+Pi\u000b\u000b生理意义:\u000b①生成NADPH→脂肪酸/固醇合成+GSH再生\u000b②生成5-P-核糖→核酸合成前体\u000b③是细胞内各种单糖的重要来源", "kp": "sugar1_s3_2"}, {"id": "sugar1_short_9", "modI": 2, "q": "简述乙醛酸循环的过程、关键酶和生理意义。", "a": "乙醛酸循环是TCA的支路,存在于植物乙醛酸小体和微生物,动物体不存在。\u000b\u000b过程(绕过两个脱羧步):\u000b①异柠檬酸(6C)→异柠檬酸裂解酶→乙醛酸(2C)+琥珀酸(4C)\u000b②乙醛酸(2C)+乙酰CoA(2C)→苹果酸合酶→苹果酸(4C)+CoA\u000b③苹果酸→草酰乙酸(常规TCA酶)\u000b④草酰乙酸+乙酰CoA→柠檬酸→异柠檬酸(常规TCA酶)\u000b\u000b关键酶:异柠檬酸裂解酶+苹果酸合酶(常规TCA无)\u000b\u000b生理意义:\u000b①以二碳物(乙酰CoA)合成TCA环中的4C中间物→回补TCA\u000b②植物/微生物中脂肪转变为糖的唯一途径:\u000b脂肪酸→b-氧化→乙酰CoA→乙醛酸循环→苹果酸→OAA→糖异生→葡萄糖\u000b③动物无此循环→不能将脂肪转为糖(乙酰CoA两个C在TCA中以CO2排出)", "kp": "sugar1_s2_24"}, {"id": "sugar1_short_10", "modI": 1, "q": "简述糖异生(gluconeogenesis)绕过酵解三步不可逆反应的机制。", "a": "糖异生基本是酵解的逆过程,但有三步不可逆必须绕过:\u000b\u000b酵解步1: G→G-6-P(己糖激酶)\u000b绕过: G-6-P+H2O→G+Pi(葡萄糖-6-磷酸酶,肝/肾内质网)\u000b\u000b酵解步3: F-6-P→F-1,6-2P(PFK-1)\u000b绕过: F-1,6-2P+H2O→F-6-P+Pi(果糖-1,6-二磷酸酶,FBPase-1)\u000b\u000b酵解步10: PEP→丙酮酸(PK)\u000b绕过分两步:\u000b①丙酮酸+CO2+ATP→草酰乙酸+ADP+Pi(丙酮酸羧化酶,线粒体,生物素)\u000b②草酰乙酸→苹果酸(出线粒体)→OAA→PEP+CO2+GTP(PEPCK,胞质)\u000b\u000b能量消耗:\u000b酵解: 1G→2丙酮酸=净产2ATP\u000b糖异生: 2丙酮酸→1G=消耗6ATP(或GTP)\u000b净亏4ATP,保障代谢单向性。G-6-Pase仅在肝/肾有,肌肉无→肌肉糖原不能直接释G到血。", "kp": "sugar1_s1_17"}, {"id": "sugar1_short_11", "modI": 0, "q": "简述淀粉、糖原和纤维素结构的异同。", "a": "共同点:均为葡萄糖单元以糖苷键相连的同多糖。\u000b\u000b淀粉(植物):\u000b• 直链淀粉→a-1,4线性链无分支,螺旋结构\u000b• 支链淀粉→a-1,4+a-1,6分支,每25-30单位一分支\u000b\u000b糖原(动物):\u000b• a-1,4+a-1,6分支,每8-12单位一分支→高度分支化\u000b• 每链平均长度:外链12-14残基,内链5-6残基\u000b• 具无定形结构→易于快速攻击(多酶同时切多个末端)\u000b• 肝湿重~10%存储为糖原\u000b\u000b纤维素(植物):\u000b• b-1,4糖苷键(非a键)→产生刚性平面链\u000b• 无分支,相邻链通过分子间H键形成微纤维→高强度\u000b• 动物无纤维素酶(草食性动物靠共生菌产生)\u000b\u000b关键差异:分支度(糖原>支链淀粉>直链淀粉>纤维素);糖苷键类型(a-1,4 vs b-1,4)。", "kp": "sugar1_s0_15"}, {"id": "sugar1_short_12", "modI": 2, "q": "简述TCA循环的三步不可逆反应的调控机制。", "a": "TCA三个调控点(对应三个不可逆反应):\u000b\u000b①柠檬酸合酶:\u000b• 底物OAA和乙酰CoA↑→激活\u000b• NADH/ATP/柠檬酸↑→抑制(产物反馈)\u000b• 琥珀酰CoA积累→竞争性抑制\u000b\u000b②异柠檬酸脱氢酶(最重要调控点):\u000b• ADP↑→别构激活(低能荷信号)\u000b• NAD+↑→激活\u000b• ATP/NADH↑→抑制(高能荷信号)\u000b• Ca2+↑→激活(呼应肌肉收缩、心率等能量需求↑)\u000b\u000b③a-酮戊二酸脱氢酶系:\u000b• 与PDH类似,受磷酸化/去磷酸化调控\u000b• NADH/ATP/琥珀酰CoA↑→抑制(产物反馈)\u000b• Ca2+↑→激活\u000b\u000b总体调控逻辑:细胞能量状态(ATP/ADP比)决定TCA速度。\u000bATP↑→TCA↓(不需要产能);ADP↑→TCA↑(需要产能)。\u000b三条途径与呼吸链速率协调一致(通过NADH/ADP的共价调节)。", "kp": "sugar1_s2_7"}, {"id": "sugar1_short_13", "modI": 0, "q": "简述G-6-P在糖代谢中的枢纽地位。", "a": "G-6-P是葡萄糖进入细胞内后的第一个磷酸化产物,是糖代谢的中心分支点:\u000b\u000b三条主要去路:\u000b①→F-6-P→酵解(EMP)→产能(ATP+NADH)→各组织基本供能\u000b②→6-P-葡萄糖酸内酯→PPP→NADPH+5-P-核糖→合成代谢/核酸\u000b③→G-1-P→UDP-葡萄糖→糖原合成(储存)\u000b\u000b来源:\u000b• 葡萄糖被己糖激酶/葡糖激酶→G-6-P\u000b• 糖原降解→G-1-P→G-6-P\u000b• 糖异生→G-6-P→G(仅肝/肾可完成,释入血液)\u000b\u000b三条去路分配取决于:\u000b• 细胞能量需求(ATP/ADP比)→酵解\u000b• 还原力需求(NADPH)→PPP\u000b• 葡萄糖供应过剩→糖原储存\u000b\u000b己糖激酶受G-6-P反馈抑制;葡糖激酶(肝)不受→可持续摄G。\u000bG-6-PDH受NADPH反馈抑制→NADPH过剩时PPP↓。\u000bG-6-P是EMP/PPP的分水岭→代谢灵活调控。", "kp": "sugar1_s0_0"}], "calc": [{"id": "sugar1_calc_1", "modI": 2, "q": "计算1分子葡萄糖彻底氧化为CO2和H2O净产生多少ATP？(分别按苹果酸穿梭和甘油-3-磷酸穿梭系统计算)", "a": "苹果酸穿梭(肝/心肌):32 ATP; 甘油-3-磷酸穿梭(骨骼肌/神经):30 ATP", "steps": "【苹果酸穿梭(肝/肾/心肌):P/O≈2.5】\u000b• 酵解:G→2丙酮酸:净+2ATP+2NADH(c)→2NADH×2.5=5ATP(穿梭)\u000b• PDH:2×丙酮酸→2乙酰CoA+2NADH(m)→2×2.5=5ATP\u000b• TCA×2:2×(3NADH×2.5+1FADH2×1.5+1GTP)=2×10=20ATP\u000b• 总计:2+5+5+20=32ATP\u000b\u000b【甘油-3-磷酸穿梭(骨骼肌/神经):P/O≈1.5】\u000b• 酵解:2ATP+2NADH(c)→2×1.5=3ATP(穿梭)\u000b• PDH+TCA:5+20=25ATP(与上相同)\u000b• 总计:2+3+5+20=30ATP\u000b\u000b核心差异:2个胞质NADH→苹果酸穿梭(×2.5)=5ATP vs 甘油-3-P穿梭(×1.5)=3ATP\u000b所以不同组织ATP数:32(肝心肌)vs 30(骨骼肌神经)。", "kp": "sugar1_s2_21"}, {"id": "sugar1_calc_2", "modI": 1, "q": "计算糖酵解(EMP)中ATP的消耗和产生,说明净ATP数。", "a": "净产2ATP+2NADH", "steps": "消耗ATP(准备阶段):\u000b①G→G-6-P(己糖激酶): -1ATP\u000b③F-6-P→F-1,6-2P(PFK-1): -1ATP\u000b消耗合计:-2ATP\u000b\u000b产生ATP(贮能阶段):\u000b⑦1,3-BPG→3-PG(PGK): +1ATP×2个三碳=+2ATP\u000b⑩PEP→丙酮酸(PK): +1ATP×2个三碳=+2ATP\u000b\u000b产生合计:+4ATP\u000b\u000b净ATP=+4-2=+2ATP\u000b\u000b还需产生:2NADH(H+)→进入呼吸链\u000b• 苹果酸穿梭:2×2.5=5ATP\u000b• 甘油-3-P穿梭:2×1.5=3ATP\u000b\u000b酵解能量效率为有氧氧化的几分之一:\u000b有氧32ATP vs 酵解(乳酸发酵)2ATP→酵解效率极低但速度快。", "kp": "sugar1_s1_2"}, {"id": "sugar1_calc_3", "modI": 2, "q": "计算一轮TCA循环的ATP产量和总产能。", "a": "10 ATP/轮", "steps": "一轮TCA产生的还原力:\u000b①异柠檬酸→a-KG: NADH×1\u000b②a-KG→琥珀酰CoA: NADH×1\u000b③琥珀酸→延胡索酸: FADH2×1(SDH/复合物II)\u000b④苹果酸→OAA: NADH×1\u000b\u000b+1分子GTP(由琥珀酰CoA合成酶生成)\u000b\u000b能量换算:\u000b• 3NADH×2.5ATP/NADH=7.5ATP\u000b• 1FADH2×1.5ATP/FADH2=1.5ATP\u000b• 1GTP×1ATP/GTP=1ATP\u000b\u000b总计:7.5+1.5+1=10ATP/轮\u000b\u000b每分子葡萄糖→2乙酰CoA→2轮TCA→20ATP\u000b\u000b旧P/O计算(NADH=3,FADH2=2):\u000b3NADH×3+1FADH2×2+1=12ATP/轮(旧教材值,注意区分)", "kp": "sugar1_s2_17"}, {"id": "sugar1_calc_4", "modI": 2, "q": "计算1分子丙酮酸彻底氧化为CO2和H2O净产生的ATP数。", "a": "12.5 ATP", "steps": "①丙酮酸→乙酰CoA+CO2(PDH):\u000bNADH(m)×1→×2.5=2.5ATP\u000b\u000b②乙酰CoA→TCA(1轮):\u000b3NADH×2.5+1FADH2×1.5+1GTP=10ATP\u000b\u000b总计:2.5+10=12.5ATP/每丙酮酸\u000b\u000b每分子葡萄糖→2丙酮酸→2×12.5=25ATP(来自PDH+TCA)\u000b+酵解:2ATP+2NADH(c)→5或3ATP(穿梭)\u000b=30或32ATP(与整体计算一致)", "kp": "sugar1_s2_18"}, {"id": "sugar1_calc_5", "modI": 3, "q": "计算1分子葡萄糖-6-磷酸(G-6-P)完全进入PPP氧化阶段的ATP当量？(从NADPH的角度)", "a": "无直接ATP产生,但2分子NADPH约相当于5ATP当量", "steps": "PPP氧化阶段:\u000bG-6-P+2NADP++H2O→5-P-核酮糖+CO2+2NADPH\u000b\u000b无ATP直接产生(与EMP不同)\u000b但2NADPH是还原力:\u000b• 若用于脂肪酸合成:每个CH2-CO-→-CH2-CH2-需2NADPH\u000b• 若通过ATP生成:NADPH通过转氢酶→NADH→呼吸链约2.5ATP\u000b• 或经旁路:NADPH→GSSG→GSH(非产能)\u000b\u000b产能等价:2NADPH≈5ATP(苹果酸穿梭)或3ATP(甘油-3-P穿梭)\u000b但NADPH主要用于合成代谢而非产ATP→<5ATP实际可用\u000b\u000b与EMP比较:\u000bEMP:G→2ATP+2NADH(约5-7ATP等价)→总计约7-9ATP\u000bPPP氧化阶段:G-6-P→0ATP+2NADPH(约3-5ATP等价)\u000b→EMP产ATP多,PPP提供还原力(分工明确)", "kp": "sugar1_s3_2"}, {"id": "sugar1_calc_6", "modI": 0, "q": "计算糖原中1个葡萄糖残基彻底氧化产生的ATP数(与游离葡萄糖比较)。", "a": "31或29 ATP(比游离G多1ATP)", "steps": "糖原中的葡萄糖残基以G-1-P形式释放(磷酸化酶),不是游离G+ATP→G-6-P\u000b\u000b差异:游离G→G-6-P(己糖激酶):消耗1ATP\u000b     糖原G-1-P→G-6-P(变位酶):不消耗ATP\u000b\u000b所以糖原比游离G少消耗1个ATP\u000b\u000b计算:\u000b游离G有氧氧化:32ATP(苹果酸穿梭)\u000b糖原Glc残基有氧氧化:\u000b• G-1-P→G-6-P:0ATP消耗\u000b• 后续:酵解+PDH+TCA=30-32(取决于穿梭)\u000b• 总计:32+1=33? → 实际上31(用穿梭换算)\u000b\u000b详细:\u000b• 已跳过己糖激酶:省1ATP\u000b• 酵解:G-1-P→...→2丙酮酸:净产=完整酵解2ATP+省1ATP=3ATP\u000b• +2NADH(c)→5ATP(苹果酸穿梭)=8ATP\u000b• +PDH(5ATP)+TCA(20ATP)=33ATP\u000b→比游离G多1ATP(省了己糖激酶那步)\u000b→32+1=33? → 实际是31/32-29/30的精确计算", "kp": "sugar1_s0_4"}, {"id": "sugar1_calc_7", "modI": 2, "q": "论述三羧酸循环是四大物质代谢网络的中心枢纽。", "a": "TCA是糖/脂/蛋白质/核酸四大物质代谢的交汇点和中心枢纽", "steps": "TCA的中心枢纽地位体现在:\u000b\u000b①来自四大物质的碳骨架全部进入TCA:\u000b• 糖→EMP→丙酮酸→乙酰CoA→TCA\u000b• 脂肪→脂肪酸→b-氧化→乙酰CoA→TCA\u000b  甘油→磷酸丙糖→酵解→TCA\u000b• 蛋白质→氨基酸碳骨架→TCA五个入口:\u000b  Ala→丙酮酸, Asp→OAA, Glu→a-KG, Met/Val→琥珀酰CoA, Phe/Tyr→延胡索酸\u000b• 核酸→降解→产生碳骨架→可部分入TCA\u000b\u000b②TCA向外输出中间物满足合成需求:\u000b• 柠檬酸→脂肪酸(三羧酸移位酶)\u000b• a-KG→Glu家族aa,核苷酸\u000b• OAA→Asp家族aa\u000b• 琥珀酰CoA→卟啉色素(含血红素)\u000b\u000b③能量转换:\u000b• TCA的脱氢(NADH/FADH2)→呼吸链→氧化磷酸化→大量ATP\u000b• 是机体通过有机物分解获得能量最有效方式\u000b\u000b④关键调控:\u000b• 受NADH/ADP比调控→与呼吸链协调\u000b• 保证产能与需求匹配\u000b\u000b结论:TCA是代谢网络的一级中枢→任何物质代谢改变都会经TCA反映→生物维持稳态的关键途径", "kp": "sugar1_s2_23"}, {"id": "sugar1_calc_8", "modI": 1, "q": "论述糖酵解在不同生理条件下的调节机制。", "a": "酵解根据组织氧条件、能量需求和激素状态受精密调节", "steps": "糖酵解的核心调节点是三步不可逆反应:\u000b\u000b①己糖激酶:\u000b• 受G-6-P反馈抑制(产物)\u000b• 葡糖激酶(肝):Km高(10mM)→高G时摄糖;不受G-6-P抑制→可持续运转\u000b\u000b②PFK-1(最重要调控点!):\u000b• 别构抑制剂:ATP(高能荷信号)、柠檬酸(无氧排出的TCA产物)\u000b• 别构激活剂:AMP/ADP(低能荷信号)\u000b• F-2,6-BP(最强激活剂)→克服ATP/柠檬酸抑制\u000b  - 受胰岛素→激活PFK-2→F-2,6-BP↑→酵解↑\u000b  - 受胰高血糖素→抑制PFK-2→F-2,6-BP↓→酵解↓\u000b\u000b③丙酮酸激酶(PK):\u000b• 受F-1,6-BP前馈激活(酵解中间物↑→通路加速)\u000b• 受ATP/Ala抑制\u000b• 肝PK受磷酸化调控:胰高血糖素→PKA通路→PK磷酸化→活性↓→酵解↓\u000b\u000b不同条件:\u000b• 进食后(高G):F-2,6-BP↑→PFK-1激活→酵解↑\u000b• 饥饿:胰高血糖素→F-2,6-BP↓+PK↓→酵解↓→节约G供脑组织\u000b• 运动肌肉:AMP↑→PFK-1激活;Ca2+↑→丙酮酸脱氢酶激活\u000b• 缺氧/无氧:PFK-1+Pasteur效应→促进酵解代替TCA", "kp": "sugar1_s1_23"}], "term": [{"id": "sugar1_term_1", "modI": 0, "term": "异头碳(Anomeric Carbon)", "def": "①在环状单糖结构中,原始羰基碳(C=O)在环化后产生的新手性碳原子（定义）。②α异头物:异头C上的-OH与环末端的-CH2OH呈反式;β异头物:二者呈顺式（分类）。③异头物:因异头C上羟基位置不同形成的立体异构体（命名）。④变旋现象:α和β异头物在溶液中通过开链互变→比旋光度变化至平衡（特点）。⑤半缩醛羟基参与糖苷键后→不再有还原性;若不参与→保留还原性（重要性）。", "kps": "①定义(1分)②a/b分类(1分)③异头物概念(1分)④变旋现象(1分)⑤与还原性的关系(1分)", "kp": "sugar1_s0_9"}, {"id": "sugar1_term_2", "modI": 0, "term": "变旋现象(Mutarotation)", "def": "①单糖溶解后,其比旋光度随时间发生变化,最终达到恒定值的现象（定义）。②原因:α和β异头物在溶液中通过开链形式互变→α→开链→β→达到动态平衡（机制）。③葡萄糖平衡时成分:α-D-葡萄糖(约36%)+β-D-葡萄糖(约64%)+开链形式(<1%)（组成）。④影响因素:温度、pH、缓冲盐等→可改变平衡速率（影响因素）。⑤变旋反映了糖分子结构的动态性和环-链互变的存在（意义）。", "kps": "①定义(1分)②机制:开链互变(1分)③平衡组成(1分)④影响因素(1分)⑤意义(1分)", "kp": "sugar1_s0_9"}, {"id": "sugar1_term_3", "modI": 0, "term": "糖苷键(Glycosidic Bond)", "def": "①单糖分子半缩醛羟基与另一分子的羟基、氨基或巯基缩合形成的O/N/S-糖苷键（定义）。②由异头C通过糖苷键与其他基团连接→单糖残基固定在环式→不再有还原性（特点）。③分类:α-糖苷键(异头C上OH与环末端反式)和β-糖苷键(顺式)（分类）。④常见:α-1,4糖苷键(麦芽糖、淀粉)、β-1,4糖苷键(纤维二糖、纤维素)、α-1,6糖苷键(支链淀粉、糖原分支)（举例）。⑤糖苷酶专一水解特定类型的糖苷键→代谢多样性（意义）。", "kps": "①定义(1分)②半缩醛消失(1分)③a/b分类(1分)④3种常见类型(1分)⑤生理意义(1分)", "kp": "sugar1_s0_19"}, {"id": "sugar1_term_4", "modI": 0, "term": "还原糖(Reducing Sugar)", "def": "①具有游离半缩醛羟基→能将弱氧化剂(Fehling试剂/Benedict试剂)还原产生红色Cu2O沉淀的单糖或寡糖。②化学基础:游离醛基或半缩醛羟基→打开环式→露出醛基→具还原性。③检测原理:碱性铜试剂→还原糖将Cu2+→Cu+(砖红色)→Cu2O红色沉淀。④常见还原糖:所有单糖(Fru虽为酮糖但碱性异构化→醛糖)、麦芽糖、乳糖等含游离半缩醛的二糖。⑤无还原性:蔗糖(两个异头碳均参与糖苷键)、所有多糖(只有一个还原端,浓度极低)。", "kps": "①定义(1分)②化学基础(1分)③检测原理(1分)④举例(1分)⑤非还原糖举例(1分)", "kp": "sugar1_s0_10"}, {"id": "sugar1_term_5", "modI": 0, "term": "差向异构体(Epimer)", "def": "①同碳数、同构型(D/L系列)、仅一个C*的构型不同的两种糖互为差向异构体(特殊类型的非对映体)。②D-甘露糖是D-葡萄糖的C2差向异构体;D-半乳糖是D-葡萄糖的C4差向异构体(举例)。③所有其他C*(C3/C5)构型相同→两者在化学性质上差别小,但生化功能不同(酶识别差异)。④底物/产物:差向异构酶催化差向异构体间互变(如:5-P-核酮糖→5-P-木酮糖)。⑤完全对映体(L-葡萄糖)不是差向异构体(所有C*都不同)。", "kps": "①定义(1分)②Glc→Man(C2)/Gal(C4)(1分)③其他C*相同(1分)④酶催化互变(1分)⑤与对映体的区别(1分)", "kp": "sugar1_s0_5"}, {"id": "sugar1_term_6", "modI": 1, "term": "糖酵解/EMP途径(Glycolysis/EMP Pathway)", "def": "①无氧条件下,酶将葡萄糖分解为丙酮酸并释放ATP的过程（定义）。②3位德国科学家阐明:Embden-Meyerhof-Parnas→就此命名EMP途径（发现者）。③部位:细胞质。步骤:10步→准备阶段(前5步)+贮能阶段(后5步)（过程）。④产能:耗2ATP+产4ATP=净2ATP+2NADH(H+)（产能）。⑤三步不可逆反应(己糖激酶③/⑧/⑩)为关键调控点（调控）。⑥所有生物体普遍存在的核心代谢途径（普遍性）。", "kps": "①定义(1分)②EMP命名(1分)③10步两阶段(1分)④产能(1分)⑤三步不可逆调控(1分)⑥普遍性(1分)", "kp": "sugar1_s1_0"}, {"id": "sugar1_term_7", "modI": 1, "term": "底物水平磷酸化(Substrate-level Phosphorylation)", "def": "①高能底物(含高能磷酸/酰基键)将高能基团直接转移给ADP/GDP生成ATP/GTP的过程（定义）。②与氧化磷酸化不同→不依赖呼吸链、O2或质子梯度（与氧化磷酸化的区别）。③糖代谢中两处:酵解-1,3-BPG→3-PG(PGK,每G产2ATP);TCA-琥珀酰CoA→琥珀酸(琥珀酰CoA合成酶,每轮TCA产1ATP/GTP)（糖代谢中位置）。④关键特征:△G0'高能底物→可逆反应→总反应中占较小比例(酵解+S+TCA底物磷酸化仅4+2=6ATP vs 呼吸链26个 ATP)（特征）。⑤在无氧条件下是唯一生成ATP的方式（意义）。", "kps": "①定义(2分)②与氧化磷酸化区别(1分)③糖代谢两处(1分)④产能占比小(1分)⑤无氧下唯一产能方式(1分)", "kp": "sugar1_s1_18"}, {"id": "sugar1_term_8", "modI": 1, "term": "诱导契合(Induced Fit)", "def": "①酶与底物结合时,酶构象发生改变以精确匹配底物形状的学说（定义）。②提出者Koshland(1958):酶活性中心不是预先形成的刚性孔穴,与底物结合才产生构象变化（理论）。③经典范例:己糖激酶与D-葡萄糖结合→活性位点包围底物→排开水分→促进磷酸转移反应（举例）。④与锁钥模型的区别:酶构象有柔性→优化结合→催化效率大大提升（区别）。⑤对所有酶的底物特异性识别和催化机制有普遍意义（意义）。", "kps": "①定义(1分)②Koshland 1958(1分)③己糖激酶经典例子(1分)④与锁钥模型区别(1分)⑤普遍意义(1分)", "kp": "sugar1_s1_6"}, {"id": "sugar1_term_9", "modI": 1, "term": "Cori循环/乳酸循环(Cori Cycle)", "def": "①肌肉与肝脏之间通过乳酸和葡萄糖的相互转化形成的代谢循环（定义）。②过程:肌肉酵解(无氧)→丙酮酸→乳酸(LDH)→进入血液→肝脏→乳酸→丙酮酸→糖异生→葡萄糖→血液→肌肉(重新酵解)（过程）。③能量:肌肉酵解1G净产2ATP,肝脏合成1G消耗6ATP→净亏4ATP（能量收支）。④生理意义:①回收废物乳酸(解毒)→②回收碳骨架(糖异生)→③紧急供能(无氧条件下维持血糖)（意义）。⑤乳酸过量→酸中毒,Cori循环受血乳酸、胰岛素和肾上腺素调控（调控）。", "kps": "①定义(1分)②完整过程(2分)③能量收支(1分)④三大生理意义(1分)⑤调控(1分)", "kp": "sugar1_s1_24"}, {"id": "sugar1_term_10", "modI": 2, "term": "丙酮酸脱氢酶系(PDH Complex)", "def": "①催化丙酮酸→乙酰CoA+CO2+NADH的不可逆多酶复合体（定义）。②3种酶:E1-丙酮酸脱氢酶(24个亚基,TPP辅酶)、E2-二氢硫辛酰转乙酰基酶(24个亚基,硫辛酸辅基)、E3-二氢硫辛酰脱氢酶(12个亚基,FAD辅酶)（组成）。③5种辅因子:TPP/E2辅基硫辛酸/FAD/NAD+/CoA（辅因子）。④部位:线粒体基质。反应不可逆→连接酵解和TCA的关键桥梁（功能）。⑤调控:磷酸化(PDH激酶磷酸化E1→失活)/去磷酸化(PDH磷酸酶→激活)→受ATP/NADH/Ca2+调控（调控）。⑥与a-KG脱氢酶系高度相似(同样的E1/E2/E3架构+5辅酶)（相关性）。", "kps": "①定义(1分)②3种酶(1分)③5辅因子(1分)④连接酵解/TCA(1分)⑤磷酸化调控(1分)⑥与a-KG脱氢酶相似性(1分)", "kp": "sugar1_s2_2"}, {"id": "sugar1_term_11", "modI": 2, "term": "三羧酸循环(TCA Cycle/Krebs Cycle)", "def": "①乙酰CoA在线粒体基质经一系列氧化脱羧→生成CO2+H2O+大量能量的代谢循环（定义）。②发现者Hans Krebs,1953年诺贝尔化学奖（发现）。③8步反应:柠檬酸→异柠檬酸→a-KG→琥珀酰CoA→琥珀酸→延胡索酸→苹果酸→OAA→回到柠檬酸（过程）。④初次反应:乙酰CoA+OAA→柠檬酸(合酶,不可逆第一步)（启动）。⑤产能:每轮→3NADH+1FADH2+1GTP≈10ATP（产能）。⑥三步不可逆反应(柠檬酸合酶/异柠檬酸脱氢酶/a-KG脱氢酶)为三大调控点（调控）。", "kps": "①定义(1分)②Krebs 1953(1分)③8步(1分)④启动(1分)⑤产能(1分)⑥三调控点(1分)", "kp": "sugar1_s2_5"}, {"id": "sugar1_term_12", "modI": 2, "term": "乙醛酸循环(Glyoxylate Cycle)", "def": "①TCA循环的支路→经异柠檬酸裂解酶和苹果酸合酶两步绕过两个脱羧步→净合成4C化合物（定义）。②部位:植物乙醛酸小体和微生物→动物体不存在（分布）。③关键酶:异柠檬酸裂解酶(异柠檬酸→乙醛酸+琥珀酸)和苹果酸合酶(乙醛酸+乙酰CoA→苹果酸+CoA)（关键酶）。④意义:以2C物(乙酰CoA)合成TCA 4C中间物→回补TCA;植物/微生物使脂肪→糖成为可能（意义）。⑤动物无此循环→不能脂→糖→乙酰CoA只能走向TCA(两个C以CO2排出)（动物限制）。", "kps": "①定义(1分)②植物/微生物(1分)③2个关键酶(1分)④总体意义(1分)⑤动物无-不可脂-糖(1分)", "kp": "sugar1_s2_24"}, {"id": "sugar1_term_13", "modI": 3, "term": "磷酸戊糖途径(PPP/HMP)", "def": "①G-6-P经氧化阶段脱氢脱羧和分子重排→产生NADPH和5-P-核糖的代谢支路（定义）。②部位:细胞质。G-6-PDH为关键限速酶→受NADPH反馈抑制（限速酶）。③氧化阶段:2步脱氢→产2NADPH+1CO2+5-P-核酮糖→异构/差向→5-P-核糖和5-P-木酮糖（氧化阶段）。④非氧化阶段:转酮酶(TPP,移2C)+转醛酶(移3C)→分子重排→总6C5⇌5C6可逆转换→再生G-6-P（非氧化阶段）。⑤三大生理意义:①NADPH(合成代谢还原力);②5-P-核糖(核酸合成前体);③各种单糖来源(适应不同组织需求)（意义）。", "kps": "①定义(1分)②G-6-PDH限速(1分)③氧化阶段(1分)④非氧化阶段(1分)⑤三大生理意义(1分)", "kp": "sugar1_s3_0"}, {"id": "sugar1_term_14", "modI": 0, "term": "糖原磷酸化酶(Glycogen Phosphorylase)", "def": "①催化糖原非还原端a-1,4糖苷键磷酸解→产生G-1-P的酶（定义）。②反应:糖原(n残基)+Pi→糖原(n-1残基)+G-1-P,不可逆（反应）。③辅酶:PLP(磷酸吡哆醛)→不与底物直接作用,而是稳定酶构象（辅酶）。④作用范围:处理约90%的糖原残基→从非还原端逐个切除Glc→直到距a-1,6分支点4个残基处停止（作用范围）。⑤调控:磷酸化调控→被肾上腺素/胰高血糖素通过cAMP/PKA级联→磷酸化→激活（调控）。⑥剩余10%由糖基转移酶+脱支酶完成（配合）。", "kps": "①定义(1分)②反应式(1分)③PLP辅酶(1分)④90%+剩余(1分)⑤磷酸化调控(1分)⑥配合脱支酶(1分)", "kp": "sugar1_s0_21"}, {"id": "sugar1_term_15", "modI": 1, "term": "生醇发酵(Alcoholic Fermentation)", "def": "①酵母在无氧条件下将葡萄糖分解为乙醇和CO2并再生NAD+的过程（定义）。②两步反应:①丙酮酸脱羧酶(PDC,TPP辅酶)→乙醛+CO2;②乙醇脱氢酶(ADH)→乙醇+NAD+→NAD+再生维持酵解（过程）。③总反应:G+2ADP+2Pi→2乙醇+2CO2+2ATP+2H2O（总反应式）。④关键:再生NAD+→保证酵解持续运行→提供ATP→使酵母在无氧下生存（生理意义）。⑤与乳酸发酵对比:共同点→再生NAD+;不同点→产物不同(乙醇vs乳酸),CO2出现(酵母才有)（对比）。", "kps": "①定义(1分)②两步过程(1分)③总反应式(1分)④NAD+再生(1分)⑤与乳酸发酵对比(1分)", "kp": "sugar1_s1_22"}, {"id": "sugar1_term_16", "modI": 0, "term": "同多糖vs杂多糖(Homopolysaccharide vs Heteropolysaccharide)", "def": "①同多糖:由相同单糖基构成的多糖(例如淀粉仅含葡萄糖a-1,4+a-1,6键,糖原、纤维素、几丁质均为同多糖)（定义+举例）。②杂多糖:由不同单糖基构成的多糖(例如透明质酸含GlcN/AcGlcN/GlcNAc,硫酸软骨素/肝素等)（定义+举例）。③功能差异:同多糖→储能(淀粉/糖原)+结构(纤维素/几丁质);杂多糖→细胞间基质/润滑剂/细胞识别(糖胺聚糖家族)（功能）。④降解:不同糖苷酶水解不同键→同多糖降解简单(单一酶);杂多糖降解复杂(多种酶协同)（降解）。⑤分析:组成分析→酸/酶水解→色谱/质谱→鉴别同/杂多糖（分析）。", "kps": "①同多糖定义+举例(1分)②杂多糖定义+举例(1分)③功能差异(1分)④降解差异(1分)⑤分析方法(1分)", "kp": "sugar1_s0_14"}, {"id": "sugar1_term_17", "modI": 0, "term": "手性碳原子(Chiral Carbon, C*)", "def": "①连接4个不同原子或基团的碳原子→失去对称性,具有两种光学异构体(互为镜像,不能重叠)（定义）。②重要性:单糖的多手性→立体异构体数=2^n个(n=C*数)→葡萄糖的4个C*→16种立体异构体（重要性）。③与D/L构型关系:以距羰基最远的C*的OH方向判定构型→OH在右=D型（判定）。④差向异构体:同碳数、仅一个C*构型不同的糖→互差向→化学反应几乎相同→酶反应因位阻不同而有差异（差向异构体）。⑤酶催化识别:C*构型决定了哪个酶可催化该糖→差向异构体被不同酶识别→生物活性差异很大（酶识别）。", "kps": "①C*定义(1分)②2^n法则(1分)③D/L判定(1分)④差向异构体(1分)⑤酶识别差异(1分)", "kp": "sugar1_s0_3"}, {"id": "sugar1_term_18", "modI": 0, "term": "构型vs构象(Configuration vs Conformation)", "def": "①构型:原子在空间的相对分布和排列,改变必须断裂共价键(如D型↔L型→断键重连)→构型互变需化学键断裂（定义）。②构象:绕单键旋转产生的不同空间排列,不涉及共价键断裂(如椅式↔船式仅绕单键旋转)（定义）。③糖类构象:六元糖以椅式为主(平伏键多→空间位阻小→最稳定)→船式(有立体矛盾→高能量→溶液中极少)（实例）。④代谢活性:仅具有特定构型和构象的糖才能进入酶活性中心→糖类代谢对立体化学严格辨别（说明）。⑤构型/构象固定了糖与其他分子的相互作用方式(如受体、酶等)（意义）。", "kps": "①构型定义(1分)②构象定义(1分)③糖类构象椅式/船式(1分)④代谢对立体化学的要求(1分)⑤意义(1分)", "kp": "sugar1_s0_3"}, {"id": "sugar1_term_19", "modI": 2, "term": "糖异生(Gluconeogenesis)", "def": "①由非糖物质(乳酸/甘油/生糖氨基酸等)合成葡萄糖的过程（定义）。②部位:肝脏(主要)+肾脏皮质（部位）。③需绕过酵解3个不可逆步(①G-6-P→G(G-6-Pase)、③F-1,6-BP→F-6-P(FBPase-1)、⑩丙酮酸→PEP→OAA(两个酶:丙酮酸羧化酶和PEPCK))（绕道机制）。④能量消耗:2丙酮酸→1G消耗6ATP(≠酵解产2ATP→净亏4ATP→保证代谢单向性)（能量）。⑤基质:主要基质→乳酸(Cori循环)、甘油、生糖氨基酸;脂肪→乙酰CoA→动物不能糖异生(无乙醛酸循环)（限制）。", "kps": "①定义(1分)②肝/肾(1分)③绕过三步不可逆(2分)④能量消耗6ATP(1分)⑤基质来源(1分)", "kp": "sugar1_s2_25"}, {"id": "sugar1_term_20", "modI": 2, "term": "柠檬酸合酶(Citrate Synthase)", "def": "①催化TCA第一步不可逆反应:乙酰CoA+OAA+H2O→柠檬酸+CoA+H+（定义）。②机制:乙酰CoA甲基脱H+→碳负离子亲核攻击OAA羰基C→C-C键形成→柠檬酰-CoA→水解→柠檬酸+CoA（机制）。③特点:释放大量自由能→△G0'极其负→不可逆→TCA第一个调控点（特点）。④调控:受NADH/ATP/柠檬酸的反馈抑制,受ADP/NAD+激活（调控）。⑤意义:此步决定了乙酰CoA→TCA的速率→控制整个有氧氧化的通量（意义）。", "kps": "①反应式(1分)②机制(1分)③△G极负(1分)④调控(1分)⑤TCA速率控制(1分)", "kp": "sugar1_s2_7"}, {"id": "sugar1_term_21", "modI": 1, "term": "2,3-二磷酸甘油酸(2,3-BPG)", "def": "①1,3-BPG的异构体,由变位酶催化产生（来源）。②结构:2,3-BPG的C2磷酸为高能键→可降解产生ATP,但在RBC中不降解→积累到高水平(5mM)（结构特点）。③核心功能:与Hb β亚基结合→稳定T态(deoxyHb)→O2解离曲线右移→P50(氧合饱和度50%的氧分压)升高→有利于组织O2释放（功能）。④高山/缺氧/贫血→RBC中2,3-BPG水平↑→组织可用O2↑→适应机制（调控）。⑤RBC中PPP失调→NADPH↓→GSH↓→2,3-BPG因积累而发挥代偿O2运输（与PPP的联系）。", "kps": "①来源(1分)②结构特点(1分)③与Hb结合→O2释放(2分)④高山适应(1分)⑤与PPP联系(1分)", "kp": "sugar1_s1_14"}, {"id": "sugar1_term_22", "modI": 2, "term": "苹果酸-天冬氨酸穿梭(Malate-Aspartate Shuttle)", "def": "①胞质NADH还原当量转运到线粒体的主要穿梭系统之一（定义）。②部位:肝、肾、心肌（分布）。③过程:胞质苹果酸→进入线粒体→MDH→OAA+NADH(m)→NADH→复合物I;OAA→Asp出→再转化为苹果酸完成循环（过程）。④能量:每胞质NADH→1分子线粒体NADH→复合物I→P/O≈2.5ATP（产能）。⑤对比:甘油-3-P穿梭(肌肉/神经)→胞质NADH→FADH2→CoQ→P/O≈1.5ATP（对比）。", "kps": "①定义(1分)②肝/肾/心肌(1分)③过程(1分)④P/O≈2.5(1分)⑤与甘油-3-P穿梭对比(1分)", "kp": "sugar1_s2_20"}, {"id": "sugar1_term_23", "modI": 3, "term": "G-6-PDH缺陷症(G6PD Deficiency)", "def": "①G-6-P脱氢酶(PPP氧化阶段限速酶)缺陷导致的X连锁遗传性溶血性贫血（定义+遗传）。②机制:G-6-PDH缺陷→PPP受阻→NADPH↓→GSSG→GSH转化受阻→GSH↓→H2O2积累↑→膜脂过氧化→膜蛋白交联→红细胞脆性↑→溶血（机制）。③诱因:食蚕豆(含嘧啶核苷)、服用氧化性药物(伯氨喹/喹啉/磺胺)→加重NADPH短缺→急性溶血危象（诱因）。④流行:全球约4亿人受影响→非洲/地中海/东南亚最普遍→与疟疾保护有关(镰状细胞/霍乱等与G6PDH缺陷的地理重叠)（流行病学）。⑤临床:新生儿黄疸、急性溶血性贫血、慢性非球形红细胞溶血性贫血→新生儿G6PDH筛查(采血测定)（临床）。", "kps": "①定义+遗传(1分)②分子机制(2分)③诱因(1分)④流行病学(1分)⑤临床意义(1分)", "kp": "sugar1_s3_1"}, {"id": "sugar1_term_24", "modI": 0, "term": "半缩醛羟基(Hemiacetal Hydroxyl)", "def": "①在单糖环化中,原羰基C(C=O)通过与分子内羟基反应,生成的异头碳上的OH（定义）。②产生:醛基与羟基分子内脱水→半缩醛→异头碳形成新C*→OH为该半缩醛羟基（产生）。③性质:半缩醛羟基反应性高→可与另一分子的OH/NH等脱水→形成糖苷键→此羟基消失→单糖失去还原性（性质）。④游离半缩醛→开环→露出醛基→具有还原性→检测还原糖时依赖此反应（与还原性的关系）。⑤重要性:半缩醛羟基的参与与否决定了糖苷键结构和多糖的表征→决定了糖类的物理/化学/生物性质（重要性）。", "kps": "①定义(1分)②产生机制(1分)③与糖苷键关系(1分)④与还原性关系(1分)⑤重要性(1分)", "kp": "sugar1_s0_9"}], "preview": null, "appcards": []};